module.exports = [{"id":"0001","name":"3/4 sit-up","nameZh":"3/4 仰卧起坐","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0001-2gPfomN.jpg","gifPath":"exercises/videos/0001-2gPfomN.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0002","name":"45° side bend","nameZh":"45° 体侧屈","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0002-Hy9D21L.jpg","gifPath":"exercises/videos/0002-Hy9D21L.gif","instructionSteps":["双脚分开与肩同宽站立，双臂在身体两侧笔直向下伸展。","保持背部挺直，核心肌群参与，慢慢将躯干向一侧弯曲，将手向膝盖方向放低。","在底部停顿片刻，然后慢慢回到起始位置。","在另一侧重复。","继续交替进行所需的重复次数。"]},{"id":"0003","name":"air bike","nameZh":"空中蹬车","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0003-1ZFqTDN.jpg","gifPath":"exercises/videos/0003-1ZFqTDN.gif","instructionSteps":["平躺，双手放在脑后。","将双腿抬离地面，并以 90 度角弯曲膝盖。","将右肘靠近左膝盖，同时伸直右腿。","返回起始位置，在另一侧重复该动作，将左肘拉向右膝盖，同时伸直左腿。","继续交替进行蹬踏动作，达到所需的重复次数。"]},{"id":"0006","name":"alternate heel touchers","nameZh":"交替触踵","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0006-qaZVsGk.jpg","gifPath":"exercises/videos/0006-qaZVsGk.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双臂伸直至两侧，与地面平行。","收紧腹肌，将肩膀抬离地面，并将右手伸向右脚跟。","返回起始位置并在左侧重复，将左手伸向左脚跟。","继续交替进行所需的重复次数。"]},{"id":"0007","name":"alternate lateral pulldown","nameZh":"交替侧向下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0007-4IKbhHV.jpg","gifPath":"exercises/videos/0007-4IKbhHV.gif","instructionSteps":["坐在缆绳机上，背部挺直，双脚平放在地面上。","正手握住手柄，握距略宽于肩宽。","稍微向后倾斜，将手柄拉向胸部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0009","name":"assisted chest dip (kneeling)","nameZh":"辅助胸部臂屈伸 (跪姿)","equipment":"leverage machine","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0009-PAgTVaK.jpg","gifPath":"exercises/videos/0009-PAgTVaK.gif","instructionSteps":["将机器调整到您想要的高度，并将膝盖固定在垫子上。","手掌朝下，抓住手柄，双臂完全伸展。","弯曲肘部降低身体，直到上臂与地板平行。","暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0010","name":"assisted hanging knee raise with throw down","nameZh":"辅助悬垂提膝带下摆","equipment":"assisted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0010-8K0w2yA.jpg","gifPath":"exercises/videos/0010-8K0w2yA.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","收紧核心并将膝盖抬向胸部，保持双腿并拢。","一旦你的膝盖与胸部齐平，爆发性地将你的双腿向地面扔去，将它们完全伸展。","让双腿向后摆动并重复该动作达到所需的重复次数。"]},{"id":"0011","name":"assisted hanging knee raise","nameZh":"辅助悬垂提膝","equipment":"assisted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0011-03lzqwk.jpg","gifPath":"exercises/videos/0011-03lzqwk.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","调动你的核心肌肉，将膝盖抬向胸部，弯曲臀部和膝盖。","在动作的最高点暂停片刻，挤压腹肌。","慢慢地将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0012","name":"assisted lying leg raise with lateral throw down","nameZh":"辅助仰卧抬腿带侧向下摆","equipment":"assisted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0012-UGhRD1A.jpg","gifPath":"exercises/videos/0012-UGhRD1A.gif","instructionSteps":["平躺，双腿伸展，双臂放在身体两侧。","将双手放在臀部下方以获得支撑。","收紧腹肌，将双腿抬离地面，保持伸直。","双腿并拢的同时，将它们降低到一侧，直到离地几英寸。","暂停片刻，然后抬起双腿回到起始位置。","到另一侧重复该动作。","继续交替进行所需的重复次数。"]},{"id":"0013","name":"assisted lying leg raise with throw down","nameZh":"辅助仰卧抬腿带下摆","equipment":"assisted","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0013-VX5YKR5.jpg","gifPath":"exercises/videos/0013-VX5YKR5.gif","instructionSteps":["平躺，双腿伸展，双臂放在身体两侧。","将双手放在臀部下方以获得支撑。","启动你的核心并将双腿抬离地面，保持伸直。","抬起双腿，直到它们垂直于地面。","将双腿放低回到起始位置。","同时，将双腿向地面放下，保持伸直。","将双腿抬回到起始位置。","重复所需的重复次数。"]},{"id":"0014","name":"assisted motion russian twist","nameZh":"辅助动态俄罗斯转体","equipment":"medicine ball","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0014-r7cT9YD.jpg","gifPath":"exercises/videos/0014-r7cT9YD.gif","instructionSteps":["坐在地上，膝盖弯曲，双脚平放在地板上。","双手将健身球放在胸前。","稍微向后倾斜，收紧腹肌并保持背部挺直。","慢慢地将你的躯干向右扭转，将健身球移向身体的右侧。","暂停片刻，然后将躯干向左扭转，将健身球移向身体左侧。","继续交替进行所需的重复次数。"]},{"id":"0015","name":"assisted parallel close grip pull-up","nameZh":"辅助平行窄距引体向上","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/0015-vrhHa6D.jpg","gifPath":"exercises/videos/0015-vrhHa6D.gif","instructionSteps":["将机器调整到您想要的重量和高度。","将双手紧紧握在双杠上，手掌相对。","悬挂在杠上，双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向杠铃，保持肘部靠近身体。","继续拉，直到下巴高于杠铃。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0016","name":"assisted prone hamstring","nameZh":"辅助俯卧腘绳肌","equipment":"assisted","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0016-VedGSby.jpg","gifPath":"exercises/videos/0016-VedGSby.gif","instructionSteps":["脸朝下躺在垫子或长凳上，双腿完全伸展。","找一个伙伴或使用阻力带来固定脚踝。","收紧腿筋，将双腿抬向臀肌，保持膝盖伸直。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0017","name":"assisted pull-up","nameZh":"辅助引体向上","equipment":"leverage machine","bodyPart":"back","target":"lats","imagePath":"exercises/images/0017-kiJ4Z2K.jpg","gifPath":"exercises/videos/0017-kiJ4Z2K.gif","instructionSteps":["将机器调整至您所需的体重和高度设置。","正手握住手柄，握距略宽于肩宽。","双臂完全伸展，双脚离开地面。","收紧背部肌肉，将身体拉向手柄，保持肘部靠近身体。","继续拉，直到下巴位于手柄上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0018","name":"assisted standing triceps extension (with towel)","nameZh":"辅助站姿肱三头肌伸展 (带毛巾)","equipment":"assisted","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0018-7HcfMBP.jpg","gifPath":"exercises/videos/0018-7HcfMBP.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住毛巾放在脑后。","保持肘部靠近耳朵，上臂保持静止。","慢慢向上伸展前臂，在顶部挤压三头肌。","暂停片刻，然后慢慢将毛巾放回起始位置。","重复所需的重复次数。"]},{"id":"0019","name":"assisted triceps dip (kneeling)","nameZh":"辅助肱三头肌臂屈伸 (跪姿)","equipment":"leverage machine","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0019-J60bN17.jpg","gifPath":"exercises/videos/0019-J60bN17.gif","instructionSteps":["将机器调整到您想要的重量和高度。","跪在面向机器的垫子上，双手握住手柄。","弯曲肘部降低身体，保持背部挺直并靠近机器。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0020","name":"balance board","nameZh":"平衡板","equipment":"body weight","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0020-xAySMB0.jpg","gifPath":"exercises/videos/0020-xAySMB0.gif","instructionSteps":["将平衡板放在平坦的表面上。","用一只脚踩在平衡板上，确保其居中。","慢慢地将体重转移到平衡板上的脚上，保持核心肌群参与。","在保持该姿势所需的时间内保持平衡和稳定。","用另一只脚重复该练习。"]},{"id":"0022","name":"barbell pullover to press","nameZh":"杠铃仰卧屈臂上拉至推举","equipment":"barbell","bodyPart":"back","target":"lats","imagePath":"exercises/images/0022-znLogoF.jpg","gifPath":"exercises/videos/0022-znLogoF.gif","instructionSteps":["平躺在长凳上，头朝一端，双脚着地。","旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。","保持手臂伸直，以弧形动作将杠铃降低到脑后，直到感觉到背阔肌有拉伸感。","暂停片刻，然后反转动作，将杠铃推回到胸部上方的起始位置。","重复所需的重复次数。"]},{"id":"0023","name":"barbell alternate biceps curl","nameZh":"杠铃交替肱二头肌弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0023-Yza7XrQ.jpg","gifPath":"exercises/videos/0023-Yza7XrQ.gif","instructionSteps":["站直，双脚分开与肩同宽，每只手握住一个杠铃，手掌朝前。","保持上臂静止，在弯举哑铃时呼气，同时收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢开始将杠铃放回起始位置。","重复所需的重复次数，交替手臂。"]},{"id":"0024","name":"barbell bench front squat","nameZh":"杠铃凳前蹲","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0024-Y7YcmIJ.jpg","gifPath":"exercises/videos/0024-Y7YcmIJ.gif","instructionSteps":["首先站立，双脚分开与肩同宽，将杠铃放在上胸部，锁骨下方。","正手握住杠铃，保持肘部向上，上臂与地面平行。","弯曲膝盖和臀部，将身体降低到蹲姿，保持背部挺直，挺胸。","在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。","重复所需的重复次数。"]},{"id":"0025","name":"barbell bench press","nameZh":"杠铃卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0025-EIeI8Vf.jpg","gifPath":"exercises/videos/0025-EIeI8Vf.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","将杠铃慢慢降低到胸部，保持肘部内收。","当杠铃触及胸部时暂停片刻。","伸展双臂，将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0026","name":"barbell bench squat","nameZh":"杠铃凳上深蹲","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0026-W9pFVv1.jpg","gifPath":"exercises/videos/0026-W9pFVv1.gif","instructionSteps":["将杠铃放在深蹲架上，与胸部同高。","背对架子站立，双脚与肩同宽。","弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。","正手握住杠铃，握距略宽于肩宽。","将杠铃从架子上提起并向后退一步，确保双脚仍与肩同宽。","降低身体蹲下，保持膝盖与脚趾在一条线上。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0027","name":"barbell bent over row","nameZh":"杠铃俯身划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0027-eZyBC3j.jpg","gifPath":"exercises/videos/0027-eZyBC3j.gif","instructionSteps":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","臀部向前弯曲，同时保持背部挺直、挺胸。","正手握住杠铃，双手间距略宽于肩宽。","通过收缩肩胛骨并挤压背部肌肉，将杠铃拉向下胸部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0028","name":"barbell clean and press","nameZh":"杠铃翻举推举","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0028-SGY8Zui.jpg","gifPath":"exercises/videos/0028-SGY8Zui.gif","instructionSteps":["双脚分开与肩同宽站立，杠铃放在你面前的地板上。","弯曲膝盖并以臀部为铰链降低并用正手握住杠铃，双手分开略宽于肩宽。","通过脚后跟发力，伸展臀部和膝盖，将杠铃抬离地板，使其靠近身体。","当杠铃到达大腿时，爆发性伸展臀部，耸肩，并将杠铃拉向胸部。","当杠铃到达胸部高度时，迅速将其降至肩部水平，肘部向前，手掌朝上。","从接球位置开始，伸展双臂并将杠铃笔直向上推，将杠铃压过头顶。","将杠铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0029","name":"barbell clean-grip front squat","nameZh":"杠铃翻举-握前蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0029-qi996YS.jpg","gifPath":"exercises/videos/0029-qi996YS.gif","instructionSteps":["首先，双脚分开与肩同宽，将杠铃放在上胸部，肘部向前。","弯曲膝盖并将臀部向后推，降低身体，就像坐在椅子上一样。","下降时保持挺胸、背部挺直，确保膝盖不超过脚趾。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后用脚跟推动站起来，伸展臀部和膝盖。","重复所需的重复次数。"]},{"id":"0030","name":"barbell close-grip bench press","nameZh":"杠铃窄距卧推","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0030-J6Dx1Mu.jpg","gifPath":"exercises/videos/0030-J6Dx1Mu.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","紧紧握住杠铃，握距略窄于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部靠近身体。","当杠铃触及胸部时暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"0031","name":"barbell curl","nameZh":"杠铃弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0031-25GPyDY.jpg","gifPath":"exercises/videos/0031-25GPyDY.gif","instructionSteps":["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝前。","保持肘部靠近躯干，在弯举哑铃时呼气，同时收缩二头肌。","继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0032","name":"barbell deadlift","nameZh":"杠铃硬拉","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0032-ila4NZS.jpg","gifPath":"exercises/videos/0032-ila4NZS.gif","instructionSteps":["双脚分开与肩同宽站立，杠铃放在你面前的地面上。","弯曲膝盖并以臀部为铰链，降低躯干，正手握住杠铃，双手分开略宽于肩宽。","当你通过脚后跟将杠铃抬离地面时，保持背部挺直，胸部抬起，伸展臀部和膝盖。","当你站直时，挤压你的臀部并保持你的核心参与。","弯曲臀部和膝盖，将杠铃放回地面，保持背部挺直。","重复所需的重复次数。"]},{"id":"0033","name":"barbell decline bench press","nameZh":"杠铃下斜卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0033-GrO65fd.jpg","gifPath":"exercises/videos/0033-GrO65fd.gif","instructionSteps":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","正手握住杠铃，握距略宽于肩宽。","松开杠铃，慢慢将其降低到胸部，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0034","name":"barbell decline bent arm pullover","nameZh":"杠铃下斜屈臂仰卧屈臂上拉","equipment":"barbell","bodyPart":"back","target":"lats","imagePath":"exercises/images/0034-hMEptv0.jpg","gifPath":"exercises/videos/0034-hMEptv0.gif","instructionSteps":["躺在倾斜的长凳上，头部低于臀部，双脚固定。","旋前握住杠铃（手掌背向您），并将手臂伸直至胸部上方。","有控制地将杠铃降低到头后，保持手臂稍微弯曲。","暂停片刻，然后收缩背阔肌，将杠铃抬回到起始位置。","重复所需的重复次数。"]},{"id":"0035","name":"barbell decline close grip to skull press","nameZh":"杠铃下斜窄距至碎颅推举","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0035-LMGXZn8.jpg","gifPath":"exercises/videos/0035-LMGXZn8.gif","instructionSteps":["躺在下斜长凳上，头低于脚，紧紧握住杠铃。","弯曲肘部，将杠铃向前额降低，保持上臂静止。","暂停片刻，然后伸展双臂将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0036","name":"barbell decline wide-grip press","nameZh":"杠铃下斜宽距推举","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0036-hl8DUh8.jpg","gifPath":"exercises/videos/0036-hl8DUh8.gif","instructionSteps":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","宽握距抓住杠铃，握距略宽于肩宽。","将杠铃降低到胸部，保持肘部向两侧伸出。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"0037","name":"barbell decline wide-grip pullover","nameZh":"杠铃下斜宽距仰卧屈臂上拉","equipment":"barbell","bodyPart":"back","target":"lats","imagePath":"exercises/images/0037-Hj4FOCd.jpg","gifPath":"exercises/videos/0037-Hj4FOCd.gif","instructionSteps":["躺在倾斜的长凳上，头部低于臀部，双脚固定。","宽握距握住杠铃，并将双臂伸直至胸部上方。","有控制地将杠铃降低到头后，保持手臂伸直。","暂停片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"]},{"id":"0038","name":"barbell drag curl","nameZh":"杠铃拖拽弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0038-IENzBdA.jpg","gifPath":"exercises/videos/0038-IENzBdA.gif","instructionSteps":["双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。","让杠铃悬挂在大腿前面，与手臂保持一定距离。","保持上臂静止，通过收缩二头肌将杠铃向上卷曲至胸部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0039","name":"barbell front chest squat","nameZh":"杠铃前胸部深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0039-IeTIEqg.jpg","gifPath":"exercises/videos/0039-IeTIEqg.gif","instructionSteps":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在胸前，双手与肩同宽，肘部向前。","当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0040","name":"barbell front raise and pullover","nameZh":"杠铃前平举和仰卧屈臂上拉","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0040-33AzZeV.jpg","gifPath":"exercises/videos/0040-33AzZeV.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。","保持双臂伸直，将杠铃举至身前，直至达到肩膀高度。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","接下来，将杠铃放低到头后，保持手臂伸直。","在底部停顿片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"]},{"id":"0041","name":"barbell front raise","nameZh":"杠铃前平举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0041-b2Uoz54.jpg","gifPath":"exercises/videos/0041-b2Uoz54.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃于大腿前方。","保持手臂伸直，向前向上举起杠铃，直至达到肩部水平。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0042","name":"barbell front squat","nameZh":"杠铃前蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0042-zG0zs85.jpg","gifPath":"exercises/videos/0042-zG0zs85.gif","instructionSteps":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在肩膀前面，将其放在锁骨和肩膀上。","当你将身体降低到蹲姿时，收紧核心并保持挺胸，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0043","name":"barbell full squat","nameZh":"杠铃深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0043-qXTaZnJ.jpg","gifPath":"exercises/videos/0043-qXTaZnJ.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你开始降低身体时，启动你的核心并保持胸部挺直。","弯曲膝盖和臀部，向后和向下推臀部，就像坐在椅子上一样。","放低身体，直到大腿与地面平行或稍低于地面。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","通过脚后跟站起来，伸展臀部和膝盖。","重复所需的重复次数。"]},{"id":"0044","name":"barbell good morning","nameZh":"杠铃早安式","equipment":"barbell","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0044-XlZ4lAC.jpg","gifPath":"exercises/videos/0044-XlZ4lAC.gif","instructionSteps":["首先站立，双脚分开与肩同宽，将杠铃放在上背部。","保持背部挺直，核心肌群参与，臀部向前转动，将臀部向后推，就好像你试图用臀部触碰身后的墙壁一样。","降低躯干直到与地面平行，感觉腿筋被拉伸。","暂停片刻，然后通过挤压臀部并将臀部向前推回到起始位置。","重复所需的重复次数。"]},{"id":"0045","name":"barbell guillotine bench press","nameZh":"杠铃断头台式卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0045-GXoaSgn.jpg","gifPath":"exercises/videos/0045-GXoaSgn.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","慢慢地将杠铃降低到颈部，保持肘部朝外。","当杠铃位于颈部上方时，暂停片刻。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"0046","name":"barbell hack squat","nameZh":"杠铃哈克深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0046-5VCj6iH.jpg","gifPath":"exercises/videos/0046-5VCj6iH.gif","instructionSteps":["首先站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在腿后面，将其放在大腿上部。","弯曲膝盖和臀部，降低身体，保持背部挺直，挺胸。","继续降低，直到大腿与地面平行，或者尽可能低。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"]},{"id":"0047","name":"barbell incline bench press","nameZh":"杠铃上斜卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0047-3TZduzM.jpg","gifPath":"exercises/videos/0047-3TZduzM.gif","instructionSteps":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚平放在地上。","正手握住杠铃，握距略宽于肩宽。","松开杠铃并将其缓慢降低至胸部，保持肘部呈 45 度角。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0048","name":"barbell incline reverse-grip press","nameZh":"杠铃上斜反向-握推举","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0048-641mIfk.jpg","gifPath":"exercises/videos/0048-641mIfk.gif","instructionSteps":["设置一个 45 度角的上斜凳。","仰卧在长凳上，反握抓住杠铃，双手距离略宽于肩宽。","松开杠铃并将其向上胸部降低，保持肘部内收。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0049","name":"barbell incline row","nameZh":"杠铃上斜划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0049-dmgMp3n.jpg","gifPath":"exercises/videos/0049-dmgMp3n.gif","instructionSteps":["设置一个 45 度角的上斜凳。","脸朝下躺在长凳上，胸部靠在垫子上，双脚平放在地上。","正手握住杠铃，握距略宽于肩宽。","保持背部挺直，核心肌群参与。","将杠铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0050","name":"barbell incline shoulder raise","nameZh":"杠铃上斜肩部抬举","equipment":"barbell","bodyPart":"chest","target":"serratus anterior","imagePath":"exercises/images/0050-xi0yckC.jpg","gifPath":"exercises/videos/0050-xi0yckC.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，背部靠在垫子上，双脚平放在地面上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃举至肩膀高度，保持肘部稍微弯曲。","慢慢地将杠铃举过头顶，充分伸展双臂。","在顶部停顿片刻，然后慢慢将杠铃放回肩部高度。","重复所需的重复次数。"]},{"id":"0051","name":"barbell jefferson squat","nameZh":"杠铃杰斐逊深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0051-pkSoCW9.jpg","gifPath":"exercises/videos/0051-pkSoCW9.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微外翻。","正手握住杠铃，将其放在身体前部、腰部下方。","左脚向前迈出，右脚向后迈出，双脚分开与肩同宽。","弯曲膝盖，将身体降低至蹲姿，保持背部挺直，挺胸。","脚后跟用力，站回起始位置。","重复该动作，每次重复时交替使用前脚和后脚。"]},{"id":"0052","name":"barbell jm bench press","nameZh":"杠铃 JM 卧推","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0052-ZsiqXYa.jpg","gifPath":"exercises/videos/0052-ZsiqXYa.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","将杠铃降低到胸部，保持肘部靠近身体。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"0053","name":"barbell jump squat","nameZh":"杠铃跳跃深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0053-1gFNTZV.jpg","gifPath":"exercises/videos/0053-1gFNTZV.gif","instructionSteps":["首先，双脚分开与肩同宽站立，将杠铃放在上背部。","弯曲膝盖并将臀部向后推，将身体降低至蹲姿。","一旦到达深蹲底部，就从地面跳起向上爆发。","跳跃时，伸展臀部、膝盖和脚踝，推动脚趾。","轻轻地回到蹲姿，然后立即重复该动作达到所需的重复次数。"]},{"id":"0054","name":"barbell lunge","nameZh":"杠铃弓步","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0054-t8iSghb.jpg","gifPath":"exercises/videos/0054-t8iSghb.gif","instructionSteps":["首先，双脚分开与肩同宽，将杠铃放在上背部。","右脚向前迈出一步，保持躯干直立。","弯曲右膝降低身体，直到大腿与地面平行。","推动右脚跟回到起始位置。","用左腿重复上述动作，交替腿进行所需的重复次数。"]},{"id":"0055","name":"barbell lying close-grip press","nameZh":"杠铃仰卧窄距推举","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0055-EcaV7aL.jpg","gifPath":"exercises/videos/0055-EcaV7aL.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","紧紧握住杠铃，双手与肩同宽，手掌朝向脚部。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","慢慢地将杠铃降低到胸部，保持肘部靠近身体。","当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。","重复所需的重复次数。"]},{"id":"0056","name":"barbell lying close-grip triceps extension","nameZh":"杠铃仰卧窄距肱三头肌伸展","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0056-HJ63mSO.jpg","gifPath":"exercises/videos/0056-HJ63mSO.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","紧握杠铃，双手与肩同宽，掌心向上。","充分伸展双臂，将杠铃举至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","在底部停顿片刻，然后将手臂伸展回起始位置。","重复所需的重复次数。"]},{"id":"0057","name":"barbell lying extension","nameZh":"杠铃仰卧伸展","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0057-EMpUwRI.jpg","gifPath":"exercises/videos/0057-EMpUwRI.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"]},{"id":"0058","name":"barbell lying lifting (on hip)","nameZh":"杠铃仰卧上提 (在髋)","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0058-SNFfUff.jpg","gifPath":"exercises/videos/0058-SNFfUff.gif","instructionSteps":["仰卧在长凳上，双脚平放在地上，膝盖弯曲。","正手握住杠铃并将其放在臀部上。","收紧臀部，将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"0059","name":"barbell lying preacher curl","nameZh":"杠铃仰卧牧师凳弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0059-SYJ4Bkt.jpg","gifPath":"exercises/videos/0059-SYJ4Bkt.gif","instructionSteps":["坐在牧师长凳上，胸部靠在垫子上，手臂伸出边缘，反手握住杠铃。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0060","name":"barbell lying triceps extension skull crusher","nameZh":"仰卧臂屈伸","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0060-h8LFzo9.jpg","gifPath":"exercises/videos/0060-h8LFzo9.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","当杠铃位于前额上方时暂停片刻，然后将手臂向后伸展至起始位置。","重复所需的重复次数。"]},{"id":"0061","name":"barbell lying triceps extension","nameZh":"杠铃仰卧肱三头肌伸展","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0061-iZop9xO.jpg","gifPath":"exercises/videos/0061-iZop9xO.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","正手握住杠铃，双手与肩同宽，将手臂伸直至胸部上方。","保持上臂静止，弯曲肘部，慢慢将杠铃降低到前额。","在底部停顿片刻，然后将手臂伸回起始位置。","重复所需的重复次数。"]},{"id":"0063","name":"barbell narrow stance squat","nameZh":"杠铃窄距深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0063-elhhVgj.jpg","gifPath":"exercises/videos/0063-elhhVgj.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","收紧核心并保持挺胸，同时弯曲膝盖并向后推臀部，慢慢降低身体。","继续降低，直到大腿与地面平行或略低于地面。","暂停片刻，然后用力推动脚后跟，回到起始位置。","重复所需的重复次数。"]},{"id":"0064","name":"barbell one arm bent over row","nameZh":"杠铃单臂俯身划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0064-Jsgsc27.jpg","gifPath":"exercises/videos/0064-Jsgsc27.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲，用一只手正握握住杠铃。","臀部向前弯曲，保持背部挺直，头部处于中立位置。","将杠铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。","以受控的方式将杠铃降低回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0065","name":"barbell one arm floor press","nameZh":"杠铃单臂地面推举","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0065-vtusOWT.jpg","gifPath":"exercises/videos/0065-vtusOWT.gif","instructionSteps":["仰卧在地板上，膝盖弯曲，双脚平放在地面上。","用一只手握住杠铃，掌心朝上，将手臂伸直至胸部上方。","慢慢地将杠铃降低到胸部，保持肘部靠近身体。","在底部停顿片刻，然后将杠铃推回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0066","name":"barbell one arm side deadlift","nameZh":"杠铃单臂侧硬拉","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0066-2DxtqHL.jpg","gifPath":"exercises/videos/0066-2DxtqHL.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住杠铃，正握。","保持背部挺直，核心肌群参与。","臀部弯曲，将杠铃向腿外侧放低，保持手臂伸直，挺胸。","尽可能降低杠铃，同时保持良好的姿势。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0067","name":"barbell one arm snatch","nameZh":"杠铃单臂抓举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0067-xHKN2s8.jpg","gifPath":"exercises/videos/0067-xHKN2s8.gif","instructionSteps":["双脚分开与肩同宽站立，脚趾稍微向外。","正手握住杠铃，双手分开略宽于肩宽。","弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。","爆发性伸展臀部、膝盖和脚踝，将杠铃向上推。","当杠铃到达胸部水平时，用手臂将其向上拉，使其靠近身体。","将肘部旋转到杠铃下方，并将手臂完全伸过头顶，锁定肘部。","以受控的方式将杠铃降低回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0068","name":"barbell one leg squat","nameZh":"杠铃单腿深蹲","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0068-uKyN64F.jpg","gifPath":"exercises/videos/0068-uKyN64F.gif","instructionSteps":["双脚分开与肩同宽站立，将杠铃放在上背部。","将一只脚抬离地面并向前伸展，保持与地面平行。","弯曲站立的腿，放低身体，就像坐回椅子上一样，保持挺胸、背部挺直。","降低身体直到大腿与地面平行，然后通过脚后跟推回到起始位置。","重复所需的重复次数，然后换腿并重复。"]},{"id":"0069","name":"barbell overhead squat","nameZh":"杠铃过头深蹲","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0069-gfk9kD4.jpg","gifPath":"exercises/videos/0069-gfk9kD4.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微外翻。","宽握距握住杠铃，将其置于头顶，双臂完全伸展。","收紧核心肌群，将身体放低至蹲姿，保持胸部向上，膝盖位于脚趾上方。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0070","name":"barbell preacher curl","nameZh":"杠铃牧师凳弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0070-qOgPVf6.jpg","gifPath":"exercises/videos/0070-qOgPVf6.gif","instructionSteps":["坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。","反手握住杠铃，握距略宽于肩宽。","保持上臂静止，呼气并将杠铃向上弯向肩膀。","在顶部暂停片刻，挤压你的二头肌。","吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0071","name":"barbell press sit-up","nameZh":"杠铃推举仰卧起坐","equipment":"barbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0071-wnEscH8.jpg","gifPath":"exercises/videos/0071-wnEscH8.gif","instructionSteps":["平躺在垫子上，膝盖弯曲，双脚平放在地上。","正手握住杠铃，将其放在胸前。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0072","name":"barbell prone incline curl","nameZh":"杠铃俯卧上斜弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0072-WLvTAv5.jpg","gifPath":"exercises/videos/0072-WLvTAv5.gif","instructionSteps":["设置一个 45 度角的上斜凳。","脸朝下躺在长凳上，胸部和腹部靠在长凳上。","反手握住杠铃，距离与肩同宽。","充分伸展双臂，让杠铃垂向地板。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0073","name":"barbell pullover","nameZh":"杠铃仰卧屈臂上拉","equipment":"barbell","bodyPart":"back","target":"lats","imagePath":"exercises/images/0073-i6LWjok.jpg","gifPath":"exercises/videos/0073-i6LWjok.gif","instructionSteps":["平躺在长凳上，头放在一端，双脚放在地板上。","握距与肩同宽，握住杠铃，将手臂伸直至胸部上方。","保持手臂伸直，以受控的方式将杠铃降低到头后，直到感觉到背阔肌被拉伸。","暂停片刻，然后将杠铃举回起始位置。","重复所需的重复次数。"]},{"id":"0074","name":"barbell rack pull","nameZh":"杠铃架上硬拉","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0074-za9Ni4z.jpg","gifPath":"exercises/videos/0074-za9Ni4z.gif","instructionSteps":["将杠铃放在膝盖高度的架子上。","双脚分开与肩同宽站立，脚趾稍微向外。","弯曲臀部和膝盖，降低身体高度，正手握住杠铃，双手与肩同宽。","通过伸展臀部和膝盖、向后拉肩膀并在顶部挤压臀部来收紧核心并举起杠铃。","弯曲臀部和膝盖，将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0075","name":"barbell rear delt raise","nameZh":"杠铃后三角肌抬举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0075-Ln9iTbU.jpg","gifPath":"exercises/videos/0075-Ln9iTbU.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃，手掌朝下。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将杠铃向两侧举起，保持手臂伸直，直到它们与地面平行。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0076","name":"barbell rear delt row","nameZh":"杠铃后三角肌划船","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0076-S9zHIvU.jpg","gifPath":"exercises/videos/0076-S9zHIvU.gif","instructionSteps":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，双手分开略宽于肩宽。","臀部向前弯曲，保持背部挺直，挺胸。","将杠铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0077","name":"barbell rear lunge v. 2","nameZh":"杠铃后弓步版本 2","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0077-62Nw60O.jpg","gifPath":"exercises/videos/0077-62Nw60O.gif","instructionSteps":["双脚分开与肩同宽站立，将杠铃放在上背部。","右脚向后退一步，用脚掌着地。","弯曲双膝降低身体，直到左大腿与地面平行。","推动左脚跟返回到起始位置。","换另一条腿重复上述步骤。"]},{"id":"0078","name":"barbell rear lunge","nameZh":"杠铃后弓步","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0078-VaP75jl.jpg","gifPath":"exercises/videos/0078-VaP75jl.gif","instructionSteps":["首先，双脚分开与肩同宽，将杠铃放在上背部。","右脚向后退一步，用脚掌着地。","弯曲双膝降低身体，直到左大腿与地面平行。","推动左脚跟返回到起始位置。","换另一条腿重复上述步骤。"]},{"id":"0079","name":"barbell revers wrist curl v. 2","nameZh":"杠铃反向手腕弯举版本 2","equipment":"barbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0079-qDnGfDb.jpg","gifPath":"exercises/videos/0079-qDnGfDb.gif","instructionSteps":["坐在长凳上，双脚平放在地上，膝盖弯曲。","正手握住杠铃，手掌朝下，双手与肩同宽。","将前臂放在大腿上，让手腕悬在边缘。","保持前臂静止，呼气并尽可能向上弯曲手腕。","保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0080","name":"barbell reverse curl","nameZh":"杠铃反向弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0080-xNrS20v.jpg","gifPath":"exercises/videos/0080-xNrS20v.gif","instructionSteps":["站直，双脚分开与肩同宽，正手握住杠铃，手掌朝下。","保持上臂静止，向上弯举杠铃时呼气，收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢将杠铃放回起始位置，保持上臂静止。","重复所需的重复次数。"]},{"id":"0081","name":"barbell reverse preacher curl","nameZh":"杠铃反向牧师凳弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0081-4LIG9xr.jpg","gifPath":"exercises/videos/0081-4LIG9xr.gif","instructionSteps":["坐在牧师凳上，胸部靠在垫子上，手臂伸直向下，正手握住杠铃。","保持上臂静止，呼气并向上弯曲杠铃，同时收缩二头肌。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0082","name":"barbell reverse wrist curl","nameZh":"杠铃反手腕弯举","equipment":"barbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0082-LsZkfU6.jpg","gifPath":"exercises/videos/0082-LsZkfU6.gif","instructionSteps":["坐在长凳上，双脚平放在地上，正手握住杠铃，手掌朝下。","将前臂放在大腿上，让手腕悬在边缘。","慢慢向上弯曲手腕，将杠铃拉向身体。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0083","name":"barbell rollerout from bench","nameZh":"杠铃滚动从凳","equipment":"barbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0083-Gxg9lDc.jpg","gifPath":"exercises/videos/0083-Gxg9lDc.gif","instructionSteps":["首先跪在地板上，将杠铃放在你面前的长凳上。","正手握住杠铃，握距略宽于肩宽。","保持核心收紧，背部挺直，慢慢向前滚动杠铃，将手臂伸到身前。","继续向前滚动杠铃，直到身体完全伸展并且手臂举过头顶。","在完全伸展的位置暂停片刻，然后慢慢地将杠铃向身体方向滚动，回到起始位置。","重复所需的重复次数。"]},{"id":"0084","name":"barbell rollerout","nameZh":"杠铃滚动","equipment":"barbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0084-7M66AVi.jpg","gifPath":"exercises/videos/0084-7M66AVi.gif","instructionSteps":["跪在地板上，双手握住杠铃，距离与肩同宽。","向前滚动杠铃，伸展手臂并保持核心收紧。","继续向前滚动，直到身体完全伸展并且手臂举过头顶。","暂停片刻，然后慢慢将杠铃向膝盖方向滚动，保持控制。","重复所需的重复次数。"]},{"id":"0085","name":"barbell romanian deadlift","nameZh":"罗马尼亚硬拉","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0085-wQ2c4XD.jpg","gifPath":"exercises/videos/0085-wQ2c4XD.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾指向前方。","正手握住杠铃，双手分开略宽于肩宽。","弯曲臀部，保持背部挺直，膝盖稍微弯曲。","将杠铃向地面降低，使其靠近身体。","当你降低杠铃时，感受腿筋的拉伸。","一旦感觉到腿筋拉伸，就将臀部向前推并站直。","在动作的最高点挤压臀部。","将杠铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0086","name":"barbell seated behind head military press","nameZh":"杠铃坐姿头后军事推举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0086-ngPpyRS.jpg","gifPath":"exercises/videos/0086-ngPpyRS.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃从架子上提起，然后将其降至与肩同高，位于头后。","向上推杠铃，直到手臂完全伸展。","将杠铃降低回到起始位置。","重复所需的重复次数。"]},{"id":"0087","name":"barbell seated bradford rocky press","nameZh":"杠铃坐姿布拉德福德洛奇式推举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0087-0dCyly0.jpg","gifPath":"exercises/videos/0087-0dCyly0.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃举至肩膀高度，保持肘部稍微弯曲并指向前方。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回肩部高度，然后重复所需的重复次数。"]},{"id":"0088","name":"barbell seated calf raise","nameZh":"杠铃坐姿提踵","equipment":"barbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0088-ktsFQAZ.jpg","gifPath":"exercises/videos/0088-ktsFQAZ.gif","instructionSteps":["坐在长凳上，双脚平放在地板上，杠铃放在大腿上。","将脚掌放在升高的平台上，例如木块或台阶。","将杠铃放在大腿上，并用手牢牢握住它。","保持背部挺直，核心收紧，伸展脚踝，将脚后跟抬离地面。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0089","name":"barbell seated close-grip concentration curl","nameZh":"杠铃坐姿窄距集中弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0089-1V1gj1u.jpg","gifPath":"exercises/videos/0089-1V1gj1u.gif","instructionSteps":["坐在长凳上，双脚平放在地板上，反手握住杠铃，双手与肩同宽。","将你的上臂靠在大腿内侧，就在膝盖上方，让杠铃垂在你面前。","保持上臂静止，呼气并将杠铃向上卷曲至肩膀，收缩二头肌。","保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0090","name":"barbell seated good morning","nameZh":"杠铃坐姿早安式","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0090-d960PgE.jpg","gifPath":"exercises/videos/0090-d960PgE.gif","instructionSteps":["坐在长凳上，双脚平放在地上，上背部放一个杠铃。","保持背部挺直，挺胸。","慢慢地向前转动臀部，将躯干降低到地面。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0091","name":"barbell seated overhead press","nameZh":"杠铃坐姿过头推举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0091-kTbSH9h.jpg","gifPath":"exercises/videos/0091-kTbSH9h.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，杠铃间距略宽于肩宽。","将杠铃从架子上提起，并将其置于与肩同高的位置，肘部弯曲，手掌朝前。","充分伸展双臂，将杠铃压过头顶。","在顶部停顿片刻，然后慢慢将杠铃放回肩部水平。","重复所需的重复次数。"]},{"id":"0092","name":"barbell seated overhead triceps extension","nameZh":"杠铃坐姿过头肱三头肌伸展","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0092-5uFK1xr.jpg","gifPath":"exercises/videos/0092-5uFK1xr.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住杠铃，双手与肩同宽，并将其举过头顶。","弯曲肘部，将杠铃降低到脑后，保持上臂靠近头部。","暂停片刻，然后伸展双臂将杠铃举回起始位置。","重复所需的重复次数。"]},{"id":"0094","name":"barbell seated twist","nameZh":"杠铃坐姿转体","equipment":"barbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0094-dFSNDOA.jpg","gifPath":"exercises/videos/0094-dFSNDOA.gif","instructionSteps":["坐在平坦的长凳上，双脚平放在地上，膝盖弯曲。","双手握住杠铃于胸前，保持肘部稍微弯曲。","启动你的核心，慢慢地将你的躯干扭转到一侧，保持背部挺直。","扭转结束时暂停片刻，然后慢慢旋转回到起始位置。","重复扭转到另一侧。","继续交替进行所需的重复次数。"]},{"id":"0095","name":"barbell shrug","nameZh":"杠铃耸肩","equipment":"barbell","bodyPart":"back","target":"traps","imagePath":"exercises/images/0095-dG7tG5y.jpg","gifPath":"exercises/videos/0095-dG7tG5y.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃。","在整个练习过程中保持手臂伸直和背部挺直。","将肩膀尽可能高地抬向耳朵，挤压斜方肌顶部。","保持一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0096","name":"barbell side bent v. 2","nameZh":"杠铃侧屈版本 2","equipment":"barbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0096-i4JkUaL.jpg","gifPath":"exercises/videos/0096-i4JkUaL.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住杠铃，掌心朝下。","在整个练习过程中保持背部挺直并保持核心参与。","慢慢地将你的躯干弯曲到右侧，将杠铃向右膝方向降低。","暂停片刻，然后回到起始位置。","在左侧重复该动作。","继续交替进行所需的重复次数。"]},{"id":"0097","name":"barbell side split squat v. 2","nameZh":"杠铃侧分腿深蹲版本 2","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0097-HUEqZ1y.jpg","gifPath":"exercises/videos/0097-HUEqZ1y.gif","instructionSteps":["站立，双脚分开比肩宽，脚趾稍微向外。","将杠铃放在上背部，将其放在肩膀上。","右脚向一侧迈出一大步，保持左脚踩地。","弯曲右膝，将身体放低至蹲姿，保持挺胸、背部挺直。","推动右脚跟回到起始位置。","在另一侧重复，左脚迈出。","继续交替进行所需的重复次数。"]},{"id":"0098","name":"barbell side split squat","nameZh":"杠铃侧分腿深蹲","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0098-W31mMjd.jpg","gifPath":"exercises/videos/0098-W31mMjd.gif","instructionSteps":["站立，双脚分开比肩宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌上。","当你将身体降低到蹲姿时，收紧你的核心并保持胸部向上，弯曲膝盖和臀部。","当你下降时，将膝盖向两侧推出，并将体重保持在脚后跟上。","降低直到大腿与地面平行，然后通过脚后跟推回到起始位置。","重复所需的重复次数。"]},{"id":"0099","name":"barbell single leg split squat","nameZh":"杠铃单腿分腿深蹲","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0099-gGNQmVt.jpg","gifPath":"exercises/videos/0099-gGNQmVt.gif","instructionSteps":["双脚分开与肩同宽站立，将杠铃放在上背部。","单腿向前迈出一大步，保持躯干直立。","弯曲前膝盖和臀部，降低身体，同时保持后腿伸直。","继续降低，直到大腿前侧与地面平行。","暂停片刻，然后推动前脚跟回到起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0100","name":"barbell skier","nameZh":"杠铃滑雪式","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0100-4Leypho.jpg","gifPath":"exercises/videos/0100-4Leypho.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃于大腿前方。","稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。","同时将杠铃举向肩膀，同时稍微离开地面。","当您到达动作的最高点时，快速反转动作并将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0101","name":"barbell speed squat","nameZh":"杠铃速度深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0101-euI1BwR.jpg","gifPath":"exercises/videos/0101-euI1BwR.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","收紧核心肌群，保持挺胸，同时向后和向下降低臀部，就像坐在椅子上一样。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","通过脚跟发力站起来，在顶部挤压臀部。","重复所需的重复次数。"]},{"id":"0102","name":"barbell squat (on knees)","nameZh":"杠铃深蹲 (在膝盖)","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0102-oR7O9LW.jpg","gifPath":"exercises/videos/0102-oR7O9LW.gif","instructionSteps":["首先跪在地上，膝盖分开与臀部同宽，脚趾向前。","将杠铃放在肩膀上，正手握住杠铃，双手分开的距离略大于肩宽。","收紧核心并保持胸部抬起，同时弯曲膝盖慢慢降低身体，保持背部挺直。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0103","name":"barbell standing ab rollerout","nameZh":"杠铃站姿腹肌滚轮","equipment":"barbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0103-xnInPfE.jpg","gifPath":"exercises/videos/0103-xnInPfE.gif","instructionSteps":["站直，双脚分开与肩同宽，双手握住杠铃于大腿前方。","启动你的核心肌群，慢慢地将杠铃向地面滚动，保持背部挺直，手臂伸展。","继续向前滚动杠铃，直到身体完全伸展，双手位于头顶正上方。","暂停片刻，然后慢慢地将杠铃向大腿方向滚动，保持控制并保持核心参与。","重复所需的重复次数。"]},{"id":"0104","name":"barbell standing back wrist curl","nameZh":"杠铃站姿背部手腕弯举","equipment":"barbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0104-2qTvJAZ.jpg","gifPath":"exercises/videos/0104-2qTvJAZ.gif","instructionSteps":["站直，双脚分开与肩同宽，正手握住杠铃。","将杠铃放在手背上，手掌朝下，手指指向身体。","保持上臂静止，呼气并尽可能向上弯曲手腕。","保持收缩位置短暂停顿，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0105","name":"barbell standing bradford press","nameZh":"杠铃站姿布拉德福德推举","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0105-dCPESfR.jpg","gifPath":"exercises/videos/0105-dCPESfR.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃于肩前。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回到起始位置。","重复所需的重复次数。"]},{"id":"0106","name":"barbell standing close grip curl","nameZh":"杠铃站姿窄距弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0106-4dUn2iv.jpg","gifPath":"exercises/videos/0106-4dUn2iv.gif","instructionSteps":["站直，双脚分开与肩同宽，反手握住杠铃，双手并拢。","在整个运动过程中，保持肘部靠近躯干，上臂保持静止。","弯举哑铃时呼气，同时收缩二头肌。继续抬高杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢开始将杠铃拉回到起始位置。","重复所需的重复次数。"]},{"id":"0107","name":"barbell standing front raise over head","nameZh":"杠铃站姿前平举过头","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0107-S8mo30S.jpg","gifPath":"exercises/videos/0107-S8mo30S.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃于大腿前方。","保持背部挺直并启动核心肌群。","慢慢地将杠铃举到你面前，保持手臂伸直，手掌朝下。","继续举起杠铃，直到杠铃略高于肩部水平。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0108","name":"barbell standing leg calf raise","nameZh":"杠铃站姿腿提踵","equipment":"barbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0108-rGwhJ5o.jpg","gifPath":"exercises/videos/0108-rGwhJ5o.gif","instructionSteps":["双脚分开与肩同宽站立，将杠铃放在上背部。","用小腿将脚跟抬离地面，尽可能高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0109","name":"barbell standing overhead triceps extension","nameZh":"杠铃站姿过头肱三头肌伸展","equipment":"barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0109-dZl9Q27.jpg","gifPath":"exercises/videos/0109-dZl9Q27.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃。","将杠铃举过头顶，充分伸展双臂。","保持上臂靠近头部，弯曲肘部，慢慢将杠铃降低到脑后。","暂停片刻，然后伸展双臂将杠铃举回起始位置。","重复所需的重复次数。"]},{"id":"0110","name":"barbell standing reverse grip curl","nameZh":"杠铃站姿反握弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0110-LWuA3aZ.jpg","gifPath":"exercises/videos/0110-LWuA3aZ.gif","instructionSteps":["站直，双脚分开与肩同宽，反手握住杠铃，手掌朝上。","保持肘部靠近躯干，上臂保持静止。","呼气并弯举杠铃，同时收缩二头肌，使杠铃尽可能靠近肩膀。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0111","name":"barbell standing rocking leg calf raise","nameZh":"杠铃站姿摇摆腿提踵","equipment":"barbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0111-6HiHHe0.jpg","gifPath":"exercises/videos/0111-6HiHHe0.gif","instructionSteps":["双脚分开与肩同宽站立，将杠铃放在上背部。","将脚跟抬离地面，尽可能高，用脚掌保持平衡。","慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0112","name":"barbell standing twist","nameZh":"杠铃站姿转体","equipment":"barbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0112-yQe5HpE.jpg","gifPath":"exercises/videos/0112-yQe5HpE.gif","instructionSteps":["双脚分开与肩同宽站立，双手握住杠铃于胸前，掌心朝下。","在整个练习过程中启动你的核心并保持背部挺直。","慢慢地将躯干向右扭转，以脚和臀部为轴，同时保持下半身稳定。","扭转结束时暂停片刻，然后慢慢回到起始位置。","向左侧重复扭转。","继续交替扭转所需的重复次数。"]},{"id":"0113","name":"barbell standing wide-grip curl","nameZh":"杠铃站姿宽距弯举","equipment":"barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0113-NdIb5Z1.jpg","gifPath":"exercises/videos/0113-NdIb5Z1.gif","instructionSteps":["站直，双脚分开与肩同宽，正手握住杠铃，双手分开比肩宽。","让杠铃悬挂在大腿前面，与手掌保持一臂距离，手掌背向身体。","保持上臂静止，呼气并通过收缩二头肌向上弯曲杠铃。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0114","name":"barbell step-up","nameZh":"杠铃登阶","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0114-Kxquu2E.jpg","gifPath":"exercises/videos/0114-Kxquu2E.gif","instructionSteps":["站在长凳或台阶前，将杠铃放在上背部。","将一只脚放在长凳或台阶上，确保整个脚与表面接触。","穿过你的脚后跟，走上长凳或台阶，充分伸展你的臀部和膝盖。","在顶部短暂停顿，然后放低自己回到起始位置。","用另一条腿重复上述步骤。","继续交替双腿达到所需的重复次数。"]},{"id":"0115","name":"barbell stiff leg good morning","nameZh":"杠铃直腿早安式","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0115-JrOHAZc.jpg","gifPath":"exercises/videos/0115-JrOHAZc.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","将杠铃放在上背部，将其放在斜方肌上。","保持背部挺直，臀部向前转动，将臀部向后推。","降低躯干直到与地面平行，感觉腿筋被拉伸。","启动臀肌和腿筋以返回起始位置。","重复所需的重复次数。"]},{"id":"0116","name":"barbell straight leg deadlift","nameZh":"杠铃直腿硬拉","equipment":"barbell","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0116-hrVQWvE.jpg","gifPath":"exercises/videos/0116-hrVQWvE.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾指向前方。","正手握住杠铃，双手分开略宽于肩宽。","弯曲臀部，将杠铃放低至地面，保持背部挺直，膝盖稍微弯曲。","降低杠铃，直到感觉到腿筋拉伸。","启动腿筋和臀肌，将杠铃举回起始位置。","重复所需的重复次数。"]},{"id":"0117","name":"barbell sumo deadlift","nameZh":"杠铃相扑硬拉","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0117-KgI0tqW.jpg","gifPath":"exercises/videos/0117-KgI0tqW.gif","instructionSteps":["站立，双脚分开比肩宽，脚趾朝外。","将杠铃放在您面前的地面上，位于双脚之间的中心。","弯曲膝盖，降低臀部，保持背部挺直，挺胸，用正手握法抓住杠铃。","启动你的核心并通过你的脚后跟发力，将杠铃抬离地面，同时伸展你的臀部和膝盖。","当你举起时，保持胸部挺直，背部挺直，向前推动臀部以充分锻炼臀部。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置，在整个动作过程中保持控制。","重复所需的重复次数。"]},{"id":"0118","name":"barbell reverse grip bent over row","nameZh":"杠铃反握俯身划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0118-SzX3uzM.jpg","gifPath":"exercises/videos/0118-SzX3uzM.gif","instructionSteps":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，手掌朝下，双手分开略宽于肩宽。","臀部向前弯曲，保持背部挺直，挺胸，直到躯干几乎与地板平行。","将杠铃拉向下胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0119","name":"barbell upright row v. 2","nameZh":"杠铃直立划船版本 2","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0119-83HoW9X.jpg","gifPath":"exercises/videos/0119-83HoW9X.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0120","name":"barbell upright row","nameZh":"杠铃直立划船","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0120-UDlhcO8.jpg","gifPath":"exercises/videos/0120-UDlhcO8.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，核心收紧，呼气，将杠铃笔直向上举向下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0121","name":"barbell upright row v. 3","nameZh":"杠铃直立划船版本 3","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0121-fI18Rbc.jpg","gifPath":"exercises/videos/0121-fI18Rbc.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃，双手分开略宽于肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持核心收紧，背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。","在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0122","name":"barbell wide bench press","nameZh":"杠铃宽卧推","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0122-JsKq9so.jpg","gifPath":"exercises/videos/0122-JsKq9so.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","宽握距抓住杠铃，握距略宽于肩宽。","将杠铃从架子上提起，并将其直接放在胸部上方，双臂完全伸展。","慢慢地将杠铃向胸部降低，保持肘部稍微张开。","当杠铃接触胸部时暂停片刻，然后将其推回到起始位置。","重复所需的重复次数。"]},{"id":"0123","name":"barbell wide-grip upright row","nameZh":"杠铃宽距直立划船","equipment":"barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0123-RgJDRR1.jpg","gifPath":"exercises/videos/0123-RgJDRR1.gif","instructionSteps":["双脚分开与肩同宽站立，正手握住杠铃，双手分开比肩宽。","让杠铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，呼气，将杠铃向上举至下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0124","name":"barbell wide squat","nameZh":"杠铃宽距深蹲","equipment":"barbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0124-s7HX1BY.jpg","gifPath":"exercises/videos/0124-s7HX1BY.gif","instructionSteps":["站立，双脚分开比肩宽，脚趾稍微向外。","将杠铃放在上背部，将其放在斜方肌或三角肌后束上。","当你下蹲时，收紧你的核心并保持胸部挺直，将臀部向后推并弯曲膝盖。","降低直到大腿与地面平行，或者尽可能降低到您能舒服的高度。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0125","name":"barbell wrist curl v. 2","nameZh":"杠铃手腕弯举版本 2","equipment":"barbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0125-6kSxYnw.jpg","gifPath":"exercises/videos/0125-6kSxYnw.gif","instructionSteps":["坐在长凳上，双脚平放在地上，膝盖弯曲。","反手握住杠铃，手掌朝上，双手与肩同宽。","将前臂放在大腿上，让手腕悬在边缘。","慢慢向上弯曲手腕，将杠铃拉向前臂。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0126","name":"barbell wrist curl","nameZh":"杠铃手腕弯举","equipment":"barbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0126-82LxxkW.jpg","gifPath":"exercises/videos/0126-82LxxkW.gif","instructionSteps":["坐在长凳上，双脚平放在地面上，前臂放在大腿上，反握杠铃。","让杠铃向下滚动到指尖，保持手腕伸直。","弯曲手腕，慢慢地将杠铃向上卷向前臂。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0127","name":"barbell zercher squat","nameZh":"杠铃泽奇深蹲","equipment":"barbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0127-LSTChY9.jpg","gifPath":"exercises/videos/0127-LSTChY9.gif","instructionSteps":["站立，双脚分开与肩同宽，脚趾稍微外翻。","将杠铃放在肘部的弯曲处，双手握住杠铃以保持稳定。","当你将臀部向后降低到蹲姿时，启动你的核心并保持胸部抬起。","保持膝盖与脚趾对齐，并将重量放在脚后跟上。","在深蹲底部暂停片刻，然后用脚后跟恢复到起始位置。","重复所需的重复次数。"]},{"id":"0128","name":"battling ropes","nameZh":"战绳","equipment":"rope","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0128-RJa4tCo.jpg","gifPath":"exercises/videos/0128-RJa4tCo.gif","instructionSteps":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","双手握住绳子的一端，手掌相对。","将手臂举至肩膀高度，保持肘部稍微弯曲。","快速抬起和放下每只手臂，开始用绳索产生交替的波浪。","继续所需的持续时间或重复次数。"]},{"id":"0129","name":"bench dip (knees bent)","nameZh":"凳上臂屈伸 (膝盖屈)","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0129-RrLske5.jpg","gifPath":"exercises/videos/0129-RrLske5.gif","instructionSteps":["坐在长凳或椅子的边缘，双手抓住臀部旁边的边缘。","将臀部从长凳上滑下来，在身前伸直双腿，脚后跟保持在地面上。","弯曲肘部，将身体放低至地面，保持背部靠近长凳。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0130","name":"bench hip extension","nameZh":"凳髋伸展","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0130-u27Kcdz.jpg","gifPath":"exercises/videos/0130-u27Kcdz.gif","instructionSteps":["坐在长凳上，背部靠在长凳上，双脚平放在地上。","将双手放在长凳上以获得支撑。","收紧臀肌和腿筋，然后将臀部抬离长凳，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"0137","name":"body-up","nameZh":"身体向上","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0137-U6G2gk9.jpg","gifPath":"exercises/videos/0137-U6G2gk9.gif","instructionSteps":["首先将双手放在凸起的表面上，例如长凳或双杠上，手掌朝下，手指向前。","将双腿向前方伸展，脚跟保持在地面上，身体伸直。","弯曲肘部降低身体，使其靠近身体两侧，直到上臂与地面平行。","暂停片刻，然后用手掌伸直手臂，将身体抬回到起始位置。","重复所需的重复次数。"]},{"id":"0138","name":"bottoms-up","nameZh":"底部朝上","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0138-CI6baTY.jpg","gifPath":"exercises/videos/0138-CI6baTY.gif","instructionSteps":["平躺，双腿伸展，双臂放在身体两侧。","弯曲膝盖并将其靠近胸部，保持双脚离开地面。","收紧腹肌，将臀部抬离地面，将膝盖靠近头部。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"0139","name":"biceps narrow pull-ups","nameZh":"肱二头肌窄引体向上","equipment":"body weight","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0139-50BETrz.jpg","gifPath":"exercises/videos/0139-50BETrz.gif","instructionSteps":["悬挂在引体向上杆上，手掌朝向自己，双手与肩同宽。","启动你的核心并将自己拉向杠铃，专注于使用二头肌来抬起你的身体。","在最高点暂停片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"0140","name":"biceps pull-up","nameZh":"肱二头肌引体向上","equipment":"body weight","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0140-guT8YnS.jpg","gifPath":"exercises/videos/0140-guT8YnS.gif","instructionSteps":["悬挂在引体向上杆上，手掌背向自己，双手与肩同宽。","启动核心肌群，弯曲肘部将自己拉起，使胸部靠近杠铃。","在动作的最高点暂停，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"0148","name":"cable alternate shoulder press","nameZh":"绳索交替肩推","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0148-KHPZL0b.jpg","gifPath":"exercises/videos/0148-KHPZL0b.gif","instructionSteps":["双脚分开与肩同宽站立，并用正手握住绳索机的手柄。","将双手放在与肩同高的位置，手掌朝前。","保持核心参与并保持背部挺直。","向上并向前按下一个手柄，直到您的手臂完全伸展。","在最高点暂停片刻，然后慢慢将手柄放回起始位置。","用另一只手臂重复上述步骤。","双臂交替进行所需的重复次数。"]},{"id":"0149","name":"cable alternate triceps extension","nameZh":"绳索交替肱三头肌伸展","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0149-Gchi5Tr.jpg","gifPath":"exercises/videos/0149-Gchi5Tr.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","右手握住电缆手柄，抬起手臂，使上臂与地面平行，肘部弯曲成 90 度角。","保持上臂静止，前臂向后伸展，完全伸直手臂。","暂停片刻，然后慢慢回到起始位置。","用左臂重复此动作。","继续交替手臂进行所需的重复次数。"]},{"id":"0150","name":"cable bar lateral pulldown","nameZh":"绳索杆侧向下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0150-eYnzaCm.jpg","gifPath":"exercises/videos/0150-eYnzaCm.gif","instructionSteps":["将电缆滑轮调整至较高位置并安装直杆。","面向缆绳机坐着，双脚平放在地面上，膝盖稍微弯曲。","正手握住杠铃，握距略宽于肩宽。","稍微向后倾斜，挺胸，保持下背部轻微的拱形。","将杠铃向下拉向胸部，用肘部引导并将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"]},{"id":"0151","name":"cable bench press","nameZh":"绳索卧推","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0151-7xI5MXA.jpg","gifPath":"exercises/videos/0151-7xI5MXA.gif","instructionSteps":["将绳索机调整至胸部高度并安装手柄。","背对机器站立，双脚与肩同宽。","正手握住手柄并向前迈一步，以在电缆中产生张力。","将双脚牢牢放在地面上并启动核心。","弯曲肘部，将双手置于肩部水平，保持肘部呈 90 度角。","向前推动手柄，将双臂完全伸展到身前。","暂停片刻，然后慢慢扭转动作，将双手放回肩部水平。","重复所需的重复次数。"]},{"id":"0152","name":"cable concentration extension (on knee)","nameZh":"绳索集中伸展 (在膝)","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0152-Db7eEgw.jpg","gifPath":"exercises/videos/0152-Db7eEgw.gif","instructionSteps":["坐在长凳或椅子上，膝盖弯曲，双脚平放在地上。","用右手握住电缆手柄，并将肘部放在右膝盖内侧。","充分伸展手臂，保持肘部静止并靠近膝盖。","在顶部停顿片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0153","name":"cable cross-over lateral pulldown","nameZh":"绳索交叉侧向下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0153-OQ1otBN.jpg","gifPath":"exercises/videos/0153-OQ1otBN.gif","instructionSteps":["将电缆手柄连接到电缆机器两侧与肩同高的位置。","站在机器中间，双脚分开与肩同宽。","正手握住手柄并后退以在电缆中产生张力。","从臀部开始稍微向前倾，保持背部挺直，挺胸。","将手柄向下拉并穿过身体，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0154","name":"cable cross-over revers fly","nameZh":"绳索交叉反向飞鸟","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0154-aqvSOQE.jpg","gifPath":"exercises/videos/0154-aqvSOQE.gif","instructionSteps":["将 D 形手柄连接到每根低滑轮电缆上，并站在电缆交叉机的中间。","旋前抓住手柄（手掌朝下），向前迈出一步，双脚分开与肩同宽。","稍微弯曲膝盖，腰部前倾，保持背部挺直，腹部收紧。","双臂向两侧伸展，肘部稍微弯曲，呼气并将肩胛骨挤压在一起，同时以反向飞翔动作向后和向上拉动绳索。","在收缩峰值时停顿片刻，然后吸气，慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0155","name":"cable cross-over variation","nameZh":"绳索交叉变式","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0155-0CXGHya.jpg","gifPath":"exercises/videos/0155-0CXGHya.gif","instructionSteps":["将电缆滑轮调整至胸部高度。","站在电缆机的中央，一只脚在另一只脚前面。","手掌朝下抓住手柄，手臂向两侧伸展。","向前迈出一步，保持手臂稍微弯曲。","肘部稍微弯曲，双手并拢放在胸前。","暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0157","name":"cable deadlift","nameZh":"绳索硬拉","equipment":"cable","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0157-eGDudUV.jpg","gifPath":"exercises/videos/0157-eGDudUV.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","弯曲臀部和膝盖，降低躯干，直到背部与地面平行。","正手握住电缆手柄，保持手臂伸直，肩膀向后。","调动臀肌和腿筋来抬起拉索手柄，伸展臀部并站直。","在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0158","name":"cable decline fly","nameZh":"绳索下斜飞鸟","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0158-7saC5zz.jpg","gifPath":"exercises/videos/0158-7saC5zz.gif","instructionSteps":["将拉线机调整至下降位置。","背对机器站立，双脚与肩同宽。","握住手柄，手掌朝前，双臂在身前伸直。","保持肘部轻微弯曲，以受控的动作向两侧张开双臂。","在完全伸展位置停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0159","name":"cable decline seated wide-grip row","nameZh":"绳索下斜坐姿宽距划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0159-kesXOpB.jpg","gifPath":"exercises/videos/0159-kesXOpB.gif","instructionSteps":["坐在面向缆绳机的下斜长凳上，双脚牢固地放在脚踏板上。","用宽的正手握法抓住电缆附件，手掌朝下。","稍微向后倾斜，保持背部挺直，核心肌群参与。","将电缆拉向下胸部，将肩胛骨挤压在一起。","在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。","重复所需的重复次数。"]},{"id":"0160","name":"cable floor seated wide-grip row","nameZh":"绳索地面坐姿宽距划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0160-veXwo0D.jpg","gifPath":"exercises/videos/0160-veXwo0D.gif","instructionSteps":["坐在地板上，双腿伸直，背部挺直。","将缆绳手柄连接到低滑轮上，并将缆绳机放在您身后。","正手宽握握住手柄，手掌朝下。","稍微向后倾斜，保持背部挺直，挺胸。","将手柄拉向腰部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0161","name":"cable forward raise","nameZh":"绳索前抬举","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0161-hvHhCv8.jpg","gifPath":"exercises/videos/0161-hvHhCv8.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住电缆手柄，手掌朝下，双臂在身前完全伸展。","保持手臂伸直，将电缆手柄抬高至肩部水平。","在顶部暂停片刻，然后慢慢将缆索手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0162","name":"cable front raise","nameZh":"绳索前平举","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0162-u2X71Np.jpg","gifPath":"exercises/videos/0162-u2X71Np.gif","instructionSteps":["双脚分开与肩同宽站立，并用正手握住电缆手柄。","保持背部挺直，核心肌群参与。","将电缆手柄举到您面前，保持手臂伸直，手掌朝下。","继续抬起，直到手臂与地板平行。","在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0164","name":"cable front shoulder raise","nameZh":"绳索前肩部抬举","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0164-mTT3KLn.jpg","gifPath":"exercises/videos/0164-mTT3KLn.gif","instructionSteps":["双脚分开与肩同宽站立，并用正手握住电缆手柄。","保持背部挺直，核心肌群参与。","将电缆手柄举到您面前，保持手臂伸直，手掌朝下。","继续抬起，直到手臂与地板平行。","在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0165","name":"cable hammer curl (with rope)","nameZh":"绳索锤式弯举 (带绳索)","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0165-HPlPoQA.jpg","gifPath":"exercises/videos/0165-HPlPoQA.gif","instructionSteps":["站直，双脚分开与肩同宽，膝盖稍微弯曲。","双手握住缆绳附件，手掌相对，手臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续提升缆绳附件，直到您的二头肌完全收缩并且绳索与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将缆绳附件降低回起始位置。","重复所需的重复次数。"]},{"id":"0167","name":"cable high row (kneeling)","nameZh":"绳索高位划船 (跪姿)","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0167-ZSJNetl.jpg","gifPath":"exercises/videos/0167-ZSJNetl.gif","instructionSteps":["将直杆连接到胸部高度的缆绳机上。","跪在缆绳机前，用正握方式抓住杠铃，双手与肩同宽。","坐在脚后跟上，保持背部挺直，核心肌群参与。","将杠铃拉向上腹部，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开杠铃回到起始位置。","重复所需的重复次数。"]},{"id":"0168","name":"cable hip adduction","nameZh":"绳索髋内收","equipment":"cable","bodyPart":"upper legs","target":"adductors","imagePath":"exercises/images/0168-hBGWILP.jpg","gifPath":"exercises/videos/0168-hBGWILP.gif","instructionSteps":["将脚踝套戴到脚踝上，面向电缆机站立。","将自己放置在距离机器足够远的位置，以便电缆上有张力。","将手放在机器上以获得支撑。","保持腿伸直，慢慢将腿移向身体中线。","动作结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0169","name":"cable incline bench press","nameZh":"绳索上斜卧推","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0169-Vh0GsK4.jpg","gifPath":"exercises/videos/0169-Vh0GsK4.gif","instructionSteps":["将长凳调整至 45 度倾斜。","将电缆手柄连接到高滑轮上。","坐在长凳上，面向电缆机，双脚平放在地面上。","正手握住手柄，并将其拉至肩部高度。","向前和向上推动手柄，直到手臂完全伸展。","暂停片刻，然后慢慢将手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0170","name":"cable incline fly (on stability ball)","nameZh":"绳索上斜飞鸟 (在稳定球)","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0170-27NNGFr.jpg","gifPath":"exercises/videos/0170-27NNGFr.gif","instructionSteps":["以倾斜角度设置稳定球。","将电缆手柄连接到电缆机的高滑轮上。","背对机器坐在稳定球上，双脚牢牢踩在地面上。","正手握住电缆手柄，手掌朝前。","稍微向前倾，保持背部挺直，核心参与。","控制动作，将手臂向两侧伸出，保持肘部轻微弯曲。","继续这个动作，直到手臂与地面平行。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0171","name":"cable incline fly","nameZh":"绳索上斜飞鸟","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0171-tBWXbIT.jpg","gifPath":"exercises/videos/0171-tBWXbIT.gif","instructionSteps":["将电缆机调整至较低位置并安装手柄。","坐在倾斜的长凳上，背部靠在垫子上，双脚平放在地板上。","正手握住手柄，并将双臂伸直至身前。","保持肘部轻微弯曲，以受控的动作向两侧张开双臂。","在完全伸展位置停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0172","name":"cable incline pushdown","nameZh":"绳索上斜下压","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0172-1PK5Uo3.jpg","gifPath":"exercises/videos/0172-1PK5Uo3.gif","instructionSteps":["将直杆连接到高滑轮电缆机上。","背对机器站立，双脚与肩同宽。","正手握住杠铃，双手距离略宽于肩宽。","稍微向前倾并保持背部挺直。","伸展肘部，将杠铃向下拉向大腿。","在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"]},{"id":"0173","name":"cable incline triceps extension","nameZh":"绳索上斜肱三头肌伸展","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0173-Hx1WC8I.jpg","gifPath":"exercises/videos/0173-Hx1WC8I.gif","instructionSteps":["将拉索机调整至低滑轮位置。","将直杆连接到电缆上。","背对机器站立，双脚与肩同宽。","正手握住杠铃，并将手臂伸直过头顶。","稍微向前倾，保持背部挺直，核心参与。","弯曲肘部，将杠铃放低到脑后，保持上臂靠近耳朵。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"]},{"id":"0174","name":"cable judo flip","nameZh":"绳索柔道翻转","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0174-MvQPqVW.jpg","gifPath":"exercises/videos/0174-MvQPqVW.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","用双手握住电缆手柄，使其与胸部齐平，手掌朝下。","启动你的核心并将你的躯干向右旋转，将电缆拉过你的身体。","当你旋转时，转动后脚并让臀部自然旋转。","充分伸展双臂，将绳索手柄翻转到肩膀上来完成动作。","通过反向运动返回起始位置，将躯干旋转回中心。","在另一侧重复该动作。","继续交替进行所需的重复次数。"]},{"id":"0175","name":"cable kneeling crunch","nameZh":"绳索卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0175-WW95auq.jpg","gifPath":"exercises/videos/0175-WW95auq.gif","instructionSteps":["将绳索手柄连接到高滑轮上，然后面向远离机器的方向跪下。","双手握住绳柄，将其放在脑后，肘部向两侧伸出。","保持臀部不动，弯曲腰部并将躯干向大腿方向挤压。","在底部停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0176","name":"cable kneeling triceps extension","nameZh":"绳索跪姿肱三头肌伸展","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0176-KWdF2JI.jpg","gifPath":"exercises/videos/0176-KWdF2JI.gif","instructionSteps":["将绳索手柄连接到高滑轮上，面向绳索机跪下。","以中立握法（手掌相对）抓住绳子，并将双手放在头的两侧。","在整个练习过程中，保持肘部靠近头部，上臂保持静止。","通过收缩三头肌来伸展前臂，直到手臂完全伸展。","暂停片刻，然后弯曲肘部慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0177","name":"cable lateral pulldown (with rope attachment)","nameZh":"绳索侧向下拉 (带绳索附件)","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0177-CuaWCmC.jpg","gifPath":"exercises/videos/0177-CuaWCmC.gif","instructionSteps":["将绳索附件连接到电缆机的高位置。","面向机器站立，双脚分开与肩同宽。","正手握住绳子，手掌相对。","保持背部挺直并稍微向后倾斜。","将绳子向下拉向身体两侧，将肩胛骨挤压在一起。","在动作的底部停顿片刻。","慢慢释放张力，让绳子回到起始位置。","重复所需的重复次数。"]},{"id":"0178","name":"cable lateral raise","nameZh":"绳索侧平举","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0178-goJ6ezq.jpg","gifPath":"exercises/videos/0178-goJ6ezq.gif","instructionSteps":["双脚分开与肩同宽站立，并用正手握住电缆手柄。","保持双臂伸直，核心肌群参与。","将手臂向两侧举起，直到与地板平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0179","name":"cable low fly","nameZh":"绳索低位飞鸟","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0179-FVmZVhk.jpg","gifPath":"exercises/videos/0179-FVmZVhk.gif","instructionSteps":["将手柄连接到缆绳机的低滑轮上，并选择合适的重量。","站在机器中间，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住手柄，将手臂向两侧伸展，肘部保持轻微弯曲。","保持控制，以扫过的动作缓慢地将手臂向前伸，交叉在身体前面。","在运动的最高点暂停片刻，感受胸部肌肉的拉伸。","反转动作，慢慢将手臂恢复到起始位置，始终保持胸部肌肉紧张。","重复所需的重复次数。"]},{"id":"0180","name":"cable low seated row","nameZh":"绳索低位坐姿划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0180-hvV79Si.jpg","gifPath":"exercises/videos/0180-hvV79Si.gif","instructionSteps":["坐在机器上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住手柄，手掌朝下。","保持背部挺直，稍微向前倾斜，肘部保持轻微弯曲。","将手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0182","name":"cable lying close-grip curl","nameZh":"绳索仰卧窄距弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0182-61GrD55.jpg","gifPath":"exercises/videos/0182-61GrD55.gif","instructionSteps":["将直杆连接到低滑轮电缆机上。","面朝上躺在平坦的长凳上，双脚平放在地上。","反手握住杠铃，双手与肩同宽。","充分伸展双臂，保持肘部靠近身体两侧。","保持上臂静止，通过收缩二头肌将杠铃卷向胸部。","在顶部暂停片刻，挤压你的二头肌。","慢慢地将杠铃放回起始位置，充分伸展双臂。","重复所需的重复次数。"]},{"id":"0184","name":"cable lying extension pullover (with rope attachment)","nameZh":"绳索仰卧伸展仰卧屈臂上拉 (带绳索附件)","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0184-Q2Eu1Ax.jpg","gifPath":"exercises/videos/0184-Q2Eu1Ax.gif","instructionSteps":["将绳子连接到缆绳机上，并将滑轮设置在最高位置。","躺在长凳上，头朝向电缆机。","双手握住绳子，将双臂伸直至胸部上方。","保持双臂伸直，在保持控制的同时慢慢将绳子放到脑后。","在底部停顿片刻，然后慢慢将绳子拉回起始位置。","重复所需的重复次数。"]},{"id":"0185","name":"cable lying fly","nameZh":"绳索仰卧飞鸟","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0185-lJJ7Yq8.jpg","gifPath":"exercises/videos/0185-lJJ7Yq8.gif","instructionSteps":["将手柄连接到电缆上，平放在长凳上，双脚平放在地面上。","手掌相对，握住手柄，双臂伸直至胸部上方。","保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后挤压胸部肌肉，使手臂回到起始位置。","重复所需的重复次数。"]},{"id":"0186","name":"cable lying triceps extension v. 2","nameZh":"绳索仰卧肱三头肌伸展版本 2","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0186-uxJcFUU.jpg","gifPath":"exercises/videos/0186-uxJcFUU.gif","instructionSteps":["将绳索手柄连接到低滑轮电缆机器上。","面朝上躺在平坦的长凳上，头朝向电缆机。","双手抓住绳柄，掌心相对，将双臂伸直至胸前。","保持上臂静止，弯曲肘部，慢慢将绳索手柄放低至前额。","在底部停顿片刻，然后将手臂伸回起始位置。","重复所需的重复次数。"]},{"id":"0188","name":"cable middle fly","nameZh":"绳索夹胸","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0188-xLYSdtg.jpg","gifPath":"exercises/videos/0188-xLYSdtg.gif","instructionSteps":["将电缆连接到电缆机两侧胸部高度处。","站在机器的中央，一只脚稍微在另一只脚前面。","正手握住手柄，并将手臂向两侧伸展。","保持肘部轻微弯曲并保持轻微前倾。","收紧胸部肌肉，并以扫过的动作将手臂向前伸。","在中心停顿片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0189","name":"cable one arm bent over row","nameZh":"绳索单臂俯身划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0189-EIsE3u8.jpg","gifPath":"exercises/videos/0189-EIsE3u8.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","用一只手抓住电缆手柄，手掌朝内，然后完全伸展手臂。","将电缆手柄拉向身体，保持肘部靠近身体一侧，直到手到达下胸部。","暂停片刻，然后慢慢将手臂伸回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0190","name":"cable one arm curl","nameZh":"绳索单臂弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0190-YTur5nR.jpg","gifPath":"exercises/videos/0190-YTur5nR.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","反手握住电缆手柄，手掌朝上。","保持肘部靠近身体两侧，慢慢地将前臂向上卷向肩膀。","在顶部暂停片刻，然后慢慢将前臂放回起始位置。","重复所需的重复次数。"]},{"id":"0191","name":"cable one arm lateral bent-over","nameZh":"绳索单臂侧向俯身","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0191-dB07vDu.jpg","gifPath":"exercises/videos/0191-dB07vDu.gif","instructionSteps":["双脚分开与肩同宽站立，面向缆绳机。","用一只手抓住手柄并向后退一步以在电缆上产生张力。","腰部向前弯曲，保持背部挺直，核心肌群参与。","将手臂向侧面伸展，与地面平行，肘部稍微弯曲。","慢慢地将手臂放回起始位置，在整个运动过程中保持控制。","重复所需的重复次数，然后换边。"]},{"id":"0192","name":"cable one arm lateral raise","nameZh":"绳索单臂侧平举","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0192-wEulIzp.jpg","gifPath":"exercises/videos/0192-wEulIzp.gif","instructionSteps":["双脚分开与肩同宽站立，面向绳索机。","用一只手握住电缆手柄，手掌朝下，站得离机器足够远，以便电缆上有张力。","保持手臂伸直，慢慢向一侧举起，直到与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0193","name":"cable one arm straight back high row (kneeling)","nameZh":"绳索单臂直背高位划船 (跪姿)","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0193-WrYPP2g.jpg","gifPath":"exercises/videos/0193-WrYPP2g.gif","instructionSteps":["将手柄连接到腰部高度的缆绳机上。","面向电缆机跪下，用一只手抓住手柄。","保持背部挺直，核心肌群参与。","将手柄拉向胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻。","慢慢松开手柄回到起始位置。","重复所需的重复次数。","换边并用另一只手臂重复练习。"]},{"id":"0194","name":"cable overhead triceps extension (rope attachment)","nameZh":"绳索过头肱三头肌伸展 (绳索附件)","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0194-2IxROQ1.jpg","gifPath":"exercises/videos/0194-2IxROQ1.gif","instructionSteps":["将绳索连接到高处的缆绳机上。","背对机器站立，双脚与肩同宽。","双手抓住绳子，掌心相对，将双手举过头顶。","保持上臂靠近头部，肘部向前。","弯曲肘部，慢慢将绳子降低到头后。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"]},{"id":"0195","name":"cable preacher curl","nameZh":"绳索牧师凳弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0195-P2lNrGL.jpg","gifPath":"exercises/videos/0195-P2lNrGL.gif","instructionSteps":["调整绳索机，使牧师弯举垫处于胸部高度。","坐在牧师弯举凳上，将上臂放在垫子上，用反手抓住电缆附件。","保持背部挺直，肘部放在身体两侧。","慢慢地将电缆附件向肩膀方向卷曲，在动作的最高点挤压二头肌。","暂停片刻，然后慢慢将电缆附件放回起始位置。","重复所需的重复次数。"]},{"id":"0196","name":"cable pull through (with rope)","nameZh":"绳索穿腿后拉 (带绳索)","equipment":"cable","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0196-OM46QHm.jpg","gifPath":"exercises/videos/0196-OM46QHm.gif","instructionSteps":["背对缆绳机站立，双脚与肩同宽。","双手抓住绳索附件并向前迈一步，在绳索中产生张力。","弯曲臀部并降低上身直至与地面平行，保持背部挺直。","启动臀肌和腿筋，将身体拉回到起始位置。","重复所需的重复次数。"]},{"id":"0197","name":"cable pulldown (pro lat bar)","nameZh":"绳索下拉 (专业背阔肌杆)","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0197-qdRxqCj.jpg","gifPath":"exercises/videos/0197-qdRxqCj.gif","instructionSteps":["调整座椅高度，使大腿与地面平行，双脚平放在地板上。","正手握住背阔肌杠铃，握距略宽于肩宽。","坐下来，稍微向后倾斜，保持挺胸、背部挺直。","将杠铃向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。","重复所需的重复次数。"]},{"id":"0198","name":"cable pulldown","nameZh":"高位下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0198-RVwzP10.jpg","gifPath":"exercises/videos/0198-RVwzP10.gif","instructionSteps":["调整拉索下拉机，使座椅处于舒适的高度并固定护膝。","坐在座位上，背部挺直，双脚平放在地面上。","正手握住电缆杆，握距略宽于肩宽。","稍微向后倾斜并启动你的核心。","将电缆杆向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢松开杠铃回到起始位置。","重复所需的重复次数。"]},{"id":"0199","name":"cable pushdown (straight arm) v. 2","nameZh":"绳索下压 (直臂) 版本 2","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0199-PskORrA.jpg","gifPath":"exercises/videos/0199-PskORrA.gif","instructionSteps":["将直杆连接到高滑轮电缆机上。","面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，保持手臂伸直，手掌朝下。","呼气时，收紧核心并保持背部挺直，并将杠铃向下推向大腿。","在底部暂停片刻，然后一边吸气，一边慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"]},{"id":"0200","name":"cable pushdown (with rope attachment)","nameZh":"绳索下压 (带绳索附件)","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0200-dU605di.jpg","gifPath":"exercises/videos/0200-dU605di.gif","instructionSteps":["将绳索附件连接到缆绳机上的高滑轮上。","面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住绳子，手掌相对。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","呼气并伸展肘部将绳子向下推，直到手臂完全伸展。","暂停片刻，然后吸气，并让肘部弯曲，慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0201","name":"cable pushdown","nameZh":"绳索下压","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0201-3ZflifB.jpg","gifPath":"exercises/videos/0201-3ZflifB.gif","instructionSteps":["将直杆连接到高滑轮电缆机上。","面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。","正手握住杠铃，双手与肩同宽。","保持肘部靠近身体两侧，上臂保持静止。","呼气并将杠铃向下推，直到肘部完全伸展。","暂停片刻，然后吸气，慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"]},{"id":"0202","name":"cable rear delt row (stirrups)","nameZh":"绳索后三角肌划船 (马镫)","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0202-yUdIGNs.jpg","gifPath":"exercises/videos/0202-yUdIGNs.gif","instructionSteps":["将马镫手柄连接到低电缆滑轮上，面向机器站立。","左手抓住手柄，右脚后退一步，身体保持一个轻微的角度。","稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。","左臂伸展，手掌朝下，通过缩回肩胛骨将手柄拉向胸部。","在动作的最高点暂停片刻，挤压肩胛骨。","慢慢地将手柄释放回起始位置，然后重复所需的重复次数。","换边并用右臂重复练习。"]},{"id":"0203","name":"cable rear delt row (with rope)","nameZh":"绳索后三角肌划船 (带绳索)","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0203-wqNPGCg.jpg","gifPath":"exercises/videos/0203-wqNPGCg.gif","instructionSteps":["将绳索手柄连接到低滑轮电缆机器上。","面向机器站立，双脚分开与肩同宽。","正手握住绳索手柄，手掌相对。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","保持肘部稍微弯曲，将绳子拉向胸部，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"0204","name":"cable rear drive","nameZh":"绳索后驱动","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0204-c3QQLPi.jpg","gifPath":"exercises/videos/0204-c3QQLPi.gif","instructionSteps":["将手柄连接到低滑轮电缆机器上，并背对机器站立。","正手握住手柄，并将双臂伸直至身前。","保持肘部不动，将手柄拉回身体，在动作结束时挤压三头肌。","慢慢地将手柄返回到起始位置，然后重复所需的重复次数。"]},{"id":"0205","name":"cable rear pulldown","nameZh":"绳索后下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0205-SpsOSXk.jpg","gifPath":"exercises/videos/0205-SpsOSXk.gif","instructionSteps":["调整拉索机，使滑轮处于最高位置。","面向机器坐着，双脚平放在地面上，膝盖稍微弯曲。","正手握住电缆附件，双手之间的距离略大于肩宽。","稍微向后倾斜，保持背部挺直，挺胸。","将电缆附件向下拉向胸部，将肩胛骨挤压在一起。","在动作底部停顿片刻，然后慢慢松开绳索回到起始位置。","重复所需的重复次数。"]},{"id":"0206","name":"cable reverse curl","nameZh":"绳索反向弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0206-eOG0r6v.jpg","gifPath":"exercises/videos/0206-eOG0r6v.gif","instructionSteps":["将直杆连接到低滑轮电缆机上。","面向机器站立，双脚分开与肩同宽，膝盖稍微弯曲。","反手握住杠铃，双手与肩同宽。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","呼气并将杠铃向上卷向肩膀，收缩二头肌。","在顶部暂停片刻，挤压你的二头肌。","吸气，慢慢将杠铃放回起始位置，充分伸展双臂。","重复所需的重复次数。"]},{"id":"0207","name":"cable reverse-grip pushdown","nameZh":"绳索反向-握下压","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0207-VjYliFZ.jpg","gifPath":"exercises/videos/0207-VjYliFZ.gif","instructionSteps":["将直杆连接到高滑轮电缆机上。","面向机器站立，双脚分开与肩同宽。","反手握住杠铃，手掌朝上，双手与肩同宽。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","使用三头肌，将杠铃向下推，直到手臂完全伸展并且三头肌收缩。","暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"]},{"id":"0208","name":"cable reverse-grip straight back seated high row","nameZh":"绳索反向-握直背坐姿高位划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0208-PNtsX17.jpg","gifPath":"exercises/videos/0208-PNtsX17.gif","instructionSteps":["坐在面向电缆机的座位上，双脚平放在地板上。","用手握住电缆附件，手掌朝上，双手与肩同宽。","保持背部挺直，并从臀部稍微向前倾斜。","通过缩回肩胛骨并挤压背部肌肉，将电缆拉向躯干。","在收缩的峰值处暂停片刻，然后慢慢地将电缆释放回起始位置。","重复所需的重复次数。"]},{"id":"0209","name":"cable reverse preacher curl","nameZh":"绳索反向牧师凳弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0209-IwX5NqK.jpg","gifPath":"exercises/videos/0209-IwX5NqK.gif","instructionSteps":["调整绳索机，使牧师弯举垫处于胸部高度。","坐在牧师弯举凳上，将上臂放在垫子上，手掌朝下，肘部完全伸展。","反手抓住电缆手柄，距离与肩同宽。","保持上臂静止，呼气并将手柄向肩膀卷曲，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气，慢慢将手柄放回起始位置，充分伸展肘部。","重复所需的重复次数。"]},{"id":"0210","name":"cable reverse wrist curl","nameZh":"绳索反手腕弯举","equipment":"cable","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0210-eYmsEPR.jpg","gifPath":"exercises/videos/0210-eYmsEPR.gif","instructionSteps":["将电缆连接到低滑轮上，然后坐在面向电缆机的长凳上。","正手握住电缆手柄，手掌朝下。","将前臂放在大腿上，手腕悬在边缘上。","保持前臂静止，呼气并尽可能向上弯曲手腕。","在顶部暂停片刻，然后吸气并慢慢将手腕放回起始位置。","重复所需的重复次数。"]},{"id":"0211","name":"cable russian twists (on stability ball)","nameZh":"绳索俄罗斯转体s (在稳定球)","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0211-d9Xaxq6.jpg","gifPath":"exercises/videos/0211-d9Xaxq6.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","双手握住电缆手柄，并将双臂伸直至前方。","稍微向后倾斜，同时保持背部挺直并且核心参与。","将躯干向右扭转，将电缆手柄拉向右臀部。","暂停片刻，然后将躯干向左扭转，将电缆手柄拉向左臀部。","继续交替扭转所需的重复次数。"]},{"id":"0212","name":"cable seated crunch","nameZh":"绳索坐姿卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0212-8xUv4J7.jpg","gifPath":"exercises/videos/0212-8xUv4J7.gif","instructionSteps":["坐在缆绳机上，双脚平放在地面上，膝盖弯曲。","用双手握住电缆手柄并将其放在脑后。","收紧腹肌，慢慢向前弯曲上半身，使胸部靠近膝盖。","在顶部停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0213","name":"cable seated high row (v-bar)","nameZh":"绳索坐姿高位划船 (V 杆)","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0213-pwt0pnM.jpg","gifPath":"exercises/videos/0213-pwt0pnM.gif","instructionSteps":["坐在缆绳机上，双脚平放在地板上，膝盖稍微弯曲。","正手握住 V 形杆附件，手掌相对，双手与肩同宽。","保持背部挺直，并从臀部稍微向前倾斜。","通过收缩肩胛骨并挤压背部肌肉，将 V 形杆拉向躯干。","在收缩的顶峰停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"0214","name":"cable seated one arm alternate row","nameZh":"绳索坐姿单臂交替划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0214-vpp9Ku2.jpg","gifPath":"exercises/videos/0214-vpp9Ku2.gif","instructionSteps":["坐在长凳上，面对缆绳机，双脚平放在地面上，膝盖稍微弯曲。","用一只手抓住手柄，并将手臂完全伸展到身前。","将手柄拉向身体，缩回肩胛骨并保持肘部靠近身体两侧。","在动作的最高点暂停片刻，挤压背部肌肉。","慢慢松开手柄回到起始位置。","用另一只手臂重复上述步骤。","双臂交替进行所需的重复次数。"]},{"id":"0215","name":"cable seated rear lateral raise","nameZh":"绳索坐姿后侧平举","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0215-x825CZm.jpg","gifPath":"exercises/videos/0215-x825CZm.gif","instructionSteps":["坐在长凳上，面向电缆机，双脚平放在地面上。","正手握住电缆手柄，并将双臂伸直至前方。","保持手臂伸直，慢慢向两侧举起，直到与地板平行。","在顶部停顿片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0216","name":"cable seated shoulder internal rotation","nameZh":"绳索坐姿肩内旋","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0216-YPoVrBi.jpg","gifPath":"exercises/videos/0216-YPoVrBi.gif","instructionSteps":["坐在长凳或椅子上，面向电缆机，双脚平放在地面上。","握住电缆手柄，手臂在身前伸直，与地面平行。","保持肘部稍微弯曲，肩胛骨向后和向下拉。","慢慢向内旋转手臂，将电缆手柄拉向身体中心。","动作结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0218","name":"cable seated wide-grip row","nameZh":"绳索坐姿宽距划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0218-qcY50ZD.jpg","gifPath":"exercises/videos/0218-qcY50ZD.gif","instructionSteps":["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手宽握握住手柄，手掌朝下。","保持背部挺直，并从臀部稍微向前倾斜。","将手柄拉向下胸部，将肩胛骨挤压在一起。","在收缩高峰时暂停片刻。","慢慢松开手柄回到起始位置，充分伸展双臂。","重复所需的重复次数。"]},{"id":"0219","name":"cable shoulder press","nameZh":"绳索肩推","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0219-PzQanLE.jpg","gifPath":"exercises/videos/0219-PzQanLE.gif","instructionSteps":["调整绳索机，使手柄位于肩部高度。","背对机器站立，双脚与肩同宽。","正手握住手柄，将其提升至肩部水平，肘部弯曲并指向外侧。","向上按压手柄，直到手臂完全伸过头顶。","在顶部暂停片刻，然后慢慢将手柄放回至肩部水平。","重复所需的重复次数。"]},{"id":"0220","name":"cable shrug","nameZh":"绳索耸肩","equipment":"cable","bodyPart":"back","target":"traps","imagePath":"exercises/images/0220-Eg98Ft9.jpg","gifPath":"exercises/videos/0220-Eg98Ft9.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","正手握住电缆手柄，让手臂垂在身前。","保持手臂伸直，耸肩向耳朵方向向上。","保持收缩一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0221","name":"cable side bend crunch (bosu ball)","nameZh":"绳索体侧屈卷腹 (波速球)","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0221-qatbkEd.jpg","gifPath":"exercises/videos/0221-qatbkEd.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住电缆手柄。","将另一只手放在臀部上。","启动你的核心，慢慢向握住电缆的手侧弯，保持背部挺直。","在动作底部暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0222","name":"cable side bend","nameZh":"绳索体侧屈","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0222-wPypxFY.jpg","gifPath":"exercises/videos/0222-wPypxFY.gif","instructionSteps":["双脚分开与肩同宽站立，用一只手抓住电缆手柄。","保持背部挺直，核心肌群参与。","腰部慢慢向侧面弯曲，将电缆手柄向膝盖方向降低。","暂停片刻，然后回到起始位置。","在另一侧重复。","交替进行所需的重复次数。"]},{"id":"0223","name":"cable side crunch","nameZh":"绳索侧卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0223-q2ADGqV.jpg","gifPath":"exercises/videos/0223-q2ADGqV.gif","instructionSteps":["将电缆手柄连接到低滑轮上并站在机器旁边。","用距离机器最远的手抓住手柄，并将另一只手放在臀部上。","双脚分开与肩同宽，膝盖稍微弯曲。","收紧腹肌，腰部向侧面弯曲，将肘部向下拉向臀部。","在底部停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0224","name":"cable standing back wrist curl","nameZh":"绳索站姿背部手腕弯举","equipment":"cable","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0224-VhX2JdE.jpg","gifPath":"exercises/videos/0224-VhX2JdE.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","正手握住电缆手柄，手掌朝下。","保持手臂伸直，肘部靠近身体两侧。","慢慢向上弯曲手腕，将电缆手柄拉向身体。","在顶部暂停片刻，然后慢慢将拉索手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0225","name":"cable standing cross-over high reverse fly","nameZh":"绳索站姿交叉高位反向飞鸟","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0225-P5p0j8B.jpg","gifPath":"exercises/videos/0225-P5p0j8B.gif","instructionSteps":["将 D 形手柄安装到缆绳机两侧与肩同高的位置。","站在缆绳机的中间，双脚分开与肩同宽。","正手握住手柄，并将手臂向两侧伸展，手掌朝前。","在整个练习过程中保持肘部轻微弯曲并保持背部挺直。","当您将手柄拉向身体前方时，收紧肩部肌肉并将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0226","name":"cable standing crunch","nameZh":"绳索站姿卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0226-jpgqxiS.jpg","gifPath":"exercises/videos/0226-jpgqxiS.gif","instructionSteps":["将电缆手柄连接到高滑轮上，并背对机器站立。","双手握住手柄并将其放在脑后，保持肘部弯曲。","双脚分开与肩同宽站立，膝盖稍微弯曲。","保持腹肌收紧，呼气，将躯干压向膝盖，将肘部拉向大腿。","在动作底部暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0227","name":"cable standing fly","nameZh":"绳索站姿飞鸟","equipment":"cable","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0227-Pr9Rhf4.jpg","gifPath":"exercises/videos/0227-Pr9Rhf4.gif","instructionSteps":["将手柄连接到胸部高度的电缆上。","双脚分开与肩同宽站立，背对缆绳机。","正手握住手柄，手掌朝前。","稍微向前一步以在缆绳中产生张力。","在整个练习过程中保持核心参与并保持背部挺直。","肘部稍微弯曲，慢慢地将双臂向前并拢在胸前。","在运动的最高点挤压胸部肌肉。","慢慢扭转动作，将手臂恢复到起始位置。","重复所需的重复次数。"]},{"id":"0228","name":"cable standing hip extension","nameZh":"绳索站姿髋伸展","equipment":"cable","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0228-Kpajagk.jpg","gifPath":"exercises/videos/0228-Kpajagk.gif","instructionSteps":["将电缆连接到低滑轮上，并背对机器站立。","将电缆绕在脚踝上，双脚分开与肩同宽站立。","在整个练习过程中保持核心参与并保持背部挺直。","慢慢地将腿向后伸直，在动作的最高点挤压臀部。","暂停片刻，然后回到起始位置。","重复所需的重复次数。","换边并用另一条腿重复。"]},{"id":"0229","name":"cable standing inner curl","nameZh":"绳索站姿内侧弯举","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0229-YwnI4ja.jpg","gifPath":"exercises/videos/0229-YwnI4ja.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","反手握住电缆手柄，手掌朝上。","保持肘部靠近身体两侧，上臂保持静止。","呼气并将绳索手柄卷向肩膀，收缩二头肌。","在动作的最高点暂停片刻，挤压你的二头肌。","吸气并缓慢地将电缆手柄放回起始位置。","重复所需的重复次数。"]},{"id":"0230","name":"cable standing lift","nameZh":"绳索站姿上提","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0230-qFpAkpP.jpg","gifPath":"exercises/videos/0230-qFpAkpP.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","双手握住电缆手柄并将其置于腰部高度。","在整个练习过程中启动核心并保持背部挺直。","保持手臂伸直，呼气并将电缆手柄向另一侧的肩膀向上提起，同时旋转躯干。","在顶部暂停片刻，然后吸气并慢慢将拉索手柄放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0231","name":"cable standing one arm triceps extension","nameZh":"绳索站姿单臂肱三头肌伸展","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0231-sYCcnon.jpg","gifPath":"exercises/videos/0231-sYCcnon.gif","instructionSteps":["双脚分开与肩同宽站立，面向绳索机。","用右手握住电缆手柄，掌心朝下，调整手臂位置，使其完全伸展并与地面平行。","保持肘部静止并靠近身体。","慢慢弯曲肘部，将电缆手柄向脑后降低。","在动作底部停顿片刻，然后将手臂伸回起始位置。","重复所需的重复次数，然后换边并用左臂进行练习。"]},{"id":"0232","name":"cable standing pulldown (with rope)","nameZh":"绳索站姿下拉 (带绳索)","equipment":"cable","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0232-CvPn9WV.jpg","gifPath":"exercises/videos/0232-CvPn9WV.gif","instructionSteps":["将绳索连接到最高设置的缆绳机上。","面向机器站立，双脚分开与肩同宽。","正手握住绳子，手掌朝下。","在整个练习过程中保持背部挺直并保持核心参与。","将绳子向下拉向大腿，挤压二头肌。","在底部停顿片刻，然后慢慢地将绳子放回原位。","重复所需的重复次数。"]},{"id":"0233","name":"cable standing rear delt row (with rope)","nameZh":"绳索面拉","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0233-ZfyAGhK.jpg","gifPath":"exercises/videos/0233-ZfyAGhK.gif","instructionSteps":["面向缆绳机站立，双脚与肩同宽。","用双手握住电缆附件，手掌相对，然后后退以在电缆中产生张力。","保持背部挺直，核心肌群参与。","将电缆拉向您的身体，将肩胛骨挤压在一起。","在运动的最高点停顿片刻，然后慢慢松开绳索回到起始位置。","重复所需的重复次数。"]},{"id":"0234","name":"cable standing row (v-bar)","nameZh":"绳索站姿划船 (V 杆)","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0234-4f8RXP8.jpg","gifPath":"exercises/videos/0234-4f8RXP8.gif","instructionSteps":["面对电缆机站立，双脚与肩同宽。","正手握住 V 形杆附件，手掌朝下。","保持背部挺直，核心肌群参与。","将 V 形杆拉向身体，将肩胛骨挤压在一起。","在动作的最高点停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"0235","name":"cable standing shoulder external rotation","nameZh":"绳索站姿肩外旋","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0235-FWdVhcW.jpg","gifPath":"exercises/videos/0235-FWdVhcW.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","将手臂伸向前方，与地面平行，握住电缆手柄。","保持肘部稍微弯曲，肩胛骨向后拉。","慢慢地向外旋转手臂，远离身体，同时保持肘部处于同一位置。","动作结束时暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数。"]},{"id":"0236","name":"cable standing twist row (v-bar)","nameZh":"绳索站姿转体划船 (V 杆)","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0236-JOZhu2h.jpg","gifPath":"exercises/videos/0236-JOZhu2h.gif","instructionSteps":["将 V 形杆附件连接到胸部高度的缆绳机上。","面对电缆机站立，双脚与肩同宽。","正手握住 V 形杆，手掌朝下。","后退一步以在电缆中产生张力。","在整个练习过程中保持背部挺直并保持核心参与。","缩回肩胛骨并弯曲肘部，将 V 形杆拉向躯干。","当你拉的时候，将你的躯干扭转到一侧，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，感受上背部的收缩。","慢慢释放紧张并回到起始位置，松开躯干。","重复该动作达到所需的重复次数，每次重复交替扭转方向。"]},{"id":"0237","name":"cable straight arm pulldown (with rope)","nameZh":"绳索直臂下拉 (带绳索)","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0237-DT14T9T.jpg","gifPath":"exercises/videos/0237-DT14T9T.gif","instructionSteps":["将绳索连接到最高设置的缆绳机上。","面向机器站立，双脚分开与肩同宽。","双手抓住绳子，掌心朝下。","将手臂完全伸展到身前，保持肘部稍微弯曲。","收紧背阔肌，慢慢地将绳子向下拉向大腿，保持手臂伸直。","在底部停顿片刻，然后慢慢释放张力，回到起始位置。","重复所需的重复次数。"]},{"id":"0238","name":"cable straight arm pulldown","nameZh":"绳索直臂下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0238-x69MAlq.jpg","gifPath":"exercises/videos/0238-x69MAlq.gif","instructionSteps":["将直杆连接到缆绳机的高滑轮上。","面向机器站立，双脚分开与肩同宽。","正手握住杠铃，保持手臂伸直，手掌朝下。","收紧背阔肌并将杠铃向下拉向大腿，在整个运动过程中保持手臂伸直。","在底部暂停片刻，然后慢慢地将杠铃返回到起始位置。","重复所需的重复次数。"]},{"id":"0239","name":"cable straight back seated row","nameZh":"绳索直背坐姿划船","equipment":"cable","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0239-Tq6gbK6.jpg","gifPath":"exercises/videos/0239-Tq6gbK6.gif","instructionSteps":["坐在电缆划船机上，双脚平放在脚踏板上，膝盖稍微弯曲。","正手握住电缆手柄，手掌朝下。","保持背部挺直，并从臀部稍微向前倾斜。","将电缆手柄拉向身体，将肩胛骨挤压在一起。","在动作的最高点暂停片刻，然后慢慢松开手柄回到起始位置。","重复所需的重复次数。"]},{"id":"0240","name":"cable supine reverse fly","nameZh":"绳索仰卧反向飞鸟","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0240-PQcUlDi.jpg","gifPath":"exercises/videos/0240-PQcUlDi.gif","instructionSteps":["将 D 形手柄连接到低滑轮缆绳机上，并面朝下躺在平凳上。","每只手握住 D 形手柄，手掌朝下，并将双臂伸直至前方。","保持手臂伸直，将它们向两侧举起，直到与地板平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0241","name":"cable triceps pushdown (v-bar)","nameZh":"绳索肱三头肌下压 (V 杆)","equipment":"cable","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0241-gAwDzB3.jpg","gifPath":"exercises/videos/0241-gAwDzB3.gif","instructionSteps":["在最高设置下将 V 形杆附件连接到电缆机上。","面对电缆机站立，双脚与肩同宽。","正手握住 V 形杆，手掌朝下，双手与肩同宽。","在整个练习过程中，保持肘部靠近身体两侧，上臂保持静止。","收紧三头肌并呼气，同时向下推 V 形杆，直到手臂完全伸展。","在动作的底部暂停片刻，挤压你的三头肌。","吸气，同时缓慢地将 V 形杆返回到起始位置，保持控制。","重复所需的重复次数。"]},{"id":"0242","name":"cable tuck reverse crunch","nameZh":"绳索蜷身反向卷腹","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0242-TXtXc84.jpg","gifPath":"exercises/videos/0242-TXtXc84.gif","instructionSteps":["将电缆连接到低滑轮上，然后面朝上躺在垫子上。","用双手握住电缆并将双臂伸直至胸部上方。","弯曲膝盖并抬起双腿，使膝盖靠近胸部。","同时，将骨盆向胸部弯曲，将臀部抬离地面。","在顶部暂停片刻，然后慢慢降低双腿和臀部回到起始位置。","重复所需的重复次数。"]},{"id":"0243","name":"cable twist","nameZh":"绳索转体","equipment":"cable","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0243-aVs3BR3.jpg","gifPath":"exercises/videos/0243-aVs3BR3.gif","instructionSteps":["双脚分开与肩同宽站立，面向绳索机。","双手握住电缆手柄于胸前，保持双臂略微弯曲。","启动你的核心并将你的躯干向右扭转，将电缆拉过你的身体。","动作结束时暂停片刻，感受腹肌和斜肌的收缩。","缓慢返回起始位置，抵抗绳索的拉力。","向左侧重复该动作。","继续交替进行所需的重复次数。"]},{"id":"0244","name":"cable twisting pull","nameZh":"绳索扭转拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0244-zCgxPbV.jpg","gifPath":"exercises/videos/0244-zCgxPbV.gif","instructionSteps":["将电缆手柄连接到低滑轮上并面向机器站立。","用左手抓住手柄，离开机器，完全伸展手臂。","双脚分开与肩同宽，膝盖稍微弯曲。","在整个练习过程中保持背部挺直，核心肌群参与其中。","将手柄拉向您的身体，同时将您的躯干向右旋转。","动作结束时挤压背部肌肉。","慢慢回到起始位置，保持绳索的张力。","重复所需的重复次数，然后换边并用右手执行。"]},{"id":"0245","name":"cable underhand pulldown","nameZh":"绳索反手下拉","equipment":"cable","bodyPart":"back","target":"lats","imagePath":"exercises/images/0245-xBYcQHj.jpg","gifPath":"exercises/videos/0245-xBYcQHj.gif","instructionSteps":["调整缆绳机，使下拉杆位于您头部上方的高度。","坐在座椅上，用反手抓住下拉杆，双手分开的距离略大于肩宽。","保持背部挺直并稍微向后倾斜。","将杠铃向下拉向胸部，将肩胛骨挤压在一起。","在动作底部暂停片刻，然后慢慢将杠铃释放回起始位置。","重复所需的重复次数。"]},{"id":"0246","name":"cable upright row","nameZh":"绳索直立划船","equipment":"cable","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0246-cALKspW.jpg","gifPath":"exercises/videos/0246-cALKspW.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲，并用正手握住电缆附件。","在整个练习过程中保持背部挺直，核心肌群参与其中。","用肘部引导，将电缆附件笔直向上拉向下巴。","在顶部暂停片刻，将肩胛骨挤压在一起。","缓慢地将电缆附件放回起始位置。","重复所需的重复次数。"]},{"id":"0247","name":"cable wrist curl","nameZh":"绳索手腕弯举","equipment":"cable","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0247-LrV4s90.jpg","gifPath":"exercises/videos/0247-LrV4s90.gif","instructionSteps":["将直杆连接到低滑轮电缆机上。","面向机器站立，双脚分开与肩同宽。","反手握住杠铃，手掌朝上，双手与肩同宽。","将前臂放在长凳或垫子上，手腕悬在边缘上。","保持前臂静止，呼气并尽可能向上弯曲手腕。","在顶部暂停片刻，然后吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0248","name":"cambered bar lying row","nameZh":"弯杆仰卧划船","equipment":"barbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0248-R5swFnc.jpg","gifPath":"exercises/videos/0248-R5swFnc.gif","instructionSteps":["在地板上放一个杠铃，脸朝下躺在长凳上，胸部刚好离开边缘。","向下伸手，正手抓住杠铃，距离略宽于肩宽。","双腿伸直，双脚着地，伸展双臂，将杠铃提离地面。","将杠铃拉向胸部，将肩胛骨挤压在一起。","将杠铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0251","name":"chest dip","nameZh":"双杠臂屈伸","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0251-9WTm7dq.jpg","gifPath":"exercises/videos/0251-9WTm7dq.gif","instructionSteps":["将自己置于双杠上，双臂完全伸展，身体伸直。","弯曲肘部，降低身体，直到肩膀低于肘部。","伸直手臂，将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0253","name":"chin-ups (narrow parallel grip)","nameZh":"反握引体向上 (窄平行握距)","equipment":"body weight","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0253-G70mEAJ.jpg","gifPath":"exercises/videos/0253-G70mEAJ.gif","instructionSteps":["用狭窄的平行握距悬挂在引体向上杆上，手掌朝向您。","收紧背部肌肉，将身体拉向杠铃杆，保持肘部靠近身体。","继续拉，直到下巴位于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0257","name":"circles knee stretch","nameZh":"绕环膝拉伸","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0257-X7jbxra.jpg","gifPath":"exercises/videos/0257-X7jbxra.gif","instructionSteps":["双脚分开与肩同宽站立，双手放在臀部。","稍微弯曲膝盖，将脚跟抬离地面，用脚掌保持平衡。","保持膝盖弯曲，先顺时针旋转膝盖，然后逆时针旋转膝盖。","执行所需的重复运动次数。"]},{"id":"0258","name":"clock push-up","nameZh":"时钟俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0258-CMAxnsG.jpg","gifPath":"exercises/videos/0258-CMAxnsG.gif","instructionSteps":["从高平板支撑位置开始，双手直接放在肩膀下方，身体呈一条直线。","弯曲肘部，使肘部靠近身体两侧，将身体降低到地面。","当你下降时，将你的身体向左旋转，将你的左臂伸直到侧面。","向上推回到起始位置，同时将身体旋转到中心。","重复俯卧撑，这次将身体向右旋转，并将右臂向侧面伸出。","每次重复时继续交替进行。"]},{"id":"0259","name":"close-grip push-up","nameZh":"窄距俯卧撑","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0259-x6KpKpq.jpg","gifPath":"exercises/videos/0259-x6KpKpq.gif","instructionSteps":["从高位平板支撑开始，双手并拢，位于肩膀正下方。","收紧核心，将身体降低到地面，保持肘部靠近身体两侧。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"]},{"id":"0260","name":"cocoons","nameZh":"蚕茧式卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0260-SLKj2pX.jpg","gifPath":"exercises/videos/0260-SLKj2pX.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0262","name":"cross body crunch","nameZh":"交叉卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0262-rbu5UUb.jpg","gifPath":"exercises/videos/0262-rbu5UUb.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，将上半身抬离地面，然后扭转，使右肘靠近左膝盖。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","在另一侧重复，将左肘靠近右膝盖。","重复所需的重复次数。"]},{"id":"0267","name":"crunch (hands overhead)","nameZh":"卷腹 (手过头)","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0267-kjJ3VoQ.jpg","gifPath":"exercises/videos/0267-kjJ3VoQ.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双臂伸直至头顶上方。","收紧腹肌，将上半身抬离地面，向前向膝盖弯曲。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0271","name":"crunch (on stability ball)","nameZh":"卷腹 (在稳定球)","equipment":"stability ball","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0271-MCUhf1F.jpg","gifPath":"exercises/videos/0271-MCUhf1F.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","仰卧在球上，直到下背部得到支撑并且上半身与地板平行。","将双手放在脑后或放在胸前。","收紧腹肌，将上身抬向膝盖，躯干向前卷曲。","在动作的最高点暂停片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0272","name":"crunch (on stability ball, arms straight)","nameZh":"卷腹 (在稳定球, 手臂直)","equipment":"stability ball","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0272-Sn8wxAI.jpg","gifPath":"exercises/videos/0272-Sn8wxAI.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","仰卧在球上，直到下背部得到支撑并且上半身与地板平行。","将双手放在脑后或交叉放在胸前。","收紧腹肌，将上半身抬离球，将肩膀向臀部弯曲。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0274","name":"crunch floor","nameZh":"卷腹地面","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0274-TFqbd8t.jpg","gifPath":"exercises/videos/0274-TFqbd8t.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，将肩膀抬离地面，向前向膝盖弯曲。","在顶部停顿片刻，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0276","name":"dead bug","nameZh":"死虫式","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0276-iny3m5y.jpg","gifPath":"exercises/videos/0276-iny3m5y.gif","instructionSteps":["平躺，双臂伸向天花板。","弯曲膝盖，将双腿抬离地面，使臀部和膝盖形成 90 度角。","接合你的核心和下背部，将你的下背部压入地面。","慢慢地将右臂和左腿放低至地面，保持它们伸直并悬停在地板上方。","暂停片刻，然后回到起始位置。","用左臂和右腿重复该动作。","继续交替进行所需的重复次数。"]},{"id":"0277","name":"decline crunch","nameZh":"下斜卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0277-9Ap7miY.jpg","gifPath":"exercises/videos/0277-9Ap7miY.gif","instructionSteps":["躺在倾斜的长凳上，双脚固定，膝盖弯曲成 90 度角。","将双手放在脑后或放在胸前。","收紧腹肌，将上半身抬向膝盖，卷曲躯干。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0279","name":"decline push-up","nameZh":"下斜俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0279-i5cEhka.jpg","gifPath":"exercises/videos/0279-i5cEhka.gif","instructionSteps":["将双手放在地面上，距离略宽于肩宽，双脚放在稳定的表面上。","保持身体从头到脚呈一条直线，锻炼核心肌肉。","弯曲肘部，使胸部靠近地面，使胸部靠近地面。","推动手掌以伸展手臂并返回到起始位置。","重复所需的重复次数。"]},{"id":"0282","name":"decline sit-up","nameZh":"下斜仰卧起坐","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0282-QLL2gdc.jpg","gifPath":"exercises/videos/0282-QLL2gdc.gif","instructionSteps":["躺在倾斜的长凳上，双脚固定，膝盖弯曲。","将双手放在脑后或放在胸前。","收紧腹肌，将上半身抬离长凳，向前向膝盖弯曲。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0283","name":"diamond push-up","nameZh":"钻石俯卧撑","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0283-soIB2rj.jpg","gifPath":"exercises/videos/0283-soIB2rj.gif","instructionSteps":["从高位平板支撑开始，双手并拢，拇指和食指形成菱形。","让你的身体从头到脚保持一条直线，锻炼你的核心和臀部。","将胸部降低至双手形成的菱形，保持肘部靠近身体。","在底部暂停片刻，然后将自己推回到起始位置。","重复所需的重复次数。"]},{"id":"0284","name":"donkey calf raise","nameZh":"驴式提踵","equipment":"body weight","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0284-u5ESqzH.jpg","gifPath":"exercises/videos/0284-u5ESqzH.gif","instructionSteps":["将脚趾站立在升高的表面上，例如台阶或木块。","将双手放在稳定的支撑物上，例如墙壁或栏杆，以保持平衡。","尽可能高地抬高脚后跟，将身体重量转移到脚掌上。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0285","name":"dumbbell alternate biceps curl","nameZh":"哑铃交替肱二头肌弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0285-BU15nH4.jpg","gifPath":"exercises/videos/0285-BU15nH4.gif","instructionSteps":["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数，交替手臂。"]},{"id":"0286","name":"dumbbell alternate side press","nameZh":"哑铃交替侧推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0286-izMnLqz.jpg","gifPath":"exercises/videos/0286-izMnLqz.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高。","将一个哑铃推过头顶，同时将另一个哑铃保持在与肩同高的位置。","将按下的哑铃放回肩部高度，同时将另一个哑铃压过头顶。","继续交替进行所需的重复次数。"]},{"id":"0287","name":"dumbbell arnold press v. 2","nameZh":"哑铃阿诺德推举版本2","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0287-eOrFCnx.jpg","gifPath":"exercises/videos/0287-eOrFCnx.gif","instructionSteps":["坐在有背部支撑的长凳上，双手各握一个哑铃，与肩同高，手掌朝向身体，肘部弯曲。","向上推哑铃，直到手臂完全伸展，手掌朝前。","抬起时旋转手腕，使手掌在动作的最高点朝前。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0288","name":"dumbbell around pullover","nameZh":"哑铃环绕仰卧屈臂上拉","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0288-vi8EhoE.jpg","gifPath":"exercises/videos/0288-vi8EhoE.gif","instructionSteps":["平躺在长凳上，头放在一端，双脚牢牢踩在地上。","双手握住哑铃，将手臂伸直至胸部上方。","保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。","在底部停顿片刻，然后将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"0289","name":"dumbbell bench press","nameZh":"哑铃卧推","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0289-SpYC0Kp.jpg","gifPath":"exercises/videos/0289-SpYC0Kp.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","双手各握一个哑铃，手掌朝前，双臂伸至胸部上方。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","暂停片刻，然后将哑铃推回起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"0290","name":"dumbbell bench seated press","nameZh":"哑铃凳坐姿推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0290-3d7wHyd.jpg","gifPath":"exercises/videos/0290-3d7wHyd.gif","instructionSteps":["坐在长凳上，每只手各拿一个哑铃，放在大腿上。","向后倾斜，将哑铃放在胸部两侧，手掌朝前。","向上推哑铃，直到手臂完全伸展。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0291","name":"dumbbell bench squat","nameZh":"哑铃凳上深蹲","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0291-mnzcrIB.jpg","gifPath":"exercises/videos/0291-mnzcrIB.gif","instructionSteps":["将哑铃放在长凳前的地面上。","背对长凳站立，双脚与肩同宽。","弯曲膝盖和臀部，将自己降低到长凳上，保持胸部挺直，背部挺直。","一旦你的臀部接触到长凳，就用脚后跟站起来，回到起始位置。","重复所需的重复次数。"]},{"id":"0292","name":"dumbbell one arm bent-over row","nameZh":"哑铃单臂俯身划船","equipment":"dumbbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0292-C0MA9bC.jpg","gifPath":"exercises/videos/0292-C0MA9bC.gif","instructionSteps":["双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。","稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心肌群参与。","让哑铃垂直垂向地板，手臂完全伸展。","将哑铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0293","name":"dumbbell bent over row","nameZh":"哑铃俯身划船","equipment":"dumbbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0293-BJ0Hz5L.jpg","gifPath":"exercises/videos/0293-BJ0Hz5L.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个哑铃，手掌朝向身体。","臀部向前弯曲，保持背部挺直，核心肌群参与。","让你的手臂垂直垂向地板，肘部稍微弯曲。","将哑铃拉向胸部，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0294","name":"dumbbell biceps curl","nameZh":"哑铃肱二头肌弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0294-NbVPDMW.jpg","gifPath":"exercises/videos/0294-NbVPDMW.gif","instructionSteps":["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0295","name":"dumbbell clean","nameZh":"哑铃翻举","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0295-7Hg55JG.jpg","gifPath":"exercises/videos/0295-7Hg55JG.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","弯曲膝盖，降低臀部至下蹲位置，保持背部挺直，挺胸。","爆发性地伸展臀部和膝盖，通过脚后跟跳离地面。","当你跳跃时，耸肩并将哑铃拉向你的肩膀，保持它们靠近你的身体。","在与肩同高的位置抓住哑铃，肘部向前，手掌朝上。","通过反向运动将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0296","name":"dumbbell close-grip press","nameZh":"哑铃窄距推举","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0296-RxayqAZ.jpg","gifPath":"exercises/videos/0296-RxayqAZ.gif","instructionSteps":["坐在平坦的长凳上，每只手各拿一个哑铃，放在大腿上。","用你的大腿帮助举起哑铃，一次举起一个哑铃，这样你就可以将它们保持在与肩同宽的位置。","一旦与肩同宽，向前旋转手腕，使手掌背向自己。这将是您的起始位置。","当你吸气时，慢慢地将哑铃降低到你的身边，直到它们与你的胸部齐平。","呼气时，用三头肌将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"0297","name":"dumbbell concentration curl","nameZh":"哑铃集中弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0297-gvsWLQw.jpg","gifPath":"exercises/videos/0297-gvsWLQw.gif","instructionSteps":["坐在长凳上，双腿分开，一只手拿着哑铃，肘部放在大腿内侧。","完全伸展手臂并用反手握住哑铃。","保持上臂静止，呼气并将重量向上弯向肩膀，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0298","name":"dumbbell cross body hammer curl","nameZh":"哑铃交叉锤式弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0298-Qyk5J3p.jpg","gifPath":"exercises/videos/0298-Qyk5J3p.gif","instructionSteps":["站直，双手各持一个哑铃，手掌朝向身体。","保持肘部靠近躯干，上臂保持静止。","呼气并弯举哑铃，同时收缩二头肌，将哑铃穿过身体拉向对侧的肩膀。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0299","name":"dumbbell cuban press","nameZh":"哑铃古巴推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0299-QfAKy1G.jpg","gifPath":"exercises/videos/0299-QfAKy1G.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝下。","保持核心收紧，肘部稍微弯曲，将哑铃向上举过头顶，直到手臂完全伸展。","旋转手腕，使手掌朝前。","慢慢地将哑铃放回起始位置，同时将手腕旋转回起始位置。","重复所需的重复次数。"]},{"id":"0300","name":"dumbbell deadlift","nameZh":"哑铃硬拉","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0300-nUwVh7b.jpg","gifPath":"exercises/videos/0300-nUwVh7b.gif","instructionSteps":["双脚分开与肩同宽站立，脚趾指向前方。","双手各握一个哑铃，手掌朝向身体，手臂向下伸展。","弯曲臀部和膝盖，将哑铃向地面降低，同时保持背部挺直。","脚跟用力，伸展臀部和膝盖，将哑铃举回起始位置。","重复所需的重复次数。"]},{"id":"0301","name":"dumbbell decline bench press","nameZh":"哑铃下斜卧推","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0301-DwhEmmE.jpg","gifPath":"exercises/videos/0301-DwhEmmE.gif","instructionSteps":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","双手各握一个哑铃，双臂伸直至胸部上方，手掌朝前。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","将哑铃推回起始位置，充分伸展手臂。","重复所需的重复次数。"]},{"id":"0302","name":"dumbbell decline fly","nameZh":"哑铃下斜飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0302-xXm4nYq.jpg","gifPath":"exercises/videos/0302-xXm4nYq.gif","instructionSteps":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","双手各握一个哑铃，手掌相对，双臂伸至胸部上方。","将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后挤压胸部肌肉，使哑铃回到起始位置。","重复所需的重复次数。"]},{"id":"0303","name":"dumbbell decline hammer press","nameZh":"哑铃下斜锤式推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0303-1qrWgZ2.jpg","gifPath":"exercises/videos/0303-1qrWgZ2.gif","instructionSteps":["躺在倾斜的长凳上，双脚固定，头部低于臀部。","双手各握一个哑铃，手掌相对，双臂伸至胸部上方。","将哑铃降低到胸部两侧，保持肘部稍微弯曲。","将哑铃推回到起始位置，充分伸展手臂。","重复所需的重复次数。"]},{"id":"0304","name":"dumbbell decline shrug v. 2","nameZh":"哑铃下斜耸肩版本 2","equipment":"dumbbell","bodyPart":"back","target":"traps","imagePath":"exercises/images/0304-bRlbdjK.jpg","gifPath":"exercises/videos/0304-bRlbdjK.gif","instructionSteps":["设置一个 45 度角的下斜凳。","脸朝下躺在长凳上，胸部和腹部靠在长凳上。","每只手握住一个哑铃，手掌相对，双臂完全伸展。","保持手臂伸直，尽可能高地抬高肩膀，同时将肩胛骨挤压在一起。","保持收缩短暂停顿，然后将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0305","name":"dumbbell decline shrug","nameZh":"哑铃下斜耸肩","equipment":"dumbbell","bodyPart":"back","target":"traps","imagePath":"exercises/images/0305-cwsAI4G.jpg","gifPath":"exercises/videos/0305-cwsAI4G.gif","instructionSteps":["设置一个 45 度角的下斜凳。","脸朝下躺在长凳上，胸部和腹部靠在长凳上。","每只手握住一个哑铃，双臂完全伸向地板。","保持手臂伸直，将肩膀尽可能高地抬向耳朵。","保持收缩一会儿，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0306","name":"dumbbell decline triceps extension","nameZh":"哑铃下斜肱三头肌伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0306-OTgkHwR.jpg","gifPath":"exercises/videos/0306-OTgkHwR.gif","instructionSteps":["躺在斜凳上，头低于脚，双手各握一个哑铃，手掌相对。","充分伸展双臂，保持肘部靠近头部。","将哑铃慢慢降低到脑后，弯曲肘部。","暂停片刻，然后将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"0307","name":"dumbbell decline twist fly","nameZh":"哑铃下斜转体飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0307-reFHapa.jpg","gifPath":"exercises/videos/0307-reFHapa.gif","instructionSteps":["躺在倾斜的长凳上，头部低于臀部。","双手各握一个哑铃，手掌相对，双臂伸直越过胸部。","将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","当你降低哑铃时，扭转手腕，使手掌在动作底部朝前。","反转动作，将哑铃拉回到起始位置，在顶部挤压胸部肌肉。","重复所需的重复次数。"]},{"id":"0308","name":"dumbbell fly","nameZh":"哑铃飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0308-yz9nUhF.jpg","gifPath":"exercises/videos/0308-yz9nUhF.gif","instructionSteps":["平躺在长凳上，双手各握一个哑铃，手掌相对。","将手臂伸直越过胸部，肘部稍微弯曲。","保持肘部轻微弯曲，将手臂以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后反转动作，将哑铃拉回到起始位置。","重复所需的重复次数。"]},{"id":"0309","name":"dumbbell front raise v. 2","nameZh":"哑铃前平举版本 2","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0309-Rr7S3yg.jpg","gifPath":"exercises/videos/0309-Rr7S3yg.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。","保持背部挺直并启动核心肌群。","慢慢举起你面前的哑铃，手臂伸直，直到与肩齐平。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0310","name":"dumbbell front raise","nameZh":"哑铃前平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0310-3eGE2JC.jpg","gifPath":"exercises/videos/0310-3eGE2JC.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向大腿。","保持双臂伸直，呼气并将哑铃举至身前，直至与肩齐平。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0311","name":"dumbbell full can lateral raise","nameZh":"哑铃满罐式侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0311-AQ0mC4Y.jpg","gifPath":"exercises/videos/0311-AQ0mC4Y.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持背部挺直并启动核心肌群。","将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0312","name":"dumbbell hammer curl v. 2","nameZh":"哑铃锤式弯举版本 2","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0312-2NpxjC1.jpg","gifPath":"exercises/videos/0312-2NpxjC1.gif","instructionSteps":["站直，双手各持一个哑铃，手掌朝向躯干。","保持肘部靠近躯干，并旋转手掌，直到手掌朝前。","这将是您的起始位置。","现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","然后，吸气并慢慢开始将哑铃放回起始位置。","重复建议的重复次数。"]},{"id":"0313","name":"dumbbell hammer curl","nameZh":"锤式弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0313-slDvUAU.jpg","gifPath":"exercises/videos/0313-slDvUAU.gif","instructionSteps":["站直，双手各持一个哑铃，手掌朝向躯干。","保持肘部靠近躯干，并旋转手掌，直到手掌朝前。","这将是您的起始位置。","现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","然后，吸气并慢慢开始将哑铃放回起始位置。","重复建议的重复次数。"]},{"id":"0314","name":"dumbbell incline bench press","nameZh":"上斜哑铃推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0314-ns0SIbU.jpg","gifPath":"exercises/videos/0314-ns0SIbU.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，双脚平放在地上，背部紧贴长凳。","双手各握一个哑铃，掌心向前，将哑铃举至肩高。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","将哑铃推回起始位置，充分伸展手臂。","重复所需的重复次数。"]},{"id":"0315","name":"dumbbell incline biceps curl","nameZh":"哑铃上斜肱二头肌弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0315-F3xgbjF.jpg","gifPath":"exercises/videos/0315-F3xgbjF.gif","instructionSteps":["坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0316","name":"dumbbell incline breeding","nameZh":"哑铃上斜扩胸","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0316-B3Rxp6L.jpg","gifPath":"exercises/videos/0316-B3Rxp6L.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，背部靠在垫子上，双脚平放在地面上。","双手各握一个哑铃，正手握握，手掌朝前。","首先，双臂完全伸展，垂直于地面。","慢慢地将哑铃降低到胸部两侧，保持肘部呈 90 度角。","在底部暂停片刻，然后将哑铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0317","name":"dumbbell incline curl v. 2","nameZh":"哑铃上斜弯举版本 2","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0317-RaflbWD.jpg","gifPath":"exercises/videos/0317-RaflbWD.gif","instructionSteps":["坐在上斜凳上，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0318","name":"dumbbell incline curl","nameZh":"哑铃上斜弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0318-ae9UoXQ.jpg","gifPath":"exercises/videos/0318-ae9UoXQ.gif","instructionSteps":["将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心向前。","将上臂放在上斜凳上，让肘部下垂，充分伸展手臂。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0319","name":"dumbbell incline fly","nameZh":"哑铃上斜飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0319-ESOd5Pl.jpg","gifPath":"exercises/videos/0319-ESOd5Pl.gif","instructionSteps":["将上斜凳设置为 45 度角。","坐在长凳上，双手各握一个哑铃，手掌相对。","仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方。","将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","暂停片刻，然后挤压胸部肌肉，将哑铃拉回起始位置。","重复所需的重复次数。"]},{"id":"0320","name":"dumbbell incline hammer curl","nameZh":"哑铃上斜锤式弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0320-ByX0WxV.jpg","gifPath":"exercises/videos/0320-ByX0WxV.gif","instructionSteps":["坐在上斜凳上，每只手各握一个哑铃，手掌朝向躯干，手臂完全伸展。","背部靠在长凳上，双脚平放在地板上。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0321","name":"dumbbell incline hammer press","nameZh":"哑铃上斜锤式推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0321-PG1kcIb.jpg","gifPath":"exercises/videos/0321-PG1kcIb.gif","instructionSteps":["将上斜凳设置成 45 度角，坐在上面，双手各握一个哑铃，放在大腿上。","仰卧在长凳上，将哑铃置于与肩同高的位置，手掌相对。","将哑铃向上推离身体，直到手臂完全伸展。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0322","name":"dumbbell incline inner biceps curl","nameZh":"哑铃上斜内侧肱二头肌弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0322-LCtQPn8.jpg","gifPath":"exercises/videos/0322-LCtQPn8.gif","instructionSteps":["坐在上斜凳上，双手各握一个哑铃，手掌相对。","将上臂放在长凳上，让肘部下垂，手掌朝前。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0323","name":"dumbbell incline one arm lateral raise","nameZh":"哑铃上斜单臂侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0323-aTNKZiC.jpg","gifPath":"exercises/videos/0323-aTNKZiC.gif","instructionSteps":["坐在上斜凳上，一只手拿着哑铃，将其放在大腿上。","身体前倾，将上臂靠在大腿内侧。","将哑铃举到一侧，保持手臂稍微弯曲，手掌朝下。","继续抬起，直到手臂与地板平行。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0324","name":"dumbbell incline palm-in press","nameZh":"哑铃上斜手掌-在推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0324-OVLmUuL.jpg","gifPath":"exercises/videos/0324-OVLmUuL.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，双手各握一个哑铃，手掌相对。","将双脚牢牢踩在地面上，并保持背部挺直靠在长凳上。","从与肩同高的哑铃开始，肘部弯曲，手掌相对。","将哑铃向上推离身体，充分伸展手臂。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0325","name":"dumbbell incline raise","nameZh":"哑铃上斜抬举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0325-nxW6BkN.jpg","gifPath":"exercises/videos/0325-nxW6BkN.gif","instructionSteps":["坐在上斜凳上，每只手各拿一个哑铃，放在大腿上。","向后靠在长凳上，将哑铃举至肩高，手掌朝前。","背部靠在长凳上，呼气并将哑铃举过头顶，充分伸展双臂。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。","重复所需的重复次数。"]},{"id":"0326","name":"dumbbell incline rear lateral raise","nameZh":"哑铃上斜后侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0326-vYk8lqw.jpg","gifPath":"exercises/videos/0326-vYk8lqw.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，胸部靠在靠背上，双手各握一个哑铃。","双臂伸直向下，手掌相对。","保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0327","name":"dumbbell incline row","nameZh":"哑铃上斜划船","equipment":"dumbbell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0327-7vG5o25.jpg","gifPath":"exercises/videos/0327-7vG5o25.gif","instructionSteps":["设置一个 45 度角的上斜凳。","双手各握一个哑铃，坐在长凳上，胸部靠在斜坡上。","充分伸展双臂，让哑铃从肩膀上垂直垂下。","将哑铃拉向胸部，将肩胛骨挤压在一起。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0328","name":"dumbbell incline shoulder raise","nameZh":"哑铃上斜肩部抬举","equipment":"dumbbell","bodyPart":"chest","target":"serratus anterior","imagePath":"exercises/images/0328-6e2DcYX.jpg","gifPath":"exercises/videos/0328-6e2DcYX.gif","instructionSteps":["将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心朝下。","将哑铃放在大腿上，然后靠在长凳上。","用大腿帮助将哑铃举至肩膀高度，然后旋转手腕，使手掌朝前。","呼气，慢慢将哑铃举过头顶，保持肘部轻微弯曲。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回肩部高度。","重复所需的重复次数。"]},{"id":"0329","name":"dumbbell incline shrug","nameZh":"哑铃上斜耸肩","equipment":"dumbbell","bodyPart":"back","target":"traps","imagePath":"exercises/images/0329-JymLInS.jpg","gifPath":"exercises/videos/0329-JymLInS.gif","instructionSteps":["将上斜凳设置为 45 度角，坐在上面，双手各握一个哑铃。","将双脚平放在地面上，让双臂笔直下垂，手掌朝向身体。","保持手臂伸直，耸肩，尽可能高地靠近耳朵。","保持收缩一会儿，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0330","name":"dumbbell incline triceps extension","nameZh":"哑铃上斜肱三头肌伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0330-OVIKwsd.jpg","gifPath":"exercises/videos/0330-OVIKwsd.gif","instructionSteps":["坐在上斜凳上，双手各握一个哑铃，掌心向内。","将手臂完全伸过头顶，保持肘部靠近头部。","弯曲肘部，将哑铃降低到头后，保持上臂静止。","暂停片刻，然后伸展双臂将哑铃举回起始位置。","重复所需的重复次数。"]},{"id":"0331","name":"dumbbell incline twisted flyes","nameZh":"哑铃上斜扭转飞鸟","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0331-1PLE8e9.jpg","gifPath":"exercises/videos/0331-1PLE8e9.gif","instructionSteps":["将上斜凳摆成 45 度角，坐在上面，双手各握一个哑铃，掌心相对。","仰卧在长凳上，将哑铃推至起始位置，位于胸部正上方，双臂伸展。","将哑铃以宽弧线向两侧放低，直到感觉到胸部有拉伸感。","放下哑铃时，旋转手腕，使手掌在动作底部朝前。","反转动作，将哑铃拉回起始位置，在顶部将胸部肌肉挤压在一起。","重复所需的重复次数。"]},{"id":"0332","name":"dumbbell iron cross","nameZh":"哑铃十字支撑","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0332-cALkHHX.jpg","gifPath":"exercises/videos/0332-cALkHHX.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。","将双臂向两侧举起，直至与地面平行，与身体形成T字形。","暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0333","name":"dumbbell kickback","nameZh":"哑铃后摆臂屈伸","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0333-W6PxUkg.jpg","gifPath":"exercises/videos/0333-W6PxUkg.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将上臂靠近身体两侧，肘部弯曲成 90 度角。","将手臂向后伸直，在动作的最高点挤压三头肌。","暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0334","name":"dumbbell lateral raise","nameZh":"哑铃侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0334-DsgkuIt.jpg","gifPath":"exercises/videos/0334-DsgkuIt.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持背部挺直并启动核心肌群。","将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0335","name":"dumbbell lateral to front raise","nameZh":"哑铃侧向至前平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0335-xMjBKwn.jpg","gifPath":"exercises/videos/0335-xMjBKwn.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持背部挺直并启动核心肌群。","将手臂向两侧举起，直到与地面平行，保持肘部稍微弯曲。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","接下来，将手臂举到身前，直到它们与地面平行，再次保持肘部稍微弯曲。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0336","name":"dumbbell lunge","nameZh":"哑铃弓步","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0336-RRWFUcw.jpg","gifPath":"exercises/videos/0336-RRWFUcw.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","右脚向前迈出一步，将身体降低至弓步位置。","降低身体时保持背部挺直、挺胸。","推动右脚跟回到起始位置。","左腿重复上述动作。","交替腿进行所需的重复次数。"]},{"id":"0337","name":"dumbbell lying extension (across face)","nameZh":"哑铃仰卧伸展 (横跨面部)","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0337-L2V5Nan.jpg","gifPath":"exercises/videos/0337-L2V5Nan.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，头放在长凳的末端。","双手握住哑铃，双臂伸直至胸部上方，手掌相对。","保持上臂静止，将哑铃在头后呈弧形缓慢降低，直到前臂与地面平行。","暂停片刻，然后收缩三头肌，将哑铃带回起始位置。","重复所需的重复次数。"]},{"id":"0338","name":"dumbbell lying elbow press","nameZh":"哑铃仰卧肘推举","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0338-eOCOwIR.jpg","gifPath":"exercises/videos/0338-eOCOwIR.gif","instructionSteps":["平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直越过胸部。","弯曲肘部，将哑铃向肩膀方向降低，保持上臂静止。","在底部暂停片刻，然后伸展肘部将哑铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0339","name":"dumbbell lying femoral","nameZh":"哑铃仰卧股骨","equipment":"dumbbell","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0339-FkBIE6a.jpg","gifPath":"exercises/videos/0339-FkBIE6a.gif","instructionSteps":["平躺，双腿伸直，将哑铃放在下腹部。","弯曲膝盖，将哑铃拉向臀部，保持双脚平放在地面上。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0340","name":"dumbbell lying hammer press","nameZh":"哑铃仰卧锤式推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0340-7gdLIXa.jpg","gifPath":"exercises/videos/0340-7gdLIXa.gif","instructionSteps":["平躺在长凳上，双手各握一个哑铃，手掌相对，双臂伸直向上。","将哑铃放低至胸部两侧，保持肘部呈 90 度角。","将哑铃推回到起始位置，充分伸展手臂。","重复所需的重复次数。"]},{"id":"0341","name":"dumbbell lying one arm deltoid rear","nameZh":"哑铃仰卧单臂三角肌后","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0341-gSw59a4.jpg","gifPath":"exercises/videos/0341-gSw59a4.gif","instructionSteps":["脸朝下躺在平坦的长凳上，一只手握住哑铃，手掌朝内。","将手臂笔直向下伸向地板，保持靠近身体。","向上和向后举起手臂，将肩胛骨挤压向脊柱。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0342","name":"dumbbell lying one arm press v. 2","nameZh":"哑铃仰卧单臂推举版本 2","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0342-K3dIO25.jpg","gifPath":"exercises/videos/0342-K3dIO25.gif","instructionSteps":["平躺在长凳上，背部支撑，双脚平放在地面上。","一只手握住哑铃，手掌朝向脚部。","将手臂伸向天花板，保持肘部稍微弯曲。","慢慢地将哑铃向胸部方向降低，保持肘部靠近身体。","在底部暂停片刻，然后将哑铃推回到起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0343","name":"dumbbell lying one arm press","nameZh":"哑铃仰卧单臂推举","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0343-zGSIWQi.jpg","gifPath":"exercises/videos/0343-zGSIWQi.gif","instructionSteps":["平躺在长凳上，一只手拿着哑铃，双脚平放在地上。","将哑铃举至肩部水平，手掌朝前。","向上推哑铃，直到手臂完全伸展。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0344","name":"dumbbell lying one arm pronated triceps extension","nameZh":"哑铃仰卧单臂旋前肱三头肌伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0344-wyaqzOS.jpg","gifPath":"exercises/videos/0344-wyaqzOS.gif","instructionSteps":["平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。","一只手握住哑铃，手掌朝下，将手臂伸直至肩膀上方。","保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。","在底部停顿片刻，然后将手臂伸回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0345","name":"dumbbell lying one arm rear lateral raise","nameZh":"哑铃仰卧单臂后侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0345-KwFGiEP.jpg","gifPath":"exercises/videos/0345-KwFGiEP.gif","instructionSteps":["脸朝下躺在平坦的长凳上，一只手拿着哑铃，垂向地板。","保持手臂伸直，将哑铃举到一侧，远离身体。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0346","name":"dumbbell lying one arm supinated triceps extension","nameZh":"哑铃仰卧单臂旋后肱三头肌伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0346-zZlORz6.jpg","gifPath":"exercises/videos/0346-zZlORz6.gif","instructionSteps":["平躺在长凳上，背部和头部得到支撑，双脚平放在地面上。","一只手握住哑铃，反握，将手臂伸直至肩膀上方。","保持上臂静止，弯曲肘部，慢慢将哑铃降低到脑后。","在底部停顿片刻，然后将手臂伸回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0347","name":"dumbbell lying pronation","nameZh":"哑铃仰卧旋前","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0347-mym4hJo.jpg","gifPath":"exercises/videos/0347-mym4hJo.gif","instructionSteps":["平躺在长凳上，胸部朝下，双臂伸直向下，每只手各握一个哑铃。","旋转手掌，使手掌朝上。","保持上臂静止，呼气并弯曲哑铃，同时将手掌旋转至面朝下。","吸气并慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0348","name":"dumbbell lying rear lateral raise","nameZh":"哑铃仰卧后侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0348-53Ttlck.jpg","gifPath":"exercises/videos/0348-53Ttlck.gif","instructionSteps":["脸朝下躺在平坦的长凳上，双手各握一个哑铃，手掌相对。","将手臂伸直向下伸向地板，肘部保持轻微弯曲。","调动肩部肌肉，将手臂向两侧抬起，直到与地板平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0349","name":"dumbbell lying supination","nameZh":"哑铃仰卧旋后","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0349-M2Pm3zj.jpg","gifPath":"exercises/videos/0349-M2Pm3zj.gif","instructionSteps":["平躺在长凳上，双脚平放在地上。","每只手握住一个哑铃，手掌朝上，双臂完全伸展。","保持上臂不动，收缩前臂，将哑铃向肩膀方向卷曲。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0350","name":"dumbbell lying supine curl","nameZh":"哑铃仰卧仰卧弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0350-KUaZst7.jpg","gifPath":"exercises/videos/0350-KUaZst7.gif","instructionSteps":["平躺在长凳上，双手各握一个哑铃，手掌朝上，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0351","name":"dumbbell lying triceps extension","nameZh":"哑铃仰卧肱三头肌伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0351-mpKZGWz.jpg","gifPath":"exercises/videos/0351-mpKZGWz.gif","instructionSteps":["平躺在长凳上，双手各握一个哑铃，手掌相对。","将手臂伸直越过胸部，保持肘部靠近身体。","将哑铃向前额方向降低，弯曲肘部。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"]},{"id":"0352","name":"dumbbell neutral grip bench press","nameZh":"哑铃中立握距卧推","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0352-pP8wP2P.jpg","gifPath":"exercises/videos/0352-pP8wP2P.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","每只手握一个哑铃，中立握法（手掌相对），双臂伸直越过胸部。","慢慢地将哑铃降低到胸部，保持肘部靠近身体。","在底部停顿片刻，然后将哑铃推回起始位置，完全伸展手臂。","重复所需的重复次数。"]},{"id":"0353","name":"dumbbell one arm concentration curl (on stability ball)","nameZh":"哑铃单臂集中弯举 (在稳定球)","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0353-k5IpyHg.jpg","gifPath":"exercises/videos/0353-k5IpyHg.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，膝盖弯曲成 90 度角。","一只手握住哑铃，手掌朝上，手臂向下伸向地板。","将肘部放在大腿内侧、膝盖上方。","保持上臂静止，呼气并将哑铃向上弯向肩膀，同时收缩二头肌。","在动作的最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂重复。"]},{"id":"0354","name":"dumbbell one arm kickback","nameZh":"哑铃单臂后摆臂屈伸","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0354-bQy2Eni.jpg","gifPath":"exercises/videos/0354-bQy2Eni.gif","instructionSteps":["双脚分开与肩同宽站立，右手握住哑铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将右肘举至身体一侧，保持弯曲 90 度角。","将右臂向后伸直，在动作的最高点挤压三头肌。","慢慢地将哑铃放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0355","name":"dumbbell one arm lateral raise","nameZh":"哑铃单臂侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0355-n5cWCsI.jpg","gifPath":"exercises/videos/0355-n5cWCsI.gif","instructionSteps":["双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。","在整个练习过程中保持背部挺直，核心肌群参与其中。","将哑铃举至一侧，保持手臂伸直，手掌朝下。","继续抬起，直到手臂与地面平行。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0356","name":"dumbbell one arm lateral raise with support","nameZh":"哑铃单臂侧平举带辅助","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0356-Yg7MJAT.jpg","gifPath":"exercises/videos/0356-Yg7MJAT.gif","instructionSteps":["双脚分开与肩同宽站立，一手握住哑铃，手掌朝向身体。","将另一只手放在稳定的表面（例如长凳或墙壁）上以获得支撑。","保持背部挺直并启动核心肌群。","将哑铃向一侧举起，保持手臂伸直，手掌朝下。","继续抬起，直到手臂与地面平行。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0358","name":"dumbbell one arm reverse wrist curl","nameZh":"哑铃单臂反手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0358-BwSNDGt.jpg","gifPath":"exercises/videos/0358-BwSNDGt.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地面上。","一只手握住哑铃，正手握住，手掌朝下。","将前臂放在大腿上，手腕悬在边缘。","弯曲手腕，慢慢地将哑铃降低到地面。","在底部停顿片刻，然后慢慢地将手腕向上卷向身体。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0359","name":"dumbbell one arm reverse fly (with support)","nameZh":"哑铃单臂反向飞鸟 (带辅助)","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0359-e25F58f.jpg","gifPath":"exercises/videos/0359-e25F58f.gif","instructionSteps":["坐在长凳上，双脚平放在地上，背部挺直。","一只手握住哑铃，手掌朝内。","身体前倾，将空着的手放在长凳上以获得支撑。","保持手臂稍微弯曲并将其向侧面抬起，直到与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0360","name":"dumbbell one arm shoulder press v. 2","nameZh":"哑铃单臂肩推版本 2","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0360-1TkiAFK.jpg","gifPath":"exercises/videos/0360-1TkiAFK.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。","启动核心肌群，将哑铃垂直推过头顶，充分伸展手臂。","在顶部停顿片刻，然后慢慢将哑铃放回肩部水平。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0361","name":"dumbbell one arm shoulder press","nameZh":"哑铃单臂肩推","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0361-84RyJf8.jpg","gifPath":"exercises/videos/0361-84RyJf8.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝前。","向上推哑铃，直到手臂完全伸过头顶。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0362","name":"dumbbell one arm triceps extension (on bench)","nameZh":"哑铃单臂肱三头肌伸展 (在凳)","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0362-nAuHPcD.jpg","gifPath":"exercises/videos/0362-nAuHPcD.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","一手握住哑铃，另一只手放在长凳上以获得支撑。","将哑铃举过头顶，保持上臂靠近头部，肘部向前。","弯曲肘部，将哑铃降低到头后，保持上臂静止。","将手臂向后伸展至起始位置，完全伸直肘部。","重复所需的重复次数，然后换臂。"]},{"id":"0363","name":"dumbbell one arm upright row","nameZh":"哑铃单臂直立划船","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0363-6cKQC5E.jpg","gifPath":"exercises/videos/0363-6cKQC5E.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住哑铃，正握。","让哑铃悬挂在大腿前面，与手臂保持一定距离，手掌朝向身体。","保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0364","name":"dumbbell one arm wrist curl","nameZh":"哑铃单臂手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0364-q8aHNoF.jpg","gifPath":"exercises/videos/0364-q8aHNoF.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地面上。","一只手握住哑铃，反握，将前臂放在大腿上。","让你的手腕伸展，让哑铃向你的手指方向滚动。","慢慢地向后弯曲手腕，将哑铃拉向前臂。","重复所需的重复次数，然后换另一只手。"]},{"id":"0365","name":"dumbbell over bench neutral wrist curl","nameZh":"哑铃过凳中立手腕弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0365-BKa8dmT.jpg","gifPath":"exercises/videos/0365-BKa8dmT.gif","instructionSteps":["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。","将前臂放在长凳上，让手腕悬在长凳边缘。","保持上臂静止，呼气并将哑铃向上弯向肩膀。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0366","name":"dumbbell over bench one arm neutral wrist curl","nameZh":"哑铃过凳单臂中立手腕弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0366-IvV6C9M.jpg","gifPath":"exercises/videos/0366-IvV6C9M.gif","instructionSteps":["坐在长凳上，一只手拿着哑铃，手臂伸过长凳，手掌朝上。","保持上臂静止，将哑铃向肩膀弯曲，使手腕保持在中立位置。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0367","name":"dumbbell over bench one arm wrist curl","nameZh":"哑铃过凳单臂手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0367-KI1DjNN.jpg","gifPath":"exercises/videos/0367-KI1DjNN.gif","instructionSteps":["坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝下。","将前臂放在长凳上，手腕悬在长凳边缘。","慢慢向上弯曲手腕，将哑铃拉向前臂。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0368","name":"dumbbell over bench revers wrist curl","nameZh":"哑铃过凳反向手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0368-3tAXPQ6.jpg","gifPath":"exercises/videos/0368-3tAXPQ6.gif","instructionSteps":["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝下。","将前臂放在长凳上，让手腕悬在长凳边缘。","慢慢向上弯曲手腕，将哑铃拉向身体。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0369","name":"dumbbell over bench wrist curl","nameZh":"哑铃过凳手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0369-D1xYJAU.jpg","gifPath":"exercises/videos/0369-D1xYJAU.gif","instructionSteps":["坐在长凳上，前臂放在长凳上，手掌朝上，每只手各握一个哑铃。","让手腕悬在长凳边缘。","慢慢向上弯曲手腕，在动作的最高点挤压前臂。","暂停片刻，然后慢慢将手腕放回起始位置。","重复所需的重复次数。"]},{"id":"0370","name":"dumbbell peacher hammer curl","nameZh":"哑铃牧师凳锤式弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0370-F1KxjBa.jpg","gifPath":"exercises/videos/0370-F1KxjBa.gif","instructionSteps":["站直，双手各持一个哑铃，手掌朝向躯干。","保持肘部靠近躯干，并旋转手掌，直到手掌朝前。","这将是您的起始位置。","现在，保持上臂静止，呼气并卷曲哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","然后，吸气并慢慢开始将哑铃放回起始位置。","重复建议的重复次数。"]},{"id":"0371","name":"dumbbell plyo squat","nameZh":"哑铃爆发式深蹲","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0371-S4pwGlc.jpg","gifPath":"exercises/videos/0371-S4pwGlc.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。","弯曲膝盖并将臀部向后推，将身体降低至蹲姿。","当你到达深蹲底部时，向上爆发，跳离地面。","在空中时，快速改变双脚的位置，落地时另一只脚向前。","立即将身体放回蹲姿，然后重复跳跃，再次换脚。","每次跳跃时继续交替双脚的位置，达到所需的重复次数。"]},{"id":"0372","name":"dumbbell preacher curl","nameZh":"哑铃牧师凳弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0372-jivWf8n.jpg","gifPath":"exercises/videos/0372-jivWf8n.gif","instructionSteps":["坐在牧师弯举凳上，上臂放在垫子上，胸部靠在垫子上。","每只手握住一个哑铃，手掌朝上，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0373","name":"dumbbell pronate-grip triceps extension","nameZh":"哑铃旋前-握肱三头肌伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0373-bpJL2Qs.jpg","gifPath":"exercises/videos/0373-bpJL2Qs.gif","instructionSteps":["坐在长凳或椅子上，背部挺直，双脚平放在地面上。","双手握住哑铃，掌心朝下，双臂伸直举过头顶。","保持上臂靠近头部，肘部向前，弯曲肘部，慢慢将哑铃降低到脑后。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"]},{"id":"0374","name":"dumbbell prone incline curl","nameZh":"哑铃俯卧上斜弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0374-mwpPcr1.jpg","gifPath":"exercises/videos/0374-mwpPcr1.gif","instructionSteps":["将长凳调整至 45 度倾斜。","脸朝下躺在长凳上，胸部和腹部靠在长凳上。","每只手握住一个哑铃，手掌朝下，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0375","name":"dumbbell pullover","nameZh":"哑铃仰卧屈臂上拉","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0375-9XjtHvS.jpg","gifPath":"exercises/videos/0375-9XjtHvS.gif","instructionSteps":["平躺在长凳上，头放在一端，双脚放在地板上。","双手握住哑铃，将手臂伸直至胸部上方。","保持肘部轻微弯曲，慢慢地将哑铃放到脑后，直到感觉胸部和肩膀有拉伸感。","暂停片刻，然后将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"0376","name":"dumbbell raise","nameZh":"哑铃抬举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0376-c9MnDRp.jpg","gifPath":"exercises/videos/0376-c9MnDRp.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持背部挺直并启动核心肌群。","将手臂向两侧抬起，直到与地板平行，保持肘部稍微弯曲。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0377","name":"dumbbell rear delt row_shoulder","nameZh":"哑铃后三角肌划船_肩","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0377-EKXOMEh.jpg","gifPath":"exercises/videos/0377-EKXOMEh.gif","instructionSteps":["站立，双脚分开与肩同宽，膝盖稍微弯曲。","每只手握住一个哑铃，手掌朝向身体。","腰部向前弯曲，保持背部挺直，核心肌群参与。","将手臂伸直向下伸向地板，肘部稍微弯曲。","将哑铃向两侧举起，将肩胛骨挤压在一起。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0378","name":"dumbbell rear fly","nameZh":"哑铃后飞鸟","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0378-8DiFDVA.jpg","gifPath":"exercises/videos/0378-8DiFDVA.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将双臂笔直向下伸向地面，手掌相对。","保持肘部轻微弯曲，将手臂向两侧抬起，并将肩胛骨挤压在一起。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0379","name":"dumbbell rear lateral raise (support head)","nameZh":"哑铃后侧平举 (辅助头)","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0379-UzkLrem.jpg","gifPath":"exercises/videos/0379-UzkLrem.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将手臂向两侧举起，肘部保持轻微弯曲，直到与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0380","name":"dumbbell rear lateral raise","nameZh":"哑铃后侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0380-v1qBec9.jpg","gifPath":"exercises/videos/0380-v1qBec9.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","稍微弯曲膝盖，髋部向前转动，保持背部挺直，核心参与。","将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0381","name":"dumbbell rear lunge","nameZh":"哑铃后弓步","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0381-SSsBDwB.jpg","gifPath":"exercises/videos/0381-SSsBDwB.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","右脚向后退一步，将身体降低至弓步位置。","弯曲左膝并降低身体，直到左大腿与地面平行。","暂停片刻，然后推动左脚跟回到起始位置。","在另一侧重复，左脚向后退一步。"]},{"id":"0382","name":"dumbbell revers grip biceps curl","nameZh":"哑铃反向握肱二头肌弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0382-e4ojVhP.jpg","gifPath":"exercises/videos/0382-e4ojVhP.gif","instructionSteps":["站直，双手各握一个哑铃，手掌朝下，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0383","name":"dumbbell reverse fly","nameZh":"哑铃反向飞鸟","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0383-EAs3xL9.jpg","gifPath":"exercises/videos/0383-EAs3xL9.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将双臂伸直在身前，手掌相对。","保持肘部轻微弯曲，将手臂向两侧抬起，直到与地面平行。","在顶部暂停片刻，然后慢慢将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0384","name":"dumbbell reverse preacher curl","nameZh":"哑铃反向牧师凳弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0384-O8Aq69u.jpg","gifPath":"exercises/videos/0384-O8Aq69u.gif","instructionSteps":["坐在牧师凳上，上臂放在垫子上，胸部靠在支撑物上。","每只手握住一个哑铃，反握，手掌朝上。","保持上臂静止，呼气并弯曲哑铃，同时收缩二头肌。","继续弯举哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0385","name":"dumbbell reverse wrist curl","nameZh":"哑铃反手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0385-BLCvwr2.jpg","gifPath":"exercises/videos/0385-BLCvwr2.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地面上。","双手各握一个哑铃，正手握握，手掌朝下。","将前臂放在大腿上，让手腕悬在边缘。","慢慢向上弯曲手腕，将哑铃拉向身体。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0386","name":"dumbbell rotation reverse fly","nameZh":"哑铃旋转反向飞鸟","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0386-prbWx1D.jpg","gifPath":"exercises/videos/0386-prbWx1D.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，掌心向内。","稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。","将手臂向两侧举起，肘部保持轻微弯曲，直到与地板平行。","旋转手臂，使手掌朝下。","慢慢地将手臂放回起始位置。","重复所需的重复次数。"]},{"id":"0387","name":"dumbbell seated alternate front raise","nameZh":"哑铃坐姿交替前平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0387-gH5fRsC.jpg","gifPath":"exercises/videos/0387-gH5fRsC.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","每只手握住一个哑铃，手掌朝向身体，手臂向下伸展到身体两侧。","保持双臂伸直，将一只哑铃举至身前，直至其与地面平行。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","用另一只手臂重复上述步骤。","双臂交替进行所需的重复次数。"]},{"id":"0388","name":"dumbbell seated alternate press","nameZh":"哑铃坐姿交替推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0388-QT5Q0nK.jpg","gifPath":"exercises/videos/0388-QT5Q0nK.gif","instructionSteps":["坐在长凳上，双手各握一个哑铃，手掌朝前。","将哑铃举至肩部高度，肘部弯曲，手掌朝前。","将一只哑铃举过头顶，完全伸展手臂。","将哑铃放回至肩膀高度。","用另一只手臂重复上述步骤。","继续交替手臂进行所需的重复次数。"]},{"id":"0389","name":"dumbbell seated bench extension","nameZh":"哑铃坐姿凳伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0389-JhYSVwT.jpg","gifPath":"exercises/videos/0389-JhYSVwT.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","双手握住哑铃，将手臂伸直至头顶上方。","慢慢地将哑铃放到脑后，保持肘部靠近耳朵。","暂停片刻，然后将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"0390","name":"dumbbell seated biceps curl (on stability ball)","nameZh":"哑铃坐姿肱二头肌弯举 (在稳定球)","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0390-WgJnBH5.jpg","gifPath":"exercises/videos/0390-WgJnBH5.gif","instructionSteps":["坐在稳定球上，双脚平放在地面上，背部挺直。","每只手握住一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0391","name":"dumbbell seated curl","nameZh":"哑铃坐姿弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0391-TiaZTxx.jpg","gifPath":"exercises/videos/0391-TiaZTxx.gif","instructionSteps":["坐在长凳上，双脚平放在地面上，每只手各握一个哑铃，手掌朝前。","保持背部挺直，肘部靠近躯干。","呼气并将哑铃向上弯向肩膀，收缩二头肌。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0392","name":"dumbbell seated front raise","nameZh":"哑铃坐姿前平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0392-Ys97II0.jpg","gifPath":"exercises/videos/0392-Ys97II0.gif","instructionSteps":["坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。","保持背部挺直，核心参与。","将哑铃举到身前，手掌朝下，直到与肩同高。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0393","name":"dumbbell seated inner biceps curl","nameZh":"哑铃坐姿内侧肱二头肌弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0393-KXyoEtA.jpg","gifPath":"exercises/videos/0393-KXyoEtA.gif","instructionSteps":["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。","将上臂放在大腿上，让哑铃垂下。","保持上臂不动，通过收缩二头肌将哑铃向肩膀方向卷曲。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0394","name":"dumbbell seated kickback","nameZh":"哑铃坐姿后摆臂屈伸","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0394-en550rk.jpg","gifPath":"exercises/videos/0394-en550rk.gif","instructionSteps":["坐在长凳上，双脚平放在地上，每只手各握一个哑铃。","稍微弯曲膝盖，从臀部向前倾斜，保持背部挺直。","将上臂靠近身体两侧，并保持肘部弯曲成 90 度角。","将手臂向后伸直，在动作的最高点挤压三头肌。","暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0395","name":"dumbbell seated lateral raise v. 2","nameZh":"哑铃坐姿侧平举版本 2","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0395-hrrS0Ed.jpg","gifPath":"exercises/videos/0395-hrrS0Ed.gif","instructionSteps":["坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。","保持背部挺直，核心参与。","将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0396","name":"dumbbell seated lateral raise","nameZh":"哑铃坐姿侧平举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0396-hxyTtWj.jpg","gifPath":"exercises/videos/0396-hxyTtWj.gif","instructionSteps":["坐在长凳上，双脚平放在地上，每只手各拿一个哑铃，放在大腿上。","保持背部挺直，核心参与。","将哑铃举至身体两侧，肘部稍微弯曲，直到手臂与地面平行。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0397","name":"dumbbell seated neutral wrist curl","nameZh":"哑铃坐姿中立手腕弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0397-uJmK7Z1.jpg","gifPath":"exercises/videos/0397-uJmK7Z1.gif","instructionSteps":["坐在长凳上，双脚平放在地上，双手各握一个哑铃，手掌相对。","将前臂放在大腿上，让哑铃垂下。","保持手腕处于中立位置，将哑铃向上弯向肩膀。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0398","name":"dumbbell seated one arm kickback","nameZh":"哑铃坐姿单臂后摆臂屈伸","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0398-VQ3sNCn.jpg","gifPath":"exercises/videos/0398-VQ3sNCn.gif","instructionSteps":["坐在长凳上，双脚平放在地上，一手握住哑铃。","将躯干的腰部向前弯曲，保持背部挺直并与地面平行。","将手臂向后伸直，保持肘部靠近身体。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0399","name":"dumbbell seated one arm rotate","nameZh":"哑铃坐姿单臂旋转","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0399-7f2jsqP.jpg","gifPath":"exercises/videos/0399-7f2jsqP.gif","instructionSteps":["坐在长凳上，背部挺直，一只手握住哑铃，将其放在大腿上。","将哑铃举至肩膀高度，保持肘部靠近身体。","向外旋转前臂，远离身体，同时保持上臂静止。","在顶部停顿片刻，然后慢慢旋转前臂回到起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0400","name":"dumbbell seated one leg calf raise","nameZh":"哑铃坐姿单腿提踵","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0400-Ia7tumC.jpg","gifPath":"exercises/videos/0400-Ia7tumC.gif","instructionSteps":["坐在长凳或椅子上，双脚平放在地面上，将哑铃放在右大腿上。","将左腿伸直到身前，保持脚部弯曲。","将右脚掌放在升高的表面上，例如台阶或配重板。","使用小腿肌肉，尽可能高地抬高右脚跟。","在顶部暂停片刻，然后慢慢将脚跟放回起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0401","name":"dumbbell seated palms up wrist curl","nameZh":"哑铃坐姿手掌向上手腕弯举","equipment":"dumbbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0401-2dImyQ8.jpg","gifPath":"exercises/videos/0401-2dImyQ8.gif","instructionSteps":["坐在长凳上，双脚平放在地上，双手各握一个哑铃，掌心朝上。","将前臂放在大腿上，让手腕悬在边缘。","慢慢向上弯曲手腕，在动作的最高点挤压前臂。","暂停片刻，然后将手腕放回起始位置。","重复所需的重复次数。"]},{"id":"0402","name":"dumbbell seated preacher curl","nameZh":"哑铃坐姿牧师凳弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0402-7D5bgLT.jpg","gifPath":"exercises/videos/0402-7D5bgLT.gif","instructionSteps":["坐在牧师弯举凳上，双脚平放在地板上。","一只手握住哑铃，反手握住，将上臂靠在讲道垫上。","保持上臂静止，呼气并将哑铃向上弯向肩膀。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0403","name":"dumbbell seated revers grip concentration curl","nameZh":"哑铃坐姿反向握集中弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0403-lyKCLmK.jpg","gifPath":"exercises/videos/0403-lyKCLmK.gif","instructionSteps":["坐在长凳上，双脚平放在地上，一手握住哑铃，掌心朝上。","将肘部放在大腿内侧、膝盖上方。","保持上臂静止，呼气并将哑铃向肩膀弯曲。","在顶部暂停片刻，挤压你的二头肌。","吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0404","name":"dumbbell seated shoulder press (parallel grip)","nameZh":"哑铃坐姿肩推 (平行握距)","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0404-f1jf47L.jpg","gifPath":"exercises/videos/0404-f1jf47L.gif","instructionSteps":["坐在长凳上，双手各握一个哑铃，掌心向内。","将哑铃举至肩高，肘部弯曲，手掌朝前。","向上推哑铃，直到手臂完全伸过头顶。","在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。","重复所需的重复次数。"]},{"id":"0405","name":"dumbbell seated shoulder press","nameZh":"哑铃推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0405-znQUdHY.jpg","gifPath":"exercises/videos/0405-znQUdHY.gif","instructionSteps":["坐在长凳上，每只手各拿一个哑铃，放在大腿上。","将哑铃举至肩高，手掌朝前。","向上推哑铃，直到手臂完全伸过头顶。","在顶部停顿片刻，然后慢慢将哑铃放回肩部高度。","重复所需的重复次数。"]},{"id":"0406","name":"dumbbell shrug","nameZh":"哑铃耸肩","equipment":"dumbbell","bodyPart":"back","target":"traps","imagePath":"exercises/images/0406-NJzBsGJ.jpg","gifPath":"exercises/videos/0406-NJzBsGJ.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持手臂伸直，让哑铃垂在身体两侧。","尽可能高地抬高肩膀，就像试图用肩膀触碰耳朵一样。","保持收缩一秒钟，然后慢慢将肩膀放回起始位置。","重复所需的重复次数。"]},{"id":"0407","name":"dumbbell side bend","nameZh":"哑铃体侧屈","equipment":"dumbbell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0407-IpONWYv.jpg","gifPath":"exercises/videos/0407-IpONWYv.gif","instructionSteps":["站直，双脚分开与肩同宽，一手握住哑铃，让它垂在身侧。","保持背部挺直，核心肌群参与，慢慢地将腰部向哑铃的另一侧侧弯，在舒适的范围内尽可能降低重量。","暂停片刻，然后慢慢回到起始位置。","重复所需的重复次数，然后换边重复。"]},{"id":"0408","name":"dumbbell side lying one hand raise","nameZh":"哑铃侧卧一手抬举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0408-fTlkJop.jpg","gifPath":"exercises/videos/0408-fTlkJop.gif","instructionSteps":["侧躺，双腿伸直，用手臂支撑头部。","用你的上手握住哑铃，手掌朝下。","保持手臂伸直，将哑铃举至肩膀高度。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0409","name":"dumbbell single leg calf raise","nameZh":"哑铃单腿提踵","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0409-1kB3Wmk.jpg","gifPath":"exercises/videos/0409-1kB3Wmk.gif","instructionSteps":["站在台阶或平台的边缘，脚后跟悬垂，脚趾放在台阶上。","一手握住哑铃，另一只手放在墙壁或栏杆上以获得支撑。","尽可能高地抬高脚跟，将身体抬起到脚趾上。","在顶部停顿片刻，然后慢慢将脚跟放回到台阶下方。","重复所需的重复次数，然后换另一条腿。"]},{"id":"0410","name":"dumbbell single leg split squat","nameZh":"哑铃单腿分腿深蹲","equipment":"dumbbell","bodyPart":"upper legs","target":"quads","imagePath":"exercises/images/0410-qx4fgX7.jpg","gifPath":"exercises/videos/0410-qx4fgX7.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","一只脚向前迈出一步，调整双脚的位置，使前脚平放在地面上，后脚抬高在长凳或台阶上。","弯曲前膝盖和臀部，降低身体，保持后膝盖稍微弯曲，后脚跟离开地面。","继续降低，直到大腿前部与地面平行，然后通过前脚跟推回到起始位置。","重复所需的重复次数，然后换腿并重复。"]},{"id":"0411","name":"dumbbell single leg squat","nameZh":"哑铃单腿深蹲","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0411-H6ybluc.jpg","gifPath":"exercises/videos/0411-H6ybluc.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","向前伸展一条腿，并在整个练习过程中保持其离开地面。","弯曲站立的腿并降低身体，就像坐回椅子上一样。","保持挺胸、背部挺直。","在底部停顿片刻，然后用脚跟推动回到起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0413","name":"dumbbell squat","nameZh":"哑铃深蹲","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0413-HsvHqgf.jpg","gifPath":"exercises/videos/0413-HsvHqgf.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃放在身体两侧。","保持胸部挺直，核心收紧，弯曲膝盖和臀部，降低身体，就像坐回椅子上一样。","继续降低，直到大腿与地面平行，或者尽可能低。","在底部停顿片刻，然后推动脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0414","name":"dumbbell standing alternate overhead press","nameZh":"哑铃站姿交替过头推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0414-bBi35y3.jpg","gifPath":"exercises/videos/0414-bBi35y3.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。","将一只哑铃举过头顶，完全伸展手臂。","将哑铃放低至肩部水平。","用另一只手臂重复上述步骤。","继续交替手臂进行所需的重复次数。"]},{"id":"0415","name":"dumbbell standing alternate raise","nameZh":"哑铃站姿交替抬举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0415-SxHteRW.jpg","gifPath":"exercises/videos/0415-SxHteRW.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，手掌朝向身体。","保持背部挺直，核心肌群参与。","将一个哑铃举到一侧，保持手臂伸直，手掌朝下。","继续抬起，直到手臂与地面平行。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","用另一只手臂重复上述步骤。","双臂交替进行所需的重复次数。"]},{"id":"0416","name":"dumbbell standing biceps curl","nameZh":"哑铃站姿肱二头肌弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0416-3s4NnTh.jpg","gifPath":"exercises/videos/0416-3s4NnTh.gif","instructionSteps":["站直，双手各握一个哑铃，手掌朝前，双臂完全伸展。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0417","name":"dumbbell standing calf raise","nameZh":"哑铃站姿提踵","equipment":"dumbbell","bodyPart":"lower legs","target":"calves","imagePath":"exercises/images/0417-dPmaUaU.jpg","gifPath":"exercises/videos/0417-dPmaUaU.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","用小腿将脚跟抬离地面，尽可能高。","在顶部停顿片刻，然后慢慢降低脚后跟回到起始位置。","重复所需的重复次数。"]},{"id":"0418","name":"dumbbell standing concentration curl","nameZh":"哑铃站姿集中弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0418-7inpWch.jpg","gifPath":"exercises/videos/0418-7inpWch.gif","instructionSteps":["双脚分开与肩同宽站立，一手握住哑铃，手臂完全伸展，手掌朝内。","将另一只手放在大腿上以获得支撑。","保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0419","name":"dumbbell standing front raise above head","nameZh":"哑铃站姿前平举上方头","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0419-laVRfDf.jpg","gifPath":"exercises/videos/0419-laVRfDf.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","保持双臂伸直，将哑铃举至身前，举过头顶。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0420","name":"dumbbell standing kickback","nameZh":"哑铃站姿后摆臂屈伸","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0420-UmpPAAe.jpg","gifPath":"exercises/videos/0420-UmpPAAe.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个哑铃。","稍微弯曲膝盖，髋部向前转动，保持背部挺直。","将手臂向后伸直，在动作的最高点挤压三头肌。","暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0421","name":"dumbbell standing one arm concentration curl","nameZh":"哑铃站姿单臂集中弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0421-8fgqP5a.jpg","gifPath":"exercises/videos/0421-8fgqP5a.gif","instructionSteps":["站直，双脚分开与肩同宽，一手握住哑铃，掌心朝上。","将空着的手放在大腿上以获得支撑。","保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0422","name":"dumbbell standing one arm curl (over incline bench)","nameZh":"哑铃站姿单臂弯举 (上方上斜凳)","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0422-BIb1tGo.jpg","gifPath":"exercises/videos/0422-BIb1tGo.gif","instructionSteps":["双脚分开与肩同宽站立，一手握住哑铃，手掌朝前。","将另一只手放在倾斜的长凳上以获得支撑。","保持上臂静止，呼气，通过收缩二头肌将哑铃向肩膀弯曲。","在最高点停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换臂。"]},{"id":"0423","name":"dumbbell standing one arm extension","nameZh":"哑铃站姿单臂伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0423-BCUR88E.jpg","gifPath":"exercises/videos/0423-BCUR88E.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住哑铃。","将哑铃举过头顶，充分伸展手臂。","保持上臂靠近头部并垂直于地面。","慢慢地将哑铃放到脑后，弯曲肘部。","暂停片刻，然后将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"0424","name":"dumbbell standing one arm palm in press","nameZh":"哑铃站姿单臂手掌内推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0424-ocYc6Db.jpg","gifPath":"exercises/videos/0424-ocYc6Db.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住哑铃，与肩同高，手掌朝内。","启动你的核心并保持背部挺直。","向上推哑铃，直到手臂完全伸展。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0425","name":"dumbbell standing one arm reverse curl","nameZh":"哑铃站姿单臂反向弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0425-DU5Kkj2.jpg","gifPath":"exercises/videos/0425-DU5Kkj2.gif","instructionSteps":["站直，双脚分开与肩同宽，一只手握住哑铃，正握。","保持手臂完全伸展并靠近身体，手掌朝下。","慢慢地将哑铃向上弯向肩膀，保持上臂静止。","在顶部停顿片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数，然后换到另一只手臂。"]},{"id":"0426","name":"dumbbell standing overhead press","nameZh":"哑铃站姿过头推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0426-A6wtbuL.jpg","gifPath":"exercises/videos/0426-A6wtbuL.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝前。","向上推哑铃，直到手臂完全伸过头顶。","在顶部停顿片刻，然后慢慢将哑铃放回至肩部水平。","重复所需的重复次数。"]},{"id":"0427","name":"dumbbell standing palms in press","nameZh":"哑铃站姿手掌内推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0427-UilDHSs.jpg","gifPath":"exercises/videos/0427-UilDHSs.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，与肩同高，手掌朝内。","保持核心收紧，背部挺直，向上推哑铃，直到手臂完全伸过头顶。","在最高点暂停片刻，然后慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0428","name":"dumbbell standing preacher curl","nameZh":"哑铃站姿牧师凳弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0428-hq2hyDH.jpg","gifPath":"exercises/videos/0428-hq2hyDH.gif","instructionSteps":["站直，双脚分开与肩同宽，每只手各握一个哑铃，手掌朝前。","将上臂后部靠在牧师凳或上斜凳上，肘部稍微弯曲。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。","继续举起哑铃，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0429","name":"dumbbell standing reverse curl","nameZh":"哑铃站姿反向弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0429-0IgNjSM.jpg","gifPath":"exercises/videos/0429-0IgNjSM.gif","instructionSteps":["站直，双脚分开与肩同宽，双手各握一个哑铃，手掌朝向身体。","保持上臂静止，呼气并弯举哑铃，同时收缩二头肌。继续举重，直到二头肌完全收缩并且哑铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气并慢慢开始将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0430","name":"dumbbell standing triceps extension","nameZh":"哑铃站姿肱三头肌伸展","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0430-PdmaD0N.jpg","gifPath":"exercises/videos/0430-PdmaD0N.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住哑铃。","将哑铃举过头顶，保持手臂伸直。","弯曲肘部，将哑铃放到脑后，保持上臂静止。","将手臂向后伸展至起始位置。","重复所需的重复次数。"]},{"id":"0431","name":"dumbbell step-up","nameZh":"哑铃登阶","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0431-aXtJhlg.jpg","gifPath":"exercises/videos/0431-aXtJhlg.gif","instructionSteps":["站在长凳或台阶前，每只手各握一个哑铃，手掌朝向身体。","将右脚放在长凳或台阶上，确保整个脚与表面接触。","推动右脚跟，将身体抬起到长凳或台阶上，伸直右腿。","将左脚放在长凳或台阶上，完全直立。","左脚向后退一步，然后是右脚，回到起始位置。","重复所需的重复次数，然后换腿。"]},{"id":"0432","name":"dumbbell stiff leg deadlift","nameZh":"哑铃直腿硬拉","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0432-5eLRITT.jpg","gifPath":"exercises/videos/0432-5eLRITT.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","保持背部挺直，核心收紧，铰接臀部并将哑铃向地面降低，让膝盖稍微弯曲。","降低哑铃，直到感觉到腿筋拉伸，然后挤压臀肌并通过脚后跟推回到起始位置。","重复所需的重复次数。"]},{"id":"0433","name":"dumbbell straight arm pullover","nameZh":"哑铃直臂仰卧屈臂上拉","equipment":"dumbbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0433-i8BdLTK.jpg","gifPath":"exercises/videos/0433-i8BdLTK.gif","instructionSteps":["平躺在长凳上，头朝一端，双脚牢牢踩在地上。","双手握住哑铃，将手臂伸直至胸部上方。","保持手臂伸直，以弧线动作慢慢将哑铃降低到脑后。","暂停片刻，然后将哑铃举回到起始位置。","重复所需的重复次数。"]},{"id":"0434","name":"dumbbell straight leg deadlift","nameZh":"哑铃直腿硬拉","equipment":"dumbbell","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0434-oom75KC.jpg","gifPath":"exercises/videos/0434-oom75KC.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","保持背部挺直，核心收紧，以臀部为铰链，将哑铃向地面降低，让躯干向前倾斜。","继续降低哑铃，直到感觉到腿筋拉伸，保持膝盖稍微弯曲。","在底部暂停片刻，然后启动臀肌和腿筋，将躯干抬回到起始位置。","重复所需的重复次数。"]},{"id":"0436","name":"dumbbell tate press","nameZh":"哑铃泰特推举","equipment":"dumbbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0436-s5PdDyY.jpg","gifPath":"exercises/videos/0436-s5PdDyY.gif","instructionSteps":["坐在平坦的长凳上，双手各握一个哑铃，手掌相对。","将哑铃举至肩膀高度，然后旋转手腕，使手掌背向自己。","向上推哑铃，直到手臂完全伸展，然后将其放回至肩膀高度。","将手腕旋转回起始位置，然后重复所需的重复次数。"]},{"id":"0437","name":"dumbbell upright row","nameZh":"哑铃直立划船","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0437-ainizkb.jpg","gifPath":"exercises/videos/0437-ainizkb.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个哑铃，正握。","让哑铃悬挂在大腿前面，双臂完全伸展。","保持背部挺直，核心收紧，呼气，将哑铃笔直向上举至下巴，用肘部引导。","在顶部停顿片刻，然后吸气，慢慢将哑铃放回起始位置。","重复所需的重复次数。"]},{"id":"0438","name":"dumbbell w-press","nameZh":"哑铃 W 推举","equipment":"dumbbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0438-vmwLyCg.jpg","gifPath":"exercises/videos/0438-vmwLyCg.gif","instructionSteps":["坐在长凳上，双手各握一个哑铃，手掌朝前。","将哑铃举至肩高，肘部弯曲，手掌朝前。","向上推哑铃，直到手臂完全伸过头顶。","将哑铃放低至肩部高度。","重复所需的重复次数。"]},{"id":"0439","name":"dumbbell zottman curl","nameZh":"哑铃佐特曼弯举","equipment":"dumbbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0439-kXaIn5A.jpg","gifPath":"exercises/videos/0439-kXaIn5A.gif","instructionSteps":["站直，双手各持一个哑铃，手掌朝向身体。","保持肘部靠近躯干，并旋转手掌以面向前方。","将哑铃举至肩膀处，同时保持上臂静止。","在动作的最高点，旋转手腕，使手掌背向身体。","慢慢地将哑铃放回起始位置，将手掌旋转回面向身体。","重复所需的重复次数。"]},{"id":"0443","name":"elbow-to-knee","nameZh":"肘触膝","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0443-jvp6DiD.jpg","gifPath":"exercises/videos/0443-jvp6DiD.gif","instructionSteps":["首先平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，将上半身抬离地面，将右肘靠近左膝盖。","同时，将左膝移向右肘，形成扭转动作。","在顶部停顿片刻，然后慢慢降低上半身并将双腿伸展回到起始位置。","重复该动作，这次将左肘移向右膝，将右膝移向左肘。","继续交替进行所需的重复次数。"]},{"id":"0445","name":"ez barbell anti gravity press","nameZh":"曲杠抗重力推举","equipment":"ez barbell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0445-fprd84i.jpg","gifPath":"exercises/videos/0445-fprd84i.gif","instructionSteps":["首先，双脚分开与肩同宽站立，并用正手握住杠铃。","将杠铃举至肩膀高度，保持肘部稍微弯曲，手掌朝前。","将杠铃推过头顶，充分伸展双臂。","将杠铃降低回肩部高度，然后重复所需的重复次数。"]},{"id":"0446","name":"ez barbell close-grip curl","nameZh":"曲杠窄距弯举","equipment":"ez barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0446-V4ryaZa.jpg","gifPath":"exercises/videos/0446-V4ryaZa.gif","instructionSteps":["站直，双脚分开与肩同宽，反手握住杠铃，双手分开与肩同宽。","在整个运动过程中，保持肘部靠近躯干，上臂保持静止。","将杠铃向上弯向肩膀，收缩二头肌。","在顶部停顿片刻，然后慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0447","name":"ez barbell curl","nameZh":"曲杠弯举","equipment":"ez barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0447-6TG6x2w.jpg","gifPath":"exercises/videos/0447-6TG6x2w.gif","instructionSteps":["站直，双脚分开与肩同宽，反手握住 ez 杠铃，手掌朝上。","在整个运动过程中，保持肘部靠近躯干，上臂保持静止。","当你将杠铃向肩膀方向卷曲时呼气，收缩二头肌。","在顶部暂停片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0448","name":"ez barbell decline close grip face press","nameZh":"曲杠下斜窄距面部推举","equipment":"ez barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0448-DgZQ11d.jpg","gifPath":"exercises/videos/0448-DgZQ11d.gif","instructionSteps":["躺在倾斜的长凳上，头低于脚。","紧紧抓住 ez 杠铃，手掌相对。","将手臂伸直至胸部上方，保持肘部靠近身体。","弯曲肘部，将杠铃降低到前额。","暂停片刻，然后将杠铃推回到起始位置。","重复所需的重复次数。"]},{"id":"0449","name":"ez barbell incline triceps extension","nameZh":"曲杠上斜肱三头肌伸展","equipment":"ez barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0449-KyLtiLT.jpg","gifPath":"exercises/videos/0449-KyLtiLT.gif","instructionSteps":["设置一个 45 度角的上斜凳。","坐在长凳上，背部靠在垫子上，正手握住 ez 杠铃。","将手臂完全伸过头顶，保持肘部靠近头部。","弯曲肘部，将杠铃降低到头后，保持上臂静止。","暂停片刻，然后将手臂伸回到起始位置。","重复所需的重复次数。"]},{"id":"0450","name":"ez barbell jm bench press","nameZh":"曲杠 JM 卧推","equipment":"ez barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0450-hnOYgH3.jpg","gifPath":"exercises/videos/0450-hnOYgH3.gif","instructionSteps":["平躺在长凳上，双脚平放在地上，背部紧贴长凳。","正手握住杠铃，握距略宽于肩宽。","将杠铃降低到胸部，保持肘部靠近身体。","将杠铃推回到起始位置，完全伸展双臂。","重复所需的重复次数。"]},{"id":"0451","name":"ez barbell reverse grip curl","nameZh":"曲杠反握弯举","equipment":"ez barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0451-Y5X65IB.jpg","gifPath":"exercises/videos/0451-Y5X65IB.gif","instructionSteps":["站直，双脚分开与肩同宽，反手握住 ez 杠铃。","在整个练习过程中，保持肘部靠近躯干，上臂保持静止。","通过收缩二头肌将杠铃向上卷曲，同时呼气。","继续举起杠铃，直到二头肌完全收缩并且杠铃与肩部齐平。","挤压二头肌时，保持收缩位置短暂停顿。","吸气时慢慢开始将杠铃拉回起始位置。","重复所需的重复次数。"]},{"id":"0452","name":"ez barbell reverse grip preacher curl","nameZh":"曲杠反握牧师凳弯举","equipment":"ez barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0452-vBNyir7.jpg","gifPath":"exercises/videos/0452-vBNyir7.gif","instructionSteps":["坐在牧师凳上，胸部靠在垫子上，双脚平放在地板上。","反手抓住 ez 杠铃，双手与肩同宽。","将上臂放在垫子上，让前臂下垂。","保持上臂静止，呼气并将杠铃向上弯向肩膀。","在顶部停顿片刻，然后吸气，慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0453","name":"ez barbell seated triceps extension","nameZh":"曲杠坐姿肱三头肌伸展","equipment":"ez barbell","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0453-iaapw0g.jpg","gifPath":"exercises/videos/0453-iaapw0g.gif","instructionSteps":["坐在长凳上，背部挺直，双脚平放在地上。","正手握住 ez 杠铃，双手与肩同宽。","将杠铃举过头顶，充分伸展双臂。","保持上臂静止，弯曲肘部将杠铃降低到脑后。","暂停片刻，然后伸展双臂将杠铃举回起始位置。","重复所需的重复次数。"]},{"id":"0454","name":"ez barbell spider curl","nameZh":"曲杠蜘蛛弯举","equipment":"ez barbell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0454-Ye5Qxb0.jpg","gifPath":"exercises/videos/0454-Ye5Qxb0.gif","instructionSteps":["双脚分开与肩同宽站立，反手握住杠铃，手掌朝上。","将上臂放在牧师凳或稳定球上，让肘部下垂。","保持上臂静止，呼气并将杠铃向上弯向肩膀。","在顶部暂停片刻，挤压你的二头肌。","吸气并慢慢将杠铃放回起始位置。","重复所需的重复次数。"]},{"id":"0455","name":"finger curls","nameZh":"手指弯举","equipment":"barbell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0455-awG04cF.jpg","gifPath":"exercises/videos/0455-awG04cF.gif","instructionSteps":["坐在长凳上，双脚平放在地面上，反手握住杠铃，手掌朝上。","将前臂放在大腿上，让手腕悬在边缘。","慢慢地将手指向手掌弯曲，紧紧挤压杠铃。","保持收缩一会儿，然后慢慢松开手指回到起始位置。","重复所需的重复次数。"]},{"id":"0456","name":"flexion leg sit up (bent knee)","nameZh":"屈曲腿仰卧起坐 (屈膝)","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0456-AR0ig3o.jpg","gifPath":"exercises/videos/0456-AR0ig3o.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","同时，将双腿抬离地面，弯曲膝盖并将其拉向胸部。","在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。","重复所需的重复次数。"]},{"id":"0457","name":"flexion leg sit up (straight arm)","nameZh":"屈曲腿仰卧起坐 (直臂)","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0457-KZn52RC.jpg","gifPath":"exercises/videos/0457-KZn52RC.gif","instructionSteps":["平躺，双腿伸直，双臂伸直至头顶上方。","收紧腹肌，将上半身抬离地面，同时将双腿抬向胸部。","抬起上半身和腿部时，将双手伸向脚趾。","在顶部停顿片刻，然后慢慢降低上半身和双腿回到起始位置。","重复所需的重复次数。"]},{"id":"0458","name":"floor fly (with barbell)","nameZh":"地面飞鸟 (带杠铃)","equipment":"barbell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0458-neonEDL.jpg","gifPath":"exercises/videos/0458-neonEDL.gif","instructionSteps":["仰卧在地板上，膝盖弯曲，双脚平放在地面上。","正手握住杠铃，双臂伸直越过胸部。","慢慢地将杠铃向两侧放低，保持肘部轻微弯曲。","降低杠铃，直到手臂与地板平行，感觉胸部有拉伸感。","暂停片刻，然后挤压胸部肌肉，使杠铃回到起始位置。","重复所需的重复次数。"]},{"id":"0459","name":"flutter kicks","nameZh":"打水式踢腿","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0459-UVo2Qs2.jpg","gifPath":"exercises/videos/0459-UVo2Qs2.gif","instructionSteps":["平躺，双腿伸展，双手放在身体两侧。","收紧核心肌群并将双腿抬离地面约 6 英寸。","保持双腿伸直，交替将一条腿抬得比另一条腿稍高。","继续这个颤动动作达到所需的重复次数。"]},{"id":"0464","name":"front plank with twist","nameZh":"平板支撑","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0464-CosupLu.jpg","gifPath":"exercises/videos/0464-CosupLu.gif","instructionSteps":["从高平板支撑位置开始，双手直接放在肩膀下方，身体从头到脚成一条直线。","调动你的核心和臀部以保持稳定的位置。","将躯干向右旋转，抬起右臂并向天花板延伸。","扭转时保持臀部和腿部稳定。","保持片刻，然后回到起始位置。","在左侧重复扭转。","继续交替进行所需的重复次数。"]},{"id":"0466","name":"gironda sternum chin","nameZh":"吉隆达胸骨引体","equipment":"body weight","bodyPart":"back","target":"lats","imagePath":"exercises/images/0466-IL0JUxR.jpg","gifPath":"exercises/videos/0466-IL0JUxR.gif","instructionSteps":["面向高杠站立，双脚分开与肩同宽。","向上伸手，正手握住杠铃，握距略宽于肩宽。","悬挂在杠上，双臂完全伸展，身体伸直。","用你的背阔肌和二头肌将你的胸部拉向杠铃杆，以胸骨为主导。","在最高点暂停片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"0467","name":"gorilla chin","nameZh":"猩猩式引体","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0467-bmwlYvD.jpg","gifPath":"exercises/videos/0467-bmwlYvD.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲。","正手握住引体向上杆，握距略宽于肩宽。","悬挂在杠上，双臂完全伸展，手掌背向自己。","收紧核心肌群，将身体拉向杠铃杆，将下巴置于杠铃上方。","在顶部停顿片刻，然后慢慢将身体放回起始位置。","重复所需的重复次数。"]},{"id":"0469","name":"groin crunch","nameZh":"腹股沟卷腹","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0469-mWppALS.jpg","gifPath":"exercises/videos/0469-mWppALS.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，将双腿抬离地面，将膝盖靠近胸部。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0471","name":"handstand push-up","nameZh":"倒立俯卧撑","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0471-rQxwMxO.jpg","gifPath":"exercises/videos/0471-rQxwMxO.gif","instructionSteps":["找到一堵墙，背对墙，站在几英尺远的地方。","将双手放在地面上，与肩同宽，然后将脚踢到墙上，形成倒立姿势。","弯曲肘部，将头低向地面，保持身体呈一条直线。","用手推动并伸展双臂以返回到起始位置。","重复所需的重复次数。"]},{"id":"0472","name":"hanging leg raise","nameZh":"悬垂举腿","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0472-I3tsCnC.jpg","gifPath":"exercises/videos/0472-I3tsCnC.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","启动你的核心并将双腿抬起到你面前，保持伸直。","继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0473","name":"hanging pike","nameZh":"悬垂派克式","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0473-nuBF9MO.jpg","gifPath":"exercises/videos/0473-nuBF9MO.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","收紧核心肌群，将双腿向杠铃方向抬起，保持伸直。","继续抬起身体，直到身体形成“V”形，双腿与地面平行。","保持该姿势片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0474","name":"hanging straight leg hip raise","nameZh":"悬垂直腿髋部上提","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0474-pj0X0tF.jpg","gifPath":"exercises/videos/0474-pj0X0tF.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","启动你的核心并将双腿抬起到你面前，直到它们与地面平行。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0475","name":"hanging straight leg raise","nameZh":"悬垂直腿抬举","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0475-4Ml7QFO.jpg","gifPath":"exercises/videos/0475-4Ml7QFO.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，手掌背向自己。","启动你的核心并将双腿抬起到你面前，保持伸直。","继续抬起，直到双腿与地面平行或达到您可以舒适地达到的高度。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0476","name":"hanging straight twisting leg hip raise","nameZh":"悬垂直扭转腿髋部上提","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0476-Q6bvyen.jpg","gifPath":"exercises/videos/0476-Q6bvyen.gif","instructionSteps":["悬挂在引体向上杆上，双臂完全伸展，双腿伸直。","启动你的核心并将双腿抬向胸部，保持伸直。","一旦双腿与地面平行，将臀部向一侧扭转，将双腿移向一侧。","暂停片刻，然后回到起始位置。","重复这个动作，但这次将臀部扭向另一侧。","继续交替进行所需的重复次数。"]},{"id":"0484","name":"hip raise (bent knee)","nameZh":"髋部上提 (屈膝)","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0484-196HJGw.jpg","gifPath":"exercises/videos/0484-196HJGw.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在身体两侧，掌心朝下。","收紧核心肌群和臀肌，然后将臀部抬离地面，直到身体从膝盖到肩膀形成一条直线。","在顶部暂停片刻，然后慢慢将臀部放回起始位置。","重复所需的重复次数。"]},{"id":"0488","name":"hyperextension (on bench)","nameZh":"过度伸展 (在凳)","equipment":"body weight","bodyPart":"back","target":"spine","imagePath":"exercises/images/0488-zkgRrbK.jpg","gifPath":"exercises/videos/0488-zkgRrbK.gif","instructionSteps":["调整过度伸展凳，使臀部舒适地放在垫子上，并且双脚固定。","双臂交叉放在胸前或将双手放在脑后。","慢慢地将上半身降低到地面，同时保持背部挺直。","在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。","重复所需的重复次数。"]},{"id":"0489","name":"hyperextension","nameZh":"过度伸展","equipment":"body weight","bodyPart":"back","target":"spine","imagePath":"exercises/images/0489-zhMwOwE.jpg","gifPath":"exercises/videos/0489-zhMwOwE.gif","instructionSteps":["调整过度伸展凳，使大腿上部放在垫子上并且双脚固定。","双臂交叉放在胸前或将双手放在脑后。","将上半身压向地面，同时保持背部挺直。","在底部停顿片刻，然后抬起上半身，直到与双腿成一直线。","重复所需的重复次数。"]},{"id":"0490","name":"incline close-grip push-up","nameZh":"上斜窄距俯卧撑","equipment":"body weight","bodyPart":"upper arms","target":"triceps","imagePath":"exercises/images/0490-1YB40kg.jpg","gifPath":"exercises/videos/0490-1YB40kg.gif","instructionSteps":["将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。","将双腿伸到身后，放在脚掌上，身体从头到脚跟形成一条直线。","弯曲肘部，使肘部靠近身体两侧，将胸部降低到升高的表面。","在底部暂停片刻，然后伸直手臂将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0491","name":"incline leg hip raise (leg straight)","nameZh":"上斜腿髋部上提 (腿直)","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0491-eVxAzgz.jpg","gifPath":"exercises/videos/0491-eVxAzgz.gif","instructionSteps":["躺在倾斜的长凳上，背部平放在长凳上，双腿伸直在身前。","将双手放在长凳两侧以获得支撑。","收紧腹肌，将双腿抬离长凳，尽可能抬高双腿，同时保持伸直。","在顶部暂停片刻，然后慢慢将双腿放回起始位置。","重复所需的重复次数。"]},{"id":"0492","name":"incline push up depth jump","nameZh":"上斜俯卧撑深度跳","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0492-CB8WET1.jpg","gifPath":"exercises/videos/0492-CB8WET1.gif","instructionSteps":["找到一个较高的表面，例如长凳或台阶，并将双手与肩同宽放在边缘。","双脚向后退一步，保持身体从头到脚跟呈一条直线。","将胸部向水面边缘降低，弯曲肘部并保持身体对齐。","推动手掌以伸展手臂并返回到起始位置。","从水面边缘跳下，膝盖稍微弯曲，轻轻落地。","重复俯卧撑和深度跳跃达到所需的重复次数。"]},{"id":"0493","name":"incline push-up","nameZh":"上斜俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0493-B1EVP9F.jpg","gifPath":"exercises/videos/0493-B1EVP9F.gif","instructionSteps":["将双手放在较高的表面上，例如长凳或台阶上，双手之间的距离略宽于肩宽。","将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。","弯曲肘部，将胸部向升高的表面降低，保持身体呈一条直线。","在底部暂停片刻，然后伸直手臂将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0494","name":"incline reverse grip push-up","nameZh":"上斜反握俯卧撑","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0494-XaaRnRn.jpg","gifPath":"exercises/videos/0494-XaaRnRn.gif","instructionSteps":["将双手放在长凳或高架表面的边缘，距离略宽于肩宽。","将双腿伸到身后，放在脚掌上，从头到脚跟形成一条直线。","弯曲肘部，将胸部向长凳方向降低，使其靠近身体两侧。","在底部暂停片刻，然后伸展双臂将自己推回起始位置。","重复所需的重复次数。"]},{"id":"0495","name":"incline twisting sit-up","nameZh":"上斜扭转仰卧起坐","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0495-9ZGZuOD.jpg","gifPath":"exercises/videos/0495-9ZGZuOD.gif","instructionSteps":["设置一个 45 度角的上斜凳。","躺在长凳上，双脚固定在脚垫下。","将双手放在脑后或放在胸前。","收紧腹肌，将上半身抬离长凳，向前卷曲。","当你蜷缩起来时，将你的躯干扭转到一侧，将你的肘部拉向另一侧的膝盖。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复这个动作，这次将你的躯干扭转到另一侧。","继续交替进行所需的重复次数。"]},{"id":"0496","name":"inverse leg curl (bench support)","nameZh":"反向腿弯举 (凳辅助)","equipment":"body weight","bodyPart":"upper legs","target":"hamstrings","imagePath":"exercises/images/0496-ms7tjSG.jpg","gifPath":"exercises/videos/0496-ms7tjSG.gif","instructionSteps":["脸朝下躺在长凳上，臀部位于边缘，双腿伸直在身后。","抓住长凳以获得支撑。","保持上半身不动，弯曲膝盖并将双腿向臀部弯曲。","在顶部停顿片刻，然后慢慢将双腿伸展回起始位置。","重复所需的重复次数。"]},{"id":"0497","name":"inverted row v. 2","nameZh":"反向划船版本 2","equipment":"body weight","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0497-uX3sUBz.jpg","gifPath":"exercises/videos/0497-uX3sUBz.gif","instructionSteps":["在史密斯机上在腰部高度设置一根杠铃或使用悬挂训练器。","面向杠铃或悬吊训练器站立，用正手握法抓住它，双手与肩同宽。","双脚向前走，向后倾斜，直到身体呈轻微角度。","保持身体挺直，将胸部向上拉向杠铃或手柄，将肩胛骨挤压在一起。","在最高点暂停片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"0498","name":"inverted row with straps","nameZh":"反向划船带带子","equipment":"body weight","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0498-jdiExfW.jpg","gifPath":"exercises/videos/0498-jdiExfW.gif","instructionSteps":["在胸部高度设置悬挂训练器或带子。","面向锚点站立，并用正手握住手柄。","双脚向前走，向后倾斜，直到身体呈一定角度。","保持身体挺直并启动核心。","将胸部拉向手柄，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"0499","name":"inverted row","nameZh":"反向划船","equipment":"body weight","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0499-bZGHsAZ.jpg","gifPath":"exercises/videos/0499-bZGHsAZ.gif","instructionSteps":["在腰部高度设置一个杠铃或使用悬挂训练器。","面向杠铃或悬吊训练器站立，双脚分开与肩同宽。","正手握住杠铃或手柄，握距略宽于肩宽。","向后倾斜，保持身体挺直，脚后跟着地。","将胸部拉向杠铃或手柄，将肩胛骨挤压在一起。","在顶部停顿片刻，然后慢慢降低回到起始位置。","重复所需的重复次数。"]},{"id":"0500","name":"isometric wipers","nameZh":"等长雨刷式","equipment":"body weight","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0500-11wrviz.jpg","gifPath":"exercises/videos/0500-11wrviz.gif","instructionSteps":["首先平躺在垫子或长凳上。","将手臂伸直至两侧，与身体垂直。","启动你的核心并将双腿抬离地面，保持它们并拢并伸直。","慢慢地将双腿向一侧降低，目标是用脚接触地面，同时保持控制。","暂停片刻，然后用核心力量将双腿抬回到起始位置。","重复该动作，这次将双腿降低到另一侧。","继续交替进行所需的重复次数。"]},{"id":"0507","name":"jackknife sit-up","nameZh":"折刀式仰卧起坐","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0507-mbkgB44.jpg","gifPath":"exercises/videos/0507-mbkgB44.gif","instructionSteps":["平躺，双腿伸展，双臂举过头顶。","启动你的核心，同时抬起双腿和上半身，将双手伸向脚趾。","在顶部停顿片刻，然后慢慢放下双腿和上半身回到起始位置。","重复所需的重复次数。"]},{"id":"0508","name":"janda sit-up","nameZh":"杨达仰卧起坐","equipment":"body weight","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0508-1GPHRyK.jpg","gifPath":"exercises/videos/0508-1GPHRyK.gif","instructionSteps":["平躺，膝盖弯曲，双脚平放在地上。","将双手放在脑后，肘部朝外。","收紧腹肌，慢慢将上半身抬离地面，向前卷曲，直到躯干呈 45 度角。","在顶部停顿片刻，然后慢慢将上半身放回起始位置。","重复所需的重复次数。"]},{"id":"0513","name":"jump squat v. 2","nameZh":"跳跃深蹲版本 2","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0513-TDYiji6.jpg","gifPath":"exercises/videos/0513-TDYiji6.gif","instructionSteps":["双脚分开与肩同宽站立。","弯曲膝盖并将臀部向后推，将身体降低至蹲姿。","爆发力跳跃，充分伸展臀部和膝盖。","脚掌轻轻着地，然后立即将身体放回蹲姿。","重复所需的重复次数。"]},{"id":"0514","name":"jump squat","nameZh":"跳跃深蹲","equipment":"body weight","bodyPart":"upper legs","target":"glutes","imagePath":"exercises/images/0514-LIlE5Tn.jpg","gifPath":"exercises/videos/0514-LIlE5Tn.gif","instructionSteps":["双脚分开与肩同宽站立。","弯曲膝盖并将臀部向后推，将身体降低至蹲姿。","爆发性地跳离地面，伸展臀部、膝盖和脚踝。","在半空中时，快速将手臂向前伸以保持平衡。","脚掌轻轻落地，然后立即进入下一个重复动作。","重复所需的重复次数。"]},{"id":"0517","name":"kettlebell advanced windmill","nameZh":"壶铃高级风车式","equipment":"kettlebell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0517-Kal9cQQ.jpg","gifPath":"exercises/videos/0517-Kal9cQQ.gif","instructionSteps":["站立，双脚分开比肩宽，脚趾稍微向外。","右手握住壶铃，手臂伸过头顶，手掌朝前。","将左脚稍微向右旋转，并将重量转移到左腿上。","弯曲左膝并铰接在臀部，将躯干向左侧降低。","保持右臂伸过头顶，眼睛盯着壶铃。","当你降低躯干时，让右腿伸直，右脚稍微转动。","降低躯干，直到感觉到左腿筋拉伸并且右臂指向地面。","暂停片刻，然后启动核心并推动左脚跟返回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0518","name":"kettlebell alternating hang clean","nameZh":"壶铃交替悬垂翻举","equipment":"kettlebell","bodyPart":"lower arms","target":"forearms","imagePath":"exercises/images/0518-I4tibZG.jpg","gifPath":"exercises/videos/0518-I4tibZG.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。","稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。","让壶铃悬挂在身体前方，双臂完全伸展。","以一种流畅的动作，爆发性地伸展臀部，耸肩，并将壶铃拉向肩膀。","当壶铃到达肩膀高度时，旋转手腕并将壶铃抓住在架子位置，手掌朝内，壶铃放在前臂外侧。","将壶铃放回起始位置，然后用另一只手臂重复该动作。","继续交替手臂进行所需的重复次数。"]},{"id":"0519","name":"kettlebell alternating press on floor","nameZh":"壶铃交替推举在地面","equipment":"kettlebell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0519-7w6i0vE.jpg","gifPath":"exercises/videos/0519-7w6i0vE.gif","instructionSteps":["首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。","每只手握住一个壶铃，手掌朝向脚部，手臂伸直向天花板。","将一个壶铃向肩膀方向降低，同时保持另一个壶铃向上伸直。","将降低的壶铃按回到起始位置，同时将另一个壶铃向肩膀方向降低。","继续用每个壶铃交替进行推举动作，达到所需的重复次数。"]},{"id":"0520","name":"kettlebell alternating press","nameZh":"壶铃交替推举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0520-5KLbZWx.jpg","gifPath":"exercises/videos/0520-5KLbZWx.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。","将一只壶铃按过头顶，完全伸展手臂。","将壶铃降低至肩膀高度。","用另一只手臂重复上述步骤。","继续交替手臂进行所需的重复次数。"]},{"id":"0521","name":"kettlebell alternating renegade row","nameZh":"壶铃交替叛逆者划船","equipment":"kettlebell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0521-b9kqlBy.jpg","gifPath":"exercises/videos/0521-b9kqlBy.gif","instructionSteps":["从高平板支撑位置开始，双手握住壶铃，双脚分开与臀部同宽。","收紧核心肌群，保持身体从头到脚跟呈一条直线。","将一个壶铃向上拉向胸部，保持肘部靠近身体。","将壶铃放回起始位置，然后用另一只手臂重复该动作。","继续交替手臂进行所需的重复次数。"]},{"id":"0522","name":"kettlebell alternating row","nameZh":"壶铃交替划船","equipment":"kettlebell","bodyPart":"back","target":"upper back","imagePath":"exercises/images/0522-Ca76jUE.jpg","gifPath":"exercises/videos/0522-Ca76jUE.gif","instructionSteps":["双脚分开与肩同宽站立，膝盖稍微弯曲，双手各握一个壶铃，手掌朝向身体。","臀部向前弯曲，保持背部挺直，核心肌群参与。","将一个壶铃向上拉向胸部，保持肘部靠近身体并将肩胛骨挤压在一起。","将壶铃放回起始位置，然后用另一只手臂重复该动作。","继续交替手臂进行所需的重复次数。"]},{"id":"0523","name":"kettlebell arnold press","nameZh":"壶铃阿诺德推举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0523-UM8mgyG.jpg","gifPath":"exercises/videos/0523-UM8mgyG.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高，手掌朝向自己。","启动你的核心并将壶铃压过头顶，在伸展手臂时旋转手掌以面向前方。","在动作的最高点暂停，然后慢慢将壶铃放回起始位置。","重复所需的重复次数。"]},{"id":"0524","name":"kettlebell bent press","nameZh":"壶铃屈推举","equipment":"kettlebell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0524-kjE55n5.jpg","gifPath":"exercises/videos/0524-kjE55n5.gif","instructionSteps":["双脚分开与肩同宽站立，右手握住壶铃。","稍微弯曲膝盖，用右臂将壶铃压过头顶，保持肘部锁定。","将躯干向左旋转，将重量转移到左脚上。","弯曲左膝，将躯干压向地面，保持右臂伸过头顶。","当你下降时，眼睛盯着壶铃，胸部抬起。","左手接触地面后，将左脚推入并伸直左腿，推动臀部向前。","当你向前推动臀部时，用你的核心和右臂将壶铃推回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0525","name":"kettlebell bottoms up clean from the hang position","nameZh":"壶铃底部向上翻举从悬垂位置","equipment":"kettlebell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0525-4KJEpzb.jpg","gifPath":"exercises/videos/0525-4KJEpzb.gif","instructionSteps":["双脚分开与肩同宽站立，一只手握住壶铃，正手握住。","稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。","让壶铃垂在双腿之间，手臂完全伸展。","以一种流畅的动作，爆发性地伸展你的臀部和膝盖，同时将壶铃拉向你的肩膀。","当壶铃到达肩膀高度时，旋转手腕，使壶铃底部朝上。","在与肩同高的位置抓住壶铃，肘部弯曲，手掌朝上。","通过反向运动将壶铃降低回到起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0526","name":"kettlebell double alternating hang clean","nameZh":"壶铃双交替悬垂翻举","equipment":"kettlebell","bodyPart":"upper arms","target":"biceps","imagePath":"exercises/images/0526-a4F9Oyc.jpg","gifPath":"exercises/videos/0526-a4F9Oyc.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个壶铃，正手握住。","稍微弯曲膝盖，臀部向前转动，保持背部挺直，挺胸。","让壶铃垂直悬挂在身体前方。","以一种流畅的动作，爆发性地伸展臀部和膝盖，同时耸肩。","当壶铃上升时，将其拉向肩膀，保持肘部高且向两侧伸展。","在与肩同高的位置抓住壶铃，手掌朝内，肘部向前。","将壶铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0527","name":"kettlebell double jerk","nameZh":"壶铃双挺举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0527-tznL2Ad.jpg","gifPath":"exercises/videos/0527-tznL2Ad.gif","instructionSteps":["双脚分开与肩同宽站立，双手各握一个壶铃，与肩同高。","稍微弯曲膝盖并启动核心。","将壶铃压过头顶，充分伸展手臂。","弯曲膝盖并快速半蹲。","爆发性地伸展臀部和膝盖，将壶铃举过头顶。","锁定双臂，将壶铃举过头顶，膝盖稍微弯曲。","站直并回到起始位置。","重复所需的重复次数。"]},{"id":"0528","name":"kettlebell double push press","nameZh":"壶铃双借力推举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0528-I4KkPdl.jpg","gifPath":"exercises/videos/0528-I4KkPdl.gif","instructionSteps":["首先，双脚分开与肩同宽，每只手握住一个壶铃，与肩同高。","稍微弯曲膝盖并启动核心。","通过爆发性伸展臀部、膝盖和脚踝来开始运动，将壶铃举过头顶。","当壶铃到达顶部时，将它们完全压过头顶，锁定手臂。","弯曲肘部并将壶铃放回至肩膀高度，将壶铃放回起始位置。","重复所需的重复次数。"]},{"id":"0529","name":"kettlebell double snatch","nameZh":"壶铃双抓举","equipment":"kettlebell","bodyPart":"shoulders","target":"delts","imagePath":"exercises/images/0529-M74kdvm.jpg","gifPath":"exercises/videos/0529-M74kdvm.gif","instructionSteps":["双脚分开与肩同宽站立，每只手各握一个壶铃，放在大腿前面，与手臂保持一定距离。","稍微弯曲膝盖，臀部向前转动，保持背部平坦，挺胸。","以一种爆发力动作，伸展臀部、膝盖和脚踝，同时将壶铃拉向肩膀。","当壶铃达到肩膀水平时，旋转手腕并将壶铃击过头顶，充分伸展手臂。","将壶铃放回起始位置，然后重复所需的重复次数。"]},{"id":"0530","name":"kettlebell double windmill","nameZh":"壶铃双风车式","equipment":"kettlebell","bodyPart":"waist","target":"abs","imagePath":"exercises/images/0530-OaE7CpD.jpg","gifPath":"exercises/videos/0530-OaE7CpD.gif","instructionSteps":["双脚分开与肩同宽站立，右手握住壶铃。","将右臂伸过头顶，眼睛盯着壶铃。","左脚向左旋转 45 度，右脚向右旋转 90 度。","腰部向左弯曲，保持右臂伸过头顶。","将壶铃向地面降低，伸向左脚。","暂停片刻，然后启动核心并推动右脚返回起始位置。","重复所需的重复次数，然后换边。"]},{"id":"0531","name":"kettlebell extended range one arm press on floor","nameZh":"壶铃伸展幅度单臂推举在地面","equipment":"kettlebell","bodyPart":"chest","target":"pectorals","imagePath":"exercises/images/0531-rseLfH3.jpg","gifPath":"exercises/videos/0531-rseLfH3.gif","instructionSteps":["首先仰卧在地板上，膝盖弯曲，双脚平放在地面上。","一只手握住壶铃，手掌朝向脚部。","将手臂伸直向上伸向天花板，保持肘部锁定且手腕伸直。","慢慢地将壶铃放回起始位置，在整个运动过程中保持控制。","重复所需的重复次数，然后换到另一只手臂。"]}];
